source_excerpt:
\begin{prop}\ollabel{prop:extensionality-strictlinearorders}
If $<$ is a strict linear order on $A$, then:
\[
  (\forall a, b \in A)((\forall x \in A)(x < a \liff x < b) \lif a = b).
\]
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:extensionality-strictlinearorders}
$<$ हा $A$ वरील काटेकोर रेषीय क्रम असेल, तर:
\[
  (\forall a, b \in A)((\forall x \in A)(x < a \liff x < b) \lif a = b).
\]
\end{prop}

source_excerpt:
\begin{proof}
Suppose $(\forall x \in A)(x < a \liff x < b)$. If $a < b$, then $a <
a$, contradicting the fact that $<$ is irreflexive; so $a \nless b$.
Exactly similarly, $b \nless a$. So $a = b$, as $<$ is connected.
\end{proof}

target_excerpt:
\begin{proof}
$(\forall x \in A)(x < a \liff x < b)$ असे समजा. $a < b$ असेल, तर
$a < a$; पण $<$ अपरावर्ती आहे याच्याशी हे विसंगत आहे. म्हणून $a \nless b$.
अगदी त्याचप्रमाणे $b \nless a$. $<$ संयोजित असल्याने $a = b$.
\end{proof}

source_excerpt:
\begin{ex}
The graph $\tuple{V, E}$ with $V = \{1, 2, 3, 4\}$ and $E =
\{\tuple{1,1}, \allowbreak \tuple{1, 2}, \allowbreak \tuple{1, 3},
\allowbreak \tuple{2, 3}\}$ looks like this:
\begin{align*}
& \begin{tikzpicture}[->,node distance=2cm]
  \node[draw,circle] (A) {$1$};
  \node[draw,circle] (B) [right of=A] {$2$};
  \node[draw,circle] (C) [below of=B] {$3$};
  \node[draw,circle] (D) [right of=B] {$4$};
  \draw (A) to [loop above]  (A);
  \draw (A) to  (B);
  \draw (A) to  (C);
  \draw (B) to  (C);
  \end{tikzpicture}
\intertext{This is a different graph than $\tuple{V', E}$ with $V' =
  \{1, 2, 3\}$, which looks like this:}
& \begin{tikzpicture}[->,node distance=2cm]
  \node[draw,circle] (A) {$1$};
  \node[draw,circle] (B) [right of=A] {$2$};
  \node[draw,circle] (C) [below of=B] {$3$};
  \draw (A) to [loop above]  (A);
  \draw (A) to  (B);
  \draw (A) to  (C);
  \draw (B) to  (C);
  \end{tikzpicture}
\end{align*}
\end{ex}

target_excerpt:
\begin{ex}
$V = \{1, 2, 3, 4\}$ आणि $E =
\{\tuple{1,1}, \allowbreak \tuple{1, 2}, \allowbreak \tuple{1, 3},
\allowbreak \tuple{2, 3}\}$ असलेला $\tuple{V, E}$ हा आलेख असा दिसतो:
\begin{align*}
& \begin{tikzpicture}[->,node distance=2cm]
  \node[draw,circle] (A) {$1$};
  \node[draw,circle] (B) [right of=A] {$2$};
  \node[draw,circle] (C) [below of=B] {$3$};
  \node[draw,circle] (D) [right of=B] {$4$};
  \draw (A) to [loop above]  (A);
  \draw (A) to  (B);
  \draw (A) to  (C);
  \draw (B) to  (C);
  \end{tikzpicture}
\intertext{हा आलेख $V' = \{1, 2, 3\}$ असणाऱ्या $\tuple{V', E}$ या
  आलेखापेक्षा वेगळा आहे; तो असा दिसतो:}
& \begin{tikzpicture}[->,node distance=2cm]
  \node[draw,circle] (A) {$1$};
  \node[draw,circle] (B) [right of=A] {$2$};
  \node[draw,circle] (C) [below of=B] {$3$};
  \draw (A) to [loop above]  (A);
  \draw (A) to  (B);
  \draw (A) to  (C);
  \draw (B) to  (C);
  \end{tikzpicture}
\end{align*}
\end{ex}

source_excerpt:
\begin{prob}
  Consider the less-than-or-equal-to relation~$\le$ on the set $\{1,
  2, 3, 4\}$ as a graph and draw the corresponding diagram.
\end{prob}

target_excerpt:
\begin{prob}
  $\{1, 2, 3, 4\}$ या संचावरील लहान-किंवा-समान असण्याचा $\le$ संबंध
  आलेख म्हणून पाहा आणि त्याची आकृती काढा.
\end{prob}

$x \in A$ च्या उत्तरवर्तींना त्याची \emph{अपत्ये} असेही म्हणतात.
$y$ हा $x$ चा उत्तरवर्ती असेल, तर $x$ ला $y$ चा \emph{पूर्ववर्ती}
किंवा \emph{पालक} म्हणतो.

source_excerpt:
\begin{prop}
If $\tuple{A,\le}$ is a tree, then every $x \in A$ other than the root
has at most one predecessor.
\end{prop}

target_excerpt:
\begin{prop}
$\tuple{A,\le}$ हा वृक्ष असेल, तर मूळ वगळता प्रत्येक $x \in A$ ला
जास्तीत जास्त एक पूर्ववर्ती असतो.
\end{prop}

source_excerpt:
\begin{defn}
A tree $T = \tuple{A, \le}$ is said to be \emph{infinite} if $A$ is an
infinite set, and \emph{finite} otherwise. If $T$ is such that every
$x \in A$ has only finitely many successors, then we say that $T$ is
\emph{finitely branching}.
\end{defn}

target_excerpt:
\begin{defn}
$T = \tuple{A, \le}$ या वृक्षातील $A$ हा अनंत संच असेल, तर वृक्षाला
\emph{अनंत}, आणि अन्यथा \emph{सांत} म्हणतात. $T$ मधील प्रत्येक
$x \in A$ ला फक्त सांत संख्येने उत्तरवर्ती असतील, तर $T$ ला
\emph{सांत शाखनाचा} वृक्ष म्हणतात.
\end{defn}

source_excerpt:
The \emph{application} of $R$ to $A$ is $\funimage{R}{A} = \{y :
(\exists x \in A)Rxy\}$
\end{defn}

target_excerpt:
$R$ चा $A$ वर \emph{प्रयोग} म्हणजे $\funimage{R}{A} = \{y :
(\exists x \in A)Rxy\}$
\end{defn}

source_excerpt:
\begin{ex}
Let $S \subseteq \Int^2$ be the successor relation on~$\Int$, i.e.,
$S = \Setabs{\tuple{x, y} \in \Int^2}{x + 1 = y}$, so that $Sxy$ iff $x + 1 = y$.

The \emph{reflexive transitive closure} of $R$ is $R^* = R^+ \cup
\Id{A}$.
\end{defn}

\begin{ex}
Take the successor relation $S \subseteq \Int^2$. $S^2xy$ iff $x + 2 =
y$, $S^3xy$ iff $x + 3 = y$, etc. So $S^+xy$ iff $x + n = y$ for some
$n \geq 1$. In other words, $S^+xy$ iff $x < y$, and $S^*xy$ iff $x \le
y$.
\end{ex}

\begin{prob}
Show that the transitive closure of $R$ is in fact transitive.
\end{prob}

target_excerpt:
\begin{prob}
$R$ चे संक्रमक संवरण खरोखर संक्रमक आहे, हे दाखवा.
\end{prob}

source_excerpt:
\begin{explain}
We've already given examples of sets by listing their !!{element}s.
Let's discuss in more general terms how and when we can list the
!!{element}s of a set, even if that set is infinite.
\end{explain}

target_excerpt:
\begin{explain}
संचांचे !!{element}s यादीत देऊन आपण आधीच संचांची उदाहरणे दिली आहेत.
संच अनंत असला, तरी त्याच्या !!{element}s ची यादी कशी आणि कधी
देता येते, याची आता अधिक व्यापकपणे चर्चा करू.
\end{explain}

source_excerpt:
\begin{defn}
  \ollabel{defn:enumerable}
  A set~$A$ is !!{enumerable} iff it is empty or has an enumeration.
\end{defn}

target_excerpt:
\begin{defn}
  \ollabel{defn:enumerable}
  संच~$A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच,
  जेव्हा तो रिक्त असतो किंवा त्याचे प्रगणन असते.
\end{defn}

source_excerpt:
\begin{prob}
  Show that if $A$ and $B$ are !!{enumerable}, so is $A \cup B$. To do
  this, suppose there are !!{surjective} functions $f\colon \PosInt \to
  A$ and $g\colon \PosInt \to B$, and define !!a{surjective}
  function~$h\colon \PosInt \to A \cup B$ and prove that it is
  !!{surjective}. Also consider the cases where $A$ or~$B = \emptyset$.
\end{prob}

\begin{prob}
  Show that if $B \subseteq A$ and $A$ is !!{enumerable}, so is~$B$. To
  do this, suppose there is !!a{surjective} function $f\colon \PosInt \to
  A$. Define !!a{surjective} function~$g\colon \PosInt \to B$ and prove
  that it is !!{surjective}. What happens if $B = \emptyset$?
\end{prob}

target_excerpt:
\begin{prob}
  $B \subseteq A$ आणि $A$ हा !!{enumerable} असेल, तर~$B$ हाही
  गणनीय असतो, हे दाखवा. यासाठी एक !!a{surjective} फलन
  $f\colon \PosInt \to A$ आहे असे समजा. एक !!a{surjective}
  फलन~$g\colon \PosInt \to B$ परिभाषित करा आणि ते
  !!{surjective} आहे हे सिद्ध करा. $B = \emptyset$ असल्यास काय होते?
\end{prob}

source_excerpt:
\begin{prob}
  Show by induction on $n$ that if $A_1$, $A_2$, \dots, $A_n$ are all
  !!{enumerable}, so is $A_1 \cup \dots \cup A_n$. You may assume the
  fact that if two sets $A$ and~$B$ are !!{enumerable}, so is~$A \cup
  B$.
\end{prob}

\begin{cor}\ollabel{cor:enum-nat}
A set $A$ is !!{enumerable} iff it is empty or there is
!!a{surjective} function $f\colon \Nat \to A$.
\end{cor}

target_excerpt:
\begin{cor}\ollabel{cor:enum-nat}
संच $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच, जेव्हा
तो रिक्त असतो किंवा !!a{surjective} फलन $f\colon \Nat \to A$ असते.
\end{cor}

source_excerpt:
\begin{prop}\ollabel{prop:enum-bij}
If $f\colon \PosInt \to A$ is !!{surjective} (i.e., an enumeration
of~$A$), there is !!a{bijection} $g\colon Z \to A$ where $Z$ is
either~$\PosInt$ or $\{1, \dots, n\}$ for some~$n \in \PosInt$.
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:enum-bij}
$f\colon \PosInt \to A$ हे !!{surjective} असेल (म्हणजे~$A$
चे प्रगणन असेल), तर !!a{bijection} $g\colon Z \to A$ असते,
जेथे $Z$ हा~$\PosInt$ किंवा कोणत्या तरी~$n \in \PosInt$
साठी $\{1, \dots, n\}$ असतो.
\end{prop}

  फलन $g$ हे !!{surjective} आहे, कारण~$A$ मधील कोणताही घटक
  $f(1)$, $f(2)$, \dots{} यांमध्ये येतो ($f$ हे !!{surjective}
  असल्यामुळे), आणि म्हणून कधी ना कधी तो कोणत्या तरी~$i$
  साठीचे~$g(i)$ चे मूल्य होईल. ते !!{injective} ही आहे:
  $g(j) = g(i)$ असणारे $j < i$ असते, तर $g(i)$ हे मूल्य
  आधीच $g(1)$, \dots, $g(i-1)$ यांमध्ये आलेले असते;
  पण हे~$g$ च्या आपल्या व्याख्येविरुद्ध आहे.
\end{proof}

source_excerpt:
\begin{cor}\ollabel{cor:enum-nat-bij}
A set $A$ is !!{enumerable} iff it is empty or there is !!a{bijection}
$f\colon N \to A$ where either $N = \Nat$ or $N = \{0, \dots, n\}$ for
some $n \in \Nat$.
\end{cor}

target_excerpt:
\begin{cor}\ollabel{cor:enum-nat-bij}
संच $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच, जेव्हा
तो रिक्त असतो किंवा !!a{bijection} $f\colon N \to A$ असते,
जेथे $N = \Nat$ किंवा कोणत्या तरी $n \in \Nat$ साठी
$N = \{0, \dots, n\}$ असते.
\end{cor}

source_excerpt:
\begin{proof}
$A$ is !!{enumerable} iff $A$ is empty or there is !!a{surjective}
$f\colon \PosInt \to A$. By \olref{prop:enum-bij}, the latter holds
iff there is !!a{bijective} function~$f\colon Z \to A$ where $Z =
\PosInt$ or $Z = \{1, \dots, n\}$ for some $n \in \PosInt$. By the
same argument as in the proof of \olref{prop:enum-shift}, that in turn
is the case iff there is !!a{bijection} $g\colon N \to A$ where either
$N = \Nat$ or $N = \{0, \dots, n-1\}$.
\end{proof}

\begin{prob}
  According to \olref[sfr][siz][enm]{defn:enumerable}, a set $A$ is
  enumerable iff $A = \emptyset$ or there is !!a{surjective} $f\colon
  \PosInt \to A$.  It is also possible to define ``!!{enumerable} set''
  precisely by: a set is enumerable iff there is !!a{injective}
  function $g\colon A \to \PosInt$.  Show that the definitions are
  equivalent, i.e., show that there is !!a{injective} function
  $g\colon A \to \PosInt$ iff either $A = \emptyset$ or there is
  !!a{surjective} $f\colon \PosInt \to A$.
\end{prob}

\begin{prop}\ollabel{natsquaredenumerable}
$\Nat \times \Nat$ is !!{enumerable}.
\end{prop}

target_excerpt:
\begin{prop}\ollabel{natsquaredenumerable}
$\Nat \times \Nat$ हा !!{enumerable} आहे.
\end{prop}

source_excerpt:
This function $g$ is the \emph{inverse} of an enumeration of a set of
pairs. Such functions are called \emph{pairing functions}.
\end{explain}

target_excerpt:
हे फलन $g$ म्हणजे जोड्यांच्या संचाच्या एका प्रगणनाचे \emph{व्युत्क्रम}
आहे. अशा फलनांना \emph{जोडीकरण फलने} म्हणतात.
\end{explain}

source_excerpt:
\begin{prob}
Give an enumeration of the set of all non-negative rational numbers.
\end{prob}

target_excerpt:
\begin{prob}
सर्व ऋणेतर परिमेय संख्यांच्या संचाचे एक प्रगणन द्या.
\end{prob}

source_excerpt:
\begin{prob}
Recall from your introductory logic course that each possible truth
table expresses a truth function. In other words, the truth functions
are all functions from $\Bin^k \to \Bin$ for some~$k$. Prove that the
set of all truth functions is enumerable.
\end{prob}

target_excerpt:
\begin{prob}
प्रास्ताविक तर्कशास्त्राच्या अभ्यासक्रमातून आठवा की प्रत्येक संभाव्य
सत्यताकोष्टक एक सत्यता-फलन व्यक्त करतो. दुसऱ्या शब्दांत, सत्यता-फलने
म्हणजे कोणत्या तरी~$k$ साठी $\Bin^k \to \Bin$ अशी सर्व फलने आहेत.
सर्व सत्यता-फलनांचा संच गणनीय आहे, हे सिद्ध करा.
\end{prob}

source_excerpt:
\begin{prob}
Show that the set of all finite subsets of an arbitrary infinite
!!{enumerable} set is !!{enumerable}.
\end{prob}

target_excerpt:
\begin{prob}
कोणत्याही अनंत !!{enumerable} संचाच्या सर्व सांत उपसंचांचा संच
!!{enumerable} आहे, हे दाखवा.
\end{prob}

\begin{prob}
$\Nat$ च्या एखाद्या सांत उपसंचाचा पूरक असलेल्या $\Nat$ च्या उपसंचाला
\emph{सांत-पूरक} म्हणतात. म्हणजे, $A \subseteq \Nat$ हा सांत-पूरक
असतो तेव्हा आणि केवळ तेव्हाच, जेव्हा $\Nat\setminus A$ हा सांत असतो.
%READERNOTE{OLSIZ-002: गोठवलेल्या इंग्रजी वाक्यात “complement of a finite set Nat” अशी संबंधदर्शक शब्दांशिवाय अपूर्ण रचना आहे. लगेचचे सूत्र अभिप्रेत अर्थ ठरवते: Nat मधील एखाद्या सांत उपसंचाचा Nat-सापेक्ष पूरक. मराठी मजकुरात हा संबंध स्पष्ट केला आहे.}
$\Nat$ चे सांत आणि सांत-पूरक उपसंच हेच ज्याचे !!{element}s आहेत,
असा संच $I$ घ्या. $I$ हा !!{enumerable} आहे, हे दाखवा.
\end{prob}

source_excerpt:
\begin{prob}
Show that the !!{enumerable} union of !!{enumerable} sets is
!!{enumerable}. That is, whenever $A_1$, $A_2$, \dots{} are sets, and
each $A_i$ is !!{enumerable}, then the union $\bigcup_{i=1}^\infty
A_i$ of all of them is also !!{enumerable}. [NB: this is hard!]
\end{prob}

target_excerpt:
\begin{prob}
!!{enumerable} इतक्या !!{enumerable} संचांचा संयोग !!{enumerable} असतो,
हे दाखवा. म्हणजे, $A_1$, $A_2$, \dots{} हे संच असतील आणि प्रत्येक
$A_i$ हा !!{enumerable} असेल, तर त्या सर्वांचा संयोग
$\bigcup_{i=1}^\infty A_i$ हाही !!{enumerable} असतो. [टीप: हे कठीण आहे!]
\end{prob}

source_excerpt:
\begin{prob}
Let $f \colon A \times B \to \Nat$ be an arbitrary pairing function.
Show that the inverse of $f$ is an enumeration of $A \times B$.
\end{prob}

target_excerpt:
\begin{prob}
$f \colon A \times B \to \Nat$ हे कोणतेही जोडीकरण फलन असू द्या.
हे $f$ आच्छादकही असेल, तर त्याचे व्युत्क्रम $A \times B$ चे प्रगणन
आहे, हे दाखवा. सर्वसाधारण बाबतीत व्युत्क्रम केवळ फलनाच्या व्याप्तीवर
परिभाषित असते; यावरून जोड्यांचा हा संच गणनीय आहे, हे सिद्ध करा.
  %READERNOTE{MRSIZ-002: गोठवलेल्या इंग्रजी सरावात कोणत्याही एकास-एक जोडीकरण फलनाचे व्युत्क्रम थेट प्रगणन असल्याचा दावा आहे. फलन आच्छादक नसेल, तर त्याचे व्युत्क्रम सर्व नैसर्गिक संख्यांवर परिभाषित नसते. मराठी सरावात आच्छादक बाब आणि सामान्य अंशतः-व्युत्क्रम बाब वेगळ्या केल्या आहेत.}
\end{prob}

source_excerpt:
\begin{thm}
\ollabel{thm:nonenum-pownat}
$\Pow{\PosInt}$ is not !!{enumerable}.
\end{thm}

target_excerpt:
\begin{thm}
\ollabel{thm:nonenum-pownat}
$\Pow{\PosInt}$ हा !!{enumerable} नाही.
\end{thm}

source_excerpt:
\begin{prob}
Show that $\Pow{\Nat}$ is !!{nonenumerable} by a diagonal argument.
\end{prob}

target_excerpt:
\begin{prob}
कर्णरेषीय युक्तिवादाने $\Pow{\Nat}$ हा !!{nonenumerable} आहे, हे दाखवा.
\end{prob}

source_excerpt:
\begin{prob}
Show that if there is an !!{injective} function $g\colon B \to A$, and
$B$~is !!{nonenumerable}, then so is~$A$. Do this by showing how you
can use~$g$ to turn an enumeration of~$A$ into one of~$B$.
\end{prob}

target_excerpt:
\begin{prob}
$g\colon B \to A$ असे !!{injective} फलन असेल आणि $B$ हा
!!{nonenumerable} असेल, तर $A$ हाही अगणनीय असतो, हे दाखवा.
$g$ वापरून~$A$ चे प्रगणन~$B$ च्या प्रगणनात कसे रूपांतरित करता येते,
हे दाखवून सिद्धता द्या.
\end{prob}

source_excerpt:
So if $\Pow{\PosInt}$ were !!{enumerable}, $\Bin^\omega$ would be
!!{enumerable}.  But $\Bin^\omega$ is !!{nonenumerable}
(\olref[nen]{thm:nonenum-bin-omega}). Hence $\Pow{\PosInt}$ is
!!{nonenumerable}.
\end{proof}

\begin{prob}
Show that the set of all \emph{sets of} pairs of positive integers is
!!{nonenumerable} by a reduction argument.
\end{prob}

target_excerpt:
\begin{prob}
धन पूर्णांकांच्या जोड्यांच्या \emph{सर्व संचांचा} संच न्यूनीकरणाच्या
युक्तिवादाने !!{nonenumerable} आहे, हे दाखवा.
\end{prob}

source_excerpt:
\begin{prob}\label{sfr:siz:red:prob:nat-nat}
  Show that the set~$X$ of all functions $f\colon \Nat \to \Nat$ is
  !!{nonenumerable} by a reduction argument (Hint: give a surjective
  function from $X$ to~$\Bin^\omega$.)
\end{prob}

target_excerpt:
\begin{prob}\label{sfr:siz:red:prob:nat-nat}
  $f\colon \Nat \to \Nat$ अशा सर्व फलनांचा संच~$X$ हा न्यूनीकरणाच्या
  युक्तिवादाने !!{nonenumerable} आहे, हे दाखवा. (सूचना: $X$ पासून
  $\Bin^\omega$ कडे जाणारे आच्छादक फलन द्या.)
\end{prob}

source_excerpt:
\begin{prob}
Let $P$ be the set of functions from the set of positive
integers to the set $\{0\}$, and let $Q$ be the set of \emph{partial}
functions from the set of positive integers to the set $\{0\}$. Show
that $P$~is !!{enumerable} and $Q$~is not. (Hint: reduce the problem
of enumerating $\Bin^\omega$ to enumerating~$Q$).
\end{prob}

\begin{prob}
Let $S$ be the set of all !!{surjective} functions from the set of
positive integers to the set \{0,1\}, i.e., $S$ consists of all
!!{surjective}~$f\colon \PosInt \to \Bin$.  Show that $S$ is
!!{nonenumerable}.
\end{prob}

target_excerpt:
\begin{prob}
$S$ हा धन पूर्णांकांच्या संचापासून \{0,1\} या संचाकडे जाणाऱ्या सर्व
!!{surjective} फलनांचा संच असू द्या; म्हणजे, $S$ मध्ये सर्व
!!{surjective}~$f\colon \PosInt \to \Bin$ आहेत. $S$ हा
!!{nonenumerable} आहे, हे दाखवा.
\end{prob}

source_excerpt:
\begin{prob}
Show that the set~$\Real$ of all real numbers is !!{nonenumerable}.
\end{prob}

target_excerpt:
\begin{prob}
सर्व वास्तव संख्यांचा संच~$\Real$ हा !!{nonenumerable} आहे, हे दाखवा.
\end{prob}

source_excerpt:
\begin{defn}\ollabel{comparisondef}
  $A$ is \emph{equinumerous} with $B$, written $\cardeq{A}{B}$, iff
  there is !!a{bijection} $f \colon A \to B$.
\end{defn}

target_excerpt:
\begin{defn}\ollabel{comparisondef}
  $A$ हा $B$ शी \emph{तुल्यबल} असतो, आणि ते $\cardeq{A}{B}$ असे लिहितो,
  तेव्हा आणि केवळ तेव्हाच, जेव्हा $f \colon A \to B$ असे
  !!a{bijection} असते.
\end{defn}

source_excerpt:
\begin{proof}
We must show that equinumerosity is reflexive, symmetric, and
transitive. Let $A, B$, and $C$ be sets.

target_excerpt:
\begin{proof}
तुल्यबलता परावर्ती, सममित आणि संक्रमक आहे, हे दाखवावे लागेल. $A, B$
आणि $C$ हे संच असू द्या.

source_excerpt:
\begin{prop}
If $\cardeq{A}{B}$, then $A$ is !!{enumerable} if
and only if $B$ is.
\end{prop}

target_excerpt:
\begin{prop}
$\cardeq{A}{B}$ असेल, तर $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ
तेव्हाच $B$ तसा असतो.
\end{prop}

source_excerpt:
\begin{prob}
Show that if $\cardeq{A}{C}$ and $\cardeq{B}{D}$, and $A \cap B =
C \cap D = \emptyset$, then $\cardeq{A \cup B}{C \cup D}$.
\end{prob}

target_excerpt:
\begin{prob}
$\cardeq{A}{C}$ आणि $\cardeq{B}{D}$ असेल, आणि $A \cap B =
C \cap D = \emptyset$ असेल, तर $\cardeq{A \cup B}{C \cup D}$ आहे,
हे दाखवा.
\end{prob}

source_excerpt:
\begin{prob}
Show that if $A$ is infinite and !!{enumerable}, then
$\cardeq{A}{\Nat}$.
\end{prob}

target_excerpt:
\begin{prob}
$A$ हा अनंत आणि !!{enumerable} असेल, तर $\cardeq{A}{\Nat}$ आहे, हे
दाखवा.
\end{prob}

source_excerpt:
\begin{defn}
$A$ is \emph{no larger than}~$B$, written $\cardle{A}{B}$, iff there
is !!a{injection} $f \colon A \to B$.
\end{defn}

target_excerpt:
\begin{defn}
$A$ हा $B$ पेक्षा \emph{आकारमानाने मोठा नाही}, हे $\cardle{A}{B}$ असे
लिहितो, तेव्हा आणि केवळ तेव्हाच, जेव्हा $f \colon A \to B$ असे
!!a{injection} असते.
\end{defn}

source_excerpt:
\begin{defn}
$A$ is \emph{smaller than}~$B$, written $\cardless{A}{B}$, iff there
is !!a{injection}~$f\colon A \to B$ but no !!{bijection}~$g\colon A
\to B$, i.e., $\cardle{A}{B}$ and $\cardneq{A}{B}$.
\end{defn}

\begin{thm}[Cantor]\ollabel{thm:cantor}
$\cardless{A}{\Pow{A}}$, for any set $A$.
\end{thm}

target_excerpt:
\begin{thm}[कँटर]\ollabel{thm:cantor}
कोणत्याही संच $A$ साठी $\cardless{A}{\Pow{A}}$.
\end{thm}

\begin{proof}
$f(x) = \{x\}$ हे $f \colon A \to \Pow{A}$ असे !!a{injection} आहे;
कारण $x \neq y$ असेल, तर विस्तारात्मकतेमुळे $\{x\} \neq \{y\}$ सुद्धा
असते, आणि म्हणून $f(x) \neq f(y)$. त्यामुळे $\cardle{A}{\Pow{A}}$.

source_excerpt:
\begin{prob}
  Show that there cannot be !!a{injection} $g\colon \Pow{A} \to
  A$, for any set~$A$. Hint: Suppose $g\colon \Pow{A} \to A$ is
  !!{injective}. Consider $D = \Setabs{g(B)}{B \subseteq A \text{ and
  } g(B) \notin B}$. Let $x = g(D)$. Use the fact that $g$ is
  !!{injective} to derive a contradiction.
\end{prob}

target_excerpt:
\begin{prob}
  कोणत्याही संच~$A$ साठी $g\colon \Pow{A} \to
  A$ असे !!a{injection} असू शकत नाही, हे दाखवा. सूचना: $g\colon
  \Pow{A} \to A$ हे !!{injective} आहे, असे समजा. पुढील संच विचारात घ्या:
  $D = \Setabs{g(B)}{B \subseteq A \text{ आणि
  } g(B) \notin B}$. $x = g(D)$ असे घ्या. $g$ हे !!{injective} आहे हा
  हे तथ्य वापरून व्याघात मिळवा.
\end{prob}

source_excerpt:
\begin{defn}
  \ollabel{defn:enumerable}
  A set~$A$ is !!{enumerable} iff either $A = \emptyset$ or there is
  an enumeration of~$A$. We say that $A$ is !!{nonenumerable} iff $A$
  is not !!{enumerable}.
\end{defn}

target_excerpt:
\begin{defn}
  \ollabel{defn:enumerable}
  संच~$A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच, जेव्हा
  $A = \emptyset$ असते किंवा~$A$ चे प्रगणन असते. $A$ हा
  !!{nonenumerable} आहे असे म्हणतो तेव्हा आणि केवळ तेव्हाच, जेव्हा
  $A$ हा !!{enumerable} नसतो.
\end{defn}

source_excerpt:
\begin{explain}
So a set is !!{enumerable} iff it is empty or you can use an
enumeration to count out its !!{element}s.
\end{explain}

target_excerpt:
\begin{explain}
म्हणून संच रिक्त असेल किंवा प्रगणन वापरून त्यातील !!{element}s मोजता
येत असतील तेव्हा आणि केवळ तेव्हाच तो !!{enumerable} असतो.
\end{explain}

source_excerpt:
\begin{prob}
Show that a set $A$ is !!{enumerable} iff either $A = \emptyset$ or
there is !!a{surjection} $f\colon \Nat \to A$. Show that $A$ is
!!{enumerable} iff there is !!a{injection} $g\colon A \to \Nat$.
\end{prob}

target_excerpt:
\begin{prob}
संच $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच $A =
\emptyset$ असते किंवा $f\colon \Nat \to A$ असे !!a{surjection}
असते, हे दाखवा. $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच
$g\colon A \to \Nat$ असे !!a{injection} असते, हेही दाखवा.
\end{prob}

source_excerpt:
\begin{prob}
Show that if $A$ and $B$ are !!{enumerable}, so is $A \cup B$.
\end{prob}

target_excerpt:
\begin{prob}
$A$ आणि $B$ हे !!{enumerable} असतील, तर $A \cup B$ सुद्धा गणनीय
आहे, हे दाखवा.
\end{prob}

source_excerpt:
\begin{prob}
Show by induction on $n$ that if $A_1$, $A_2$, \dots, $A_n$ are all
!!{enumerable}, so is $A_1 \cup \dots \cup A_n$.
\end{prob}

target_excerpt:
\begin{prob}
$A_1$, $A_2$, \dots, $A_n$ हे सर्व !!{enumerable} असतील, तर
$A_1 \cup \dots \cup A_n$ सुद्धा गणनीय आहे, हे $n$ वरील गणिती विगमनाने
दाखवा.
\end{prob}

source_excerpt:
\begin{editorial}
  This section proves the non-enumerability of $\Bin^\omega$ and
  $\Pow{\Nat}$ using the definitions in \olref[enm-alt]{sec}, i.e.,
  requiring a bijection with~$\Nat$ instead of a surjection from
  $\PosInt$.
\end{editorial}

target_excerpt:
\begin{editorial}
  या विभागात \olref[enm-alt]{sec} मधील व्याख्या वापरून
  $\Bin^\omega$ आणि $\Pow{\Nat}$ यांची अगणनीयता सिद्ध केली आहे;
  म्हणजे $\PosInt$ पासून आच्छादन मागण्याऐवजी~$\Nat$ शी एकास-एक
  आच्छादन आवश्यक मानले आहे.
\end{editorial}

source_excerpt:
\begin{explain}
The set $\Nat$ of natural numbers is infinite. It is also trivially
!!{enumerable}. But the remarkable fact is that there are
\emph{!!{nonenumerable}} sets, i.e., sets which are not !!{enumerable}
(see \olref[sfr][siz][enm-alt]{defn:enumerable}).

\begin{thm}
\ollabel{thm:nonenum-pownat}
$\Pow{\Nat}$ is not !!{enumerable}.
\end{thm}

target_excerpt:
\begin{thm}
\ollabel{thm:nonenum-pownat}
$\Pow{\Nat}$ हा !!{enumerable} नाही.
\end{thm}

\begin{proof}
~$\Nat$ च्या उपसंचांची प्रत्येक यादी $\Nat$ चा कोणता तरी उपसंच वगळते
हे दाखवून आपण त्याच पद्धतीने पुढे जाऊ. म्हणून $\Nat$ च्या उपसंचांची
$N_0, N_1, N_2, \ldots$ अशी एखादी यादी आहे असे समजा. $D$ या संचाची
व्याख्या पुढीलप्रमाणे करतो: $n \in D$ तेव्हा आणि केवळ तेव्हाच, जेव्हा
$n \notin N_{n}$:
\[
D = \Setabs{n \in \Nat}{n \notin N_n}
\]
स्पष्टच $D\subseteq \Nat$. पण $D$ हा यादीत असू शकत नाही. कारण
रचनेनुसार $n \in D$ तेव्हा आणि केवळ तेव्हाच, जेव्हा $n\notin N_n$;
म्हणून कोणत्याही $n \in \Nat$ साठी $D \neq N_n$.
\end{proof}

source_excerpt:
\begin{prob}
Show that if there is an !!{injective} function $g\colon B \to A$, and
$B$~is !!{nonenumerable}, then so is~$A$. Do this by showing how you
can use~$g$ to turn an enumeration of~$A$ into one of~$B$.
\end{prob}

target_excerpt:
\begin{prob}
$g\colon B \to A$ असे !!{injective} फलन असेल आणि $B$ हा
!!{nonenumerable} असेल, तर $A$ हाही तसाच असतो, हे दाखवा. $g$ वापरून
~$A$ चे प्रगणन~$B$ च्या प्रगणनात कसे रूपांतरित करता येते हे दाखवून
सिद्धता द्या.
\end{prob}

source_excerpt:
So if $\Pow{\Nat}$ were !!{enumerable}, $\Bin^\omega$ would be
!!{enumerable}.  But $\Bin^\omega$ is !!{nonenumerable}
(\olref[nen-alt]{thm:nonenum-bin-omega}). Hence $\Pow{\Nat}$ is
!!{nonenumerable}.
\end{proof}

