source_excerpt:
\begin{prop}\ollabel{prop:extensionality-strictlinearorders}
If $<$ is a strict linear order on $A$, then:
\[
  (\forall a, b \in A)((\forall x \in A)(x < a \liff x < b) \lif a = b).
\]
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:extensionality-strictlinearorders}
$<$ हा $A$ वरील काटेकोर रेषीय क्रम असेल, तर:
\[
  (\forall a, b \in A)((\forall x \in A)(x < a \liff x < b) \lif a = b).
\]
\end{prop}

source_excerpt:
\begin{proof}
Suppose $(\forall x \in A)(x < a \liff x < b)$. If $a < b$, then $a <
a$, contradicting the fact that $<$ is irreflexive; so $a \nless b$.
Exactly similarly, $b \nless a$. So $a = b$, as $<$ is connected.
\end{proof}

target_excerpt:
\begin{proof}
$(\forall x \in A)(x < a \liff x < b)$ असे समजा. $a < b$ असेल, तर
$a < a$; पण $<$ अपरावर्ती आहे याच्याशी हे विसंगत आहे. म्हणून $a \nless b$.
अगदी त्याचप्रमाणे $b \nless a$. $<$ संयोजित असल्याने $a = b$.
\end{proof}

$x \in A$ च्या उत्तरवर्तींना त्याची \emph{अपत्ये} असेही म्हणतात.
$y$ हा $x$ चा उत्तरवर्ती असेल, तर $x$ ला $y$ चा \emph{पूर्ववर्ती}
किंवा \emph{पालक} म्हणतो.

source_excerpt:
\begin{prop}
If $\tuple{A,\le}$ is a tree, then every $x \in A$ other than the root
has at most one predecessor.
\end{prop}

target_excerpt:
\begin{prop}
$\tuple{A,\le}$ हा वृक्ष असेल, तर मूळ वगळता प्रत्येक $x \in A$ ला
जास्तीत जास्त एक पूर्ववर्ती असतो.
\end{prop}

source_excerpt:
\begin{defn}
A tree $T = \tuple{A, \le}$ is said to be \emph{infinite} if $A$ is an
infinite set, and \emph{finite} otherwise. If $T$ is such that every
$x \in A$ has only finitely many successors, then we say that $T$ is
\emph{finitely branching}.
\end{defn}

target_excerpt:
\begin{defn}
$T = \tuple{A, \le}$ या वृक्षातील $A$ हा अनंत संच असेल, तर वृक्षाला
\emph{अनंत}, आणि अन्यथा \emph{सांत} म्हणतात. $T$ मधील प्रत्येक
$x \in A$ ला फक्त सांत संख्येने उत्तरवर्ती असतील, तर $T$ ला
\emph{सांत शाखनाचा} वृक्ष म्हणतात.
\end{defn}

source_excerpt:
The \emph{application} of $R$ to $A$ is $\funimage{R}{A} = \{y :
(\exists x \in A)Rxy\}$
\end{defn}

target_excerpt:
$R$ चा $A$ वर \emph{प्रयोग} म्हणजे $\funimage{R}{A} = \{y :
(\exists x \in A)Rxy\}$
\end{defn}

source_excerpt:
\begin{ex}
Let $S \subseteq \Int^2$ be the successor relation on~$\Int$, i.e.,
$S = \Setabs{\tuple{x, y} \in \Int^2}{x + 1 = y}$, so that $Sxy$ iff $x + 1 = y$.

The \emph{reflexive transitive closure} of $R$ is $R^* = R^+ \cup
\Id{A}$.
\end{defn}

\begin{ex}
Take the successor relation $S \subseteq \Int^2$. $S^2xy$ iff $x + 2 =
y$, $S^3xy$ iff $x + 3 = y$, etc. So $S^+xy$ iff $x + n = y$ for some
$n \geq 1$. In other words, $S^+xy$ iff $x < y$, and $S^*xy$ iff $x \le
y$.
\end{ex}

\begin{prob}
Show that the transitive closure of $R$ is in fact transitive.
\end{prob}

target_excerpt:
\begin{prob}
$R$ चे संक्रमक संवरण खरोखर संक्रमक आहे, हे दाखवा.
\end{prob}

source_excerpt:
\begin{defn}
  \ollabel{defn:enumerable}
  A set~$A$ is !!{enumerable} iff it is empty or has an enumeration.
\end{defn}

target_excerpt:
\begin{defn}
  \ollabel{defn:enumerable}
  संच~$A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच,
  जेव्हा तो रिक्त असतो किंवा त्याचे प्रगणन असते.
\end{defn}

source_excerpt:
\begin{prob}
  Show that if $A$ and $B$ are !!{enumerable}, so is $A \cup B$. To do
  this, suppose there are !!{surjective} functions $f\colon \PosInt \to
  A$ and $g\colon \PosInt \to B$, and define !!a{surjective}
  function~$h\colon \PosInt \to A \cup B$ and prove that it is
  !!{surjective}. Also consider the cases where $A$ or~$B = \emptyset$.
\end{prob}

\begin{prob}
  Show that if $B \subseteq A$ and $A$ is !!{enumerable}, so is~$B$. To
  do this, suppose there is !!a{surjective} function $f\colon \PosInt \to
  A$. Define !!a{surjective} function~$g\colon \PosInt \to B$ and prove
  that it is !!{surjective}. What happens if $B = \emptyset$?
\end{prob}

target_excerpt:
\begin{prob}
  $B \subseteq A$ आणि $A$ हा !!{enumerable} असेल, तर~$B$ हाही
  गणनीय असतो, हे दाखवा. यासाठी एक !!a{surjective} फलन
  $f\colon \PosInt \to A$ आहे असे समजा. एक !!a{surjective}
  फलन~$g\colon \PosInt \to B$ परिभाषित करा आणि ते
  !!{surjective} आहे हे सिद्ध करा. $B = \emptyset$ असल्यास काय होते?
\end{prob}

source_excerpt:
\begin{cor}\ollabel{cor:enum-nat}
A set $A$ is !!{enumerable} iff it is empty or there is
!!a{surjective} function $f\colon \Nat \to A$.
\end{cor}

target_excerpt:
\begin{cor}\ollabel{cor:enum-nat}
संच $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच, जेव्हा
तो रिक्त असतो किंवा !!a{surjective} फलन $f\colon \Nat \to A$ असते.
\end{cor}

source_excerpt:
\begin{cor}\ollabel{cor:enum-nat-bij}
A set $A$ is !!{enumerable} iff it is empty or there is !!a{bijection}
$f\colon N \to A$ where either $N = \Nat$ or $N = \{0, \dots, n\}$ for
some $n \in \Nat$.
\end{cor}

target_excerpt:
\begin{cor}\ollabel{cor:enum-nat-bij}
संच $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच, जेव्हा
तो रिक्त असतो किंवा !!a{bijection} $f\colon N \to A$ असते,
जेथे $N = \Nat$ किंवा कोणत्या तरी $n \in \Nat$ साठी
$N = \{0, \dots, n\}$ असते.
\end{cor}

source_excerpt:
\begin{proof}
$A$ is !!{enumerable} iff $A$ is empty or there is !!a{surjective}
$f\colon \PosInt \to A$. By \olref{prop:enum-bij}, the latter holds
iff there is !!a{bijective} function~$f\colon Z \to A$ where $Z =
\PosInt$ or $Z = \{1, \dots, n\}$ for some $n \in \PosInt$. By the
same argument as in the proof of \olref{prop:enum-shift}, that in turn
is the case iff there is !!a{bijection} $g\colon N \to A$ where either
$N = \Nat$ or $N = \{0, \dots, n-1\}$.
\end{proof}

\begin{prob}
  According to \olref[sfr][siz][enm]{defn:enumerable}, a set $A$ is
  enumerable iff $A = \emptyset$ or there is !!a{surjective} $f\colon
  \PosInt \to A$.  It is also possible to define ``!!{enumerable} set''
  precisely by: a set is enumerable iff there is !!a{injective}
  function $g\colon A \to \PosInt$.  Show that the definitions are
  equivalent, i.e., show that there is !!a{injective} function
  $g\colon A \to \PosInt$ iff either $A = \emptyset$ or there is
  !!a{surjective} $f\colon \PosInt \to A$.
\end{prob}

\begin{prob}
Show that if $\cardeq{A}{C}$ and $\cardeq{B}{D}$, and $A \cap B =
C \cap D = \emptyset$, then $\cardeq{A \cup B}{C \cup D}$.
\end{prob}

target_excerpt:
\begin{prob}
$\cardeq{A}{C}$ आणि $\cardeq{B}{D}$ असेल, आणि $A \cap B =
C \cap D = \emptyset$ असेल, तर $\cardeq{A \cup B}{C \cup D}$ आहे,
हे दाखवा.
\end{prob}

source_excerpt:
\begin{defn}
  \ollabel{defn:enumerable}
  A set~$A$ is !!{enumerable} iff either $A = \emptyset$ or there is
  an enumeration of~$A$. We say that $A$ is !!{nonenumerable} iff $A$
  is not !!{enumerable}.
\end{defn}

target_excerpt:
\begin{defn}
  \ollabel{defn:enumerable}
  संच~$A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच, जेव्हा
  $A = \emptyset$ असते किंवा~$A$ चे प्रगणन असते. $A$ हा
  !!{nonenumerable} आहे असे म्हणतो तेव्हा आणि केवळ तेव्हाच, जेव्हा
  $A$ हा !!{enumerable} नसतो.
\end{defn}

source_excerpt:
\begin{prob}
Show that a set $A$ is !!{enumerable} iff either $A = \emptyset$ or
there is !!a{surjection} $f\colon \Nat \to A$. Show that $A$ is
!!{enumerable} iff there is !!a{injection} $g\colon A \to \Nat$.
\end{prob}

target_excerpt:
\begin{prob}
संच $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच $A =
\emptyset$ असते किंवा $f\colon \Nat \to A$ असे !!a{surjection}
असते, हे दाखवा. $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच
$g\colon A \to \Nat$ असे !!a{injection} असते, हेही दाखवा.
\end{prob}

source_excerpt:
\begin{explain}
It does not matter how we \emph{specify} the set, or how we
\emph{order} its !!{element}s, or indeed how \emph{many times} we
count its !!{element}s. All that matters are what its !!{element}s
are. We codify this in the following principle.
\end{explain}

target_excerpt:
\begin{explain}
आपण संच \emph{कसा निर्दिष्ट करतो}, त्यातील !!{element}s \emph{कोणत्या क्रमाने}
मांडतो किंवा तेच !!{element}s \emph{किती वेळा} मोजतो, याला महत्त्व नसते.
त्यात कोणते !!{element}s आहेत, एवढेच महत्त्वाचे असते. ही गोष्ट आपण पुढील
तत्त्वात नेमकेपणाने मांडतो.
\end{explain}

source_excerpt:
\begin{tagblock}{novice}
\begin{ex}
Whenever you have a bunch of objects, you can collect them together in
a set. The set of Richard's siblings, for instance, is a set that
contains one person, and we could write it as $S=\{\textrm{Ruth}\}$.
The set of positive integers less than $4$ is $\{1, 2, 3\}$, but it
can also be written as $\{3, 2, 1\}$ or even as $\{1, 2, 1, 2, 3\}$.
These are all the same set, by extensionality. For every !!{element}
of $\{1, 2, 3\}$ is also !!a{element} of $\{3, 2, 1\}$ (and of $\{1,
2, 1, 2, 3\}$), and vice versa.
\end{ex}
\end{tagblock}

target_excerpt:
\begin{tagblock}{novice}
\begin{ex}
काही वस्तू दिलेल्या असतील, तर त्या एकत्र करून त्यांचा संच बनवता येतो.
उदाहरणार्थ, रिचर्डच्या भावंडांच्या संचात एक व्यक्ती आहे, आणि तो
$S=\{\textrm{Ruth}\}$ असा लिहिता येईल.
$4$ पेक्षा लहान धन पूर्णांकांचा संच $\{1, 2, 3\}$ आहे; पण तो
$\{3, 2, 1\}$ किंवा अगदी $\{1, 2, 1, 2, 3\}$ असाही लिहिता येतो.
विस्तारात्मकतेनुसार हे सर्व एकच संच आहेत. कारण $\{1, 2, 3\}$ मधील
प्रत्येक !!{element} हा $\{3, 2, 1\}$ चा (आणि $\{1,
2, 1, 2, 3\}$ चाही) !!a{element} आहे, आणि उलटही.
\end{ex}
\end{tagblock}

source_excerpt:
\begin{tagblock}{novice}
\begin{ex}
In our example, we could have specified $S$ also as
\[
S = \Setabs{x}{x \text{ is a sibling of Richard}}.
\]
\end{ex}
\end{tagblock}

target_excerpt:
\begin{tagblock}{novice}
\begin{ex}
आपल्या उदाहरणातील $S$ हा संच पुढीलप्रमाणेही निर्दिष्ट करता आला असता:
\[
S = \Setabs{x}{x \text{ हे रिचर्डचे भावंड आहे}}.
\]
\end{ex}
\end{tagblock}

source_excerpt:
\begin{tagblock}{math}
\begin{ex}
A number is called \emph{perfect} iff it is equal to the sum of its
proper divisors (i.e., numbers that evenly divide it but aren't
identical to the number). For instance, $6$ is perfect because its
proper divisors are $1$, $2$, and~$3$, and $6 = 1 + 2 + 3$. In fact,
$6$ is the only positive integer less than $10$ that is perfect. So,
using extensionality, we can say:
\[
    \{6\} = \Setabs{x}{x\text{ is perfect and }0 \leq x \leq 10}
\]
We read the notation on the right as ``the set of $x$'s such that $x$
is perfect and $0 \leq x \leq 10$''. The identity here confirms that,
when we consider sets, we don't care about how they are specified.
And, more generally, extensionality guarantees that there is always
only one set of $x$'s such that $\phi(x)$.
So, extensionality justifies calling
$\Setabs{x}{\phi(x)}$ \emph{the} set of $x$'s such that~$\phi(x)$.
\end{ex}
\end{tagblock}

\begin{prob}
Prove that there is at most one empty set, i.e., show that if $A$ and $B$
are sets without !!{element}s, then $A = B$.
\end{prob}

target_excerpt:
\begin{prob}
जास्तीत जास्त एकच रिक्त संच असतो हे सिद्ध करा. म्हणजे, $A$ आणि $B$ या
संचांत एकही !!{element}s नसेल, तर $A = B$ हे दाखवा.
\end{prob}

source_excerpt:
\begin{explain}
We will often want to compare sets. And one obvious kind of comparison
one might make is as follows: \emph{everything in one set is in the
other too}. This situation is sufficiently important for us to
introduce some new notation.
\end{explain}

target_excerpt:
\begin{explain}
आपल्याला अनेकदा संचांची तुलना करावी लागेल. तुलना करण्याचा एक सरळ प्रकार
असा आहे: \emph{एका संचातील प्रत्येक वस्तू दुसऱ्या संचातही असते}.
ही स्थिती पुरेशी महत्त्वाची असल्यामुळे तिच्यासाठी आपण नवीन चिन्हपद्धतीची
ओळख करून घेऊ.
\end{explain}

source_excerpt:
\begin{ex}
Every set is a subset of itself, and $\emptyset$ is a subset of every
set. The set of natural even numbers is a subset of the set of natural
numbers. Also, $\{ a, b \} \subseteq \{ a, b, c \}$. But $\{ a, b, e
\}$ is not a subset of $\{ a, b, c \}$.
\end{ex}

\begin{prop}
$A = B$ iff both $A \subseteq B$ and $B \subseteq A$.
\end{prop}

target_excerpt:
\begin{prop}
$A = B$ तेव्हा आणि केवळ तेव्हाच, जेव्हा $A \subseteq B$ आणि $B \subseteq A$ दोन्ही असतात.
\end{prop}

source_excerpt:
\begin{defn}\ollabel{forallxina}
$(\forall x \in A)\phi$ abbreviates $\forall x(x \in A \lif
\phi)$. Similarly, $(\exists x \in A)\phi$ abbreviates $\exists x(x
\in A \land \phi)$.
\end{defn}

target_excerpt:
\begin{defn}\ollabel{forallxina}
$(\forall x \in A)\phi$ हे $\forall x(x \in A \lif
\phi)$ याचे संक्षिप्त रूप आहे. त्याचप्रमाणे, $(\exists x \in A)\phi$ हे
$\exists x(x
\in A \land \phi)$ याचे संक्षिप्त रूप आहे.
\end{defn}

source_excerpt:
\begin{ex}
What are all the possible subsets of $\{ a, b, c \}$? They are:
$\emptyset$, $\{a \}$, $\{b\}$, $\{c\}$, $\{a, b\}$, $\{a, c\}$, $\{b,
c\}$, $\{a, b, c\}$. The set of all these subsets is
$\Pow{\{a,b,c\}}$:
\[
\Pow{\{ a, b, c \}} = \{\emptyset, \{a \}, \{b\}, \{c\}, \{a, b\},
\{b, c\}, \{a, c\}, \{a, b, c\}\}
\]
\end{ex}

\begin{prob}
List all subsets of $\{a, b, c, d\}$.
\end{prob}

target_excerpt:
\begin{prob}
$\{a, b, c, d\}$ चे सर्व उपसंच लिहा.
\end{prob}

source_excerpt:
\begin{prob}
Show that if $A$ has $n$ !!{element}s, then $\Pow{A}$ has $2^n$
!!{element}s.
\end{prob}

target_excerpt:
\begin{prob}
$A$ मध्ये $n$ !!{element}s असतील, तर $\Pow{A}$ मध्ये $2^n$
!!{element}s असतात हे दाखवा.
\end{prob}

source_excerpt:
\begin{defn}[Function]
A \emph{function} $f \colon A \to B$ is a mapping of each !!{element}
of~$A$ to an !!{element} of~$B$.

We call $A$ the \emph{domain} of~$f$ and $B$ the \emph{codomain}
of~$f$.  The !!{element}s of~$A$ are called inputs or \emph{arguments}
of~$f$, and the !!{element} of~$B$ that is paired with an argument~$x$
by~$f$ is called the \emph{value of~$f$} for argument~$x$,
written~$f(x)$.

target_excerpt:
~$f$ ची \emph{व्याप्ती} $\ran{f}$ म्हणजे सहप्रांताचा असा उपसंच की
त्याचे घटक कोणत्या तरी फलसाधकासाठीची~$f$ ची मूल्ये असतात;
$\ran{f} = \Setabs{f(x)}{x \in A}$.
\end{defn}

source_excerpt:
\begin{figure}
  \olasset{assets/diagrams/function.tikz}
  \caption{A function is a mapping of each !!{element} of one set to
    !!a{element} of another. An arrow points from an argument in the
    domain to the corresponding value in the codomain.}
  \ollabel{fig:function}
\end{figure}

target_excerpt:
\begin{figure}
  \olasset{assets/diagrams/function.tikz}
  \caption{फलन एका संचातील प्रत्येक !!{element} ची दुसऱ्या संचातील
    !!a{element} शी संगती लावते. बाण प्रांतातील फलसाधकापासून
    सहप्रांतातील त्याच्या संगत मूल्याकडे जातो.}
  \ollabel{fig:function}
\end{figure}

source_excerpt:
\begin{ex}
Multiplication takes pairs of natural numbers as inputs and maps them
to natural numbers as outputs, so goes from $\Nat \times \Nat$ (the
domain) to $\Nat$ (the codomain). As it turns out, the range is also
$\Nat$, since every $n \in \Nat$ is $n \times 1$.
\end{ex}

target_excerpt:
\begin{ex}
गुणाकार नैसर्गिक संख्यांच्या जोड्या आदान म्हणून घेतो आणि त्यांना प्रदान
म्हणून नैसर्गिक संख्या जोडतो. म्हणून तो $\Nat \times \Nat$ या प्रांताकडून
$\Nat$ या सहप्रांताकडे जातो. त्याची व्याप्तीही $\Nat$ च असते, कारण
प्रत्येक $n \in \Nat$ हा $n \times 1$ असतो.
\end{ex}

\begin{ex}
गुणाकार हे फलन आहे, कारण तो प्रत्येक आदानाशी---नैसर्गिक संख्यांच्या
प्रत्येक जोडीशी---एकच प्रदान जोडतो: $\times \colon \Nat^2 \to \Nat$.
याउलट, नैसर्गिक संख्या~$n$ शी $x^2 = n$ असणारी वास्तव संख्या~$x$
जोडण्याची संगती फलन होत नाही, कारण प्रत्येक धन पूर्णांक~$n$ ची दोन
वर्गमुळे असतात: $\sqrt{n}$ आणि~$-\sqrt{n}$. फक्त धन वर्गमूळ देऊन
आपण तिचे फलन करू शकतो: फक्त ऋणेतर (प्रधान) वर्गमूळ परत द्यायचे,
$\sqrt{\phantom{X}} \colon \Nat \to \Real$.
\end{ex}
%READERNOTE{OLFUN-002 — गोठवलेल्या इंग्रजी स्रोतामध्ये सर्व नैसर्गिक संख्यांसाठी positive square root म्हटले आहे. शून्याचे प्रधान वर्गमूळ शून्य असल्यामुळे येथे ऋणेतर (प्रधान) असे दुरुस्त केले आहे; धन पूर्णांकांना दोन वास्तव वर्गमुळे असतात हे आधीचे विधान योग्य आहे.}

\begin{ex}
वर्गातील प्रत्येक विद्यार्थ्याशी त्याची अंतिम श्रेणी जोडणारा संबंध हे
फलन आहे---एकाच वर्गात कोणत्याही विद्यार्थ्याला दोन वेगवेगळ्या अंतिम
श्रेणी मिळू शकत नाहीत. वर्गातील प्रत्येक विद्यार्थ्याशी त्याचे पालक
जोडणारा संबंध फलन नाही: विद्यार्थ्यांचे पालक शून्य, दोन किंवा अधिक असू शकतात.
\end{ex}

\begin{ex}\ollabel{examplefunext}
$g \colon \Nat \to \Nat$ ची व्याख्या $g(x) = x+2-1$ अशी करू.
यावरून $g$ हे नैसर्गिक संख्या आदान म्हणून घेऊन नैसर्गिक संख्या प्रदान
करणारे फलन आहे हे कळते. नैसर्गिक संख्या x दिली, की $g$ हा~$x$ च्या
उत्तरवर्ती संख्येच्या उत्तरवर्ती संख्येची पूर्ववर्ती संख्या,
म्हणजेच $x+1$, देईल.
\end{ex}
%READERNOTE{OLFUN-003 — गोठवलेल्या इंग्रजी स्रोताच्या गद्यामध्ये याच उदाहरणात आदानासाठी आधी $n$ आणि लगेच x वापरले आहेत. सूत्र न बदलता मराठी गद्याने x हे एकच नाव सातत्याने वापरले आहे.}

source_excerpt:
\begin{ex}
We can also define functions by cases. For instance, we could define
$h \colon \Nat \to \Nat$  by
\[
h(x) =
\begin{cases}
  \frac{x}{2} & \text{if $x$ is even} \\
  \frac{x+1}{2} & \text{if $x$ is odd.}
\end{cases}
\]
Since every natural number is either even or odd, the output of this
function will always be a natural number. Just remember that if you
define a function by cases, every possible input must fall into
exactly one case.  In some cases, this will require a proof that the
cases are exhaustive and exclusive.
\end{ex}

target_excerpt:
\begin{ex}
प्रकरणे पाडूनही फलनाची व्याख्या करता येते. उदाहरणार्थ,
$h \colon \Nat \to \Nat$ ची व्याख्या अशी करता येईल:
\[
h(x) =
\begin{cases}
  \frac{x}{2} & \text{जर $x$ सम असेल} \\
  \frac{x+1}{2} & \text{जर $x$ विषम असेल.}
\end{cases}
\]
प्रत्येक नैसर्गिक संख्या सम किंवा विषम असते, म्हणून या फलनाचे प्रदान
नेहमी नैसर्गिक संख्या असेल. प्रकरणे पाडून फलनाची व्याख्या करताना
प्रत्येक शक्य आदान नेमक्या एका प्रकरणात बसले पाहिजे, हे लक्षात ठेवा.
काही वेळा सर्व शक्यता त्या प्रकरणांत येतात आणि कोणतीही शक्यता दोन
प्रकरणांत येत नाही याची सिद्धता करावी लागेल.
\end{ex}

\begin{explain}
~$A$ मधील !!{element}s ची~$B$ मधील !!{element}s शी संगती लावणारे
फलन $A$ आणि~$B$ यांच्यामधील एक संबंध ठरवते: $f(x) = y$ असेल
तेव्हा आणि केवळ तेव्हाच $x$ आणि $y$ यांच्यात हा संबंध असतो.
खरे तर, उदाहरणार्थ गणिताच्या पायाभूत घटकांची संख्या कमी करायची असेल,
तर आपण फलन~$f$ आणि हा संबंध, म्हणजे जोड्यांचा एक संच, \emph{एकरूप}
मानू शकतो. मग असा प्रश्न उभा राहतो: कोणते संबंध अशा रीतीने फलने ठरवतात?
\end{explain}

source_excerpt:
\begin{prop}\ollabel{prop:graph-function}
Let $R \subseteq A \times B$ be such that:
\begin{enumerate}
\item If $Rxy$ and $Rxz$ then $y = z$; and
\item for every $x \in A$ there is some $y \in B$ such that $\tuple{x,
y} \in R$.
\end{enumerate}
Then $R$ is the graph of the function $f\colon A \to B$ defined by
$f(x) = y$ iff $Rxy$.
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:graph-function}
$R \subseteq A \times B$ हा संबंध पुढील अटी पूर्ण करतो असे समजा:
\begin{enumerate}
\item $Rxy$ आणि $Rxz$ असल्यास $y = z$ असते; आणि
\item प्रत्येक $x \in A$ साठी $\tuple{x,
y} \in R$ असणारा काही $y \in B$ असतो.
\end{enumerate}
मग $f(x) = y$ तेव्हा आणि केवळ तेव्हाच $Rxy$, अशा व्याख्येने मिळणाऱ्या
फलन $f\colon A \to B$ चा आलेख $R$ असतो.
\end{prop}

source_excerpt:
\begin{proof}
Suppose there is a $y$ such that $Rxy$.  If there were another $z \neq
y$ such that $Rxz$, the condition on~$R$ would be violated. Hence, if
there is a $y$ such that $Rxy$, this $y$ is unique, and so $f$ is
well-defined.  Obviously, $R_f = R$.
\end{proof}

target_excerpt:
\begin{proof}
$Rxy$ असणारा एक $y$ आहे असे समजा. $Rxz$ असणारा दुसरा $z \neq y$
असता, तर~$R$ वरील अट मोडली गेली असती. म्हणून $Rxy$ असणारा एक $y$
असेल, तर हा $y$ एकमेव असतो. त्यामुळे $f$ सुस्पष्टपणे परिभाषित आहे.
उघडच, $R_f = R$.
\end{proof}

~$f$ चे~$C$ वरील \emph{उपयोजन} म्हणजे $\funimage{f}{C} =
\Setabs{f(x)}{x \in C}$. यालाच~$f$ अंतर्गत~$C$ ची \emph{प्रतिमा}
असेही म्हणतो.
\end{defn}

source_excerpt:
\begin{explain}
It follows from these definitions that $\ran{f} =
\funimage{f}{\dom{f}}$, for any function~$f$.
\oliflabeldef{sfr:rel:ops:sec}{These notions are exactly as one would
expect, given the definitions in \olref[sfr][rel][ops]{sec} and our
identification of functions with relations. But two other
operations---inverses and relative products---require a little more
detail. We will provide that in \olref[inv]{sec} and
\olref[cmp]{sec}.}{}
\end{explain}

target_excerpt:
\begin{explain}
या व्याख्यांवरून कोणत्याही फलन~$f$ साठी $\ran{f} =
\funimage{f}{\dom{f}}$ असते.
\oliflabeldef{sfr:rel:ops:sec}{\olref[sfr][rel][ops]{sec} मधील
व्याख्या आणि फलनांना संबंधांशी एकरूप मानण्याची आपली पद्धत लक्षात
घेतल्यास या संकल्पना अनुरूप आहेत. मात्र फलनाचे C पर्यंतचे मर्यादन
केवळ आदान निर्देशांक C मध्ये ठेवते; संबंधाचे C वरील मर्यादन
दोन्ही निर्देशांक C मध्ये ठेवते. त्यामुळे त्या अगदी एकच क्रिया नाहीत.
व्युत्क्रम आणि सापेक्ष गुणाकार या इतर दोन क्रियांना थोडे अधिक
स्पष्टीकरण लागते. ते आपण
\olref[inv]{sec} आणि \olref[cmp]{sec} मध्ये देऊ.}{}
\end{explain}
%READERNOTE{OLFUN-005 — फलनाच्या मर्यादनाचे स्पष्ट सूत्र योग्य आहे: आलेखात पहिला निर्देशांक C मध्ये असतो. आधीचे संबंधावरील मर्यादन दोन्ही निर्देशांक C मध्ये ठेवते. इंग्रजी स्रोताचा exactly असा दावा येथे अनुरूप पण भिन्न असा स्पष्ट केला आहे.}

\begin{proof}
$f(x) = \{x\}$ हे $f \colon A \to \Pow{A}$ असे !!a{injection} आहे;
कारण $x \neq y$ असेल, तर विस्तारात्मकतेमुळे $\{x\} \neq \{y\}$ सुद्धा
असते, आणि म्हणून $f(x) \neq f(y)$. त्यामुळे $\cardle{A}{\Pow{A}}$.

source_excerpt:
\begin{explain}
We will often want to compare sets. And one obvious kind of comparison
one might make is as follows: \emph{everything in one set is in the
other too}. This situation is sufficiently important for us to
introduce some new notation.
\end{explain}

target_excerpt:
\begin{explain}
आपल्याला अनेकदा संचांची तुलना करावी लागेल. तुलना करण्याचा एक सरळ प्रकार
असा आहे: \emph{एका संचातील प्रत्येक वस्तू दुसऱ्या संचातही असते}.
ही स्थिती पुरेशी महत्त्वाची असल्यामुळे तिच्यासाठी आपण नवीन चिन्हपद्धतीची
ओळख करून घेऊ.
\end{explain}

source_excerpt:
\begin{ex}
Every set is a subset of itself, and $\emptyset$ is a subset of every
set. The set of natural even numbers is a subset of the set of natural
numbers. Also, $\{ a, b \} \subseteq \{ a, b, c \}$. But $\{ a, b, e
\}$ is not a subset of $\{ a, b, c \}$.
\end{ex}

\begin{prop}
$A = B$ iff both $A \subseteq B$ and $B \subseteq A$.
\end{prop}

target_excerpt:
\begin{prop}
$A = B$ तेव्हा आणि केवळ तेव्हाच, जेव्हा $A \subseteq B$ आणि $B \subseteq A$ दोन्ही असतात.
\end{prop}

source_excerpt:
\begin{defn}\ollabel{forallxina}
$(\forall x \in A)\phi$ abbreviates $\forall x(x \in A \lif
\phi)$. Similarly, $(\exists x \in A)\phi$ abbreviates $\exists x(x
\in A \land \phi)$.
\end{defn}

target_excerpt:
\begin{defn}\ollabel{forallxina}
$(\forall x \in A)\phi$ हे $\forall x(x \in A \lif
\phi)$ याचे संक्षिप्त रूप आहे. त्याचप्रमाणे, $(\exists x \in A)\phi$ हे
$\exists x(x
\in A \land \phi)$ याचे संक्षिप्त रूप आहे.
\end{defn}

source_excerpt:
\begin{ex}
What are all the possible subsets of $\{ a, b, c \}$? They are:
$\emptyset$, $\{a \}$, $\{b\}$, $\{c\}$, $\{a, b\}$, $\{a, c\}$, $\{b,
c\}$, $\{a, b, c\}$. The set of all these subsets is
$\Pow{\{a,b,c\}}$:
\[
\Pow{\{ a, b, c \}} = \{\emptyset, \{a \}, \{b\}, \{c\}, \{a, b\},
\{b, c\}, \{a, c\}, \{a, b, c\}\}
\]
\end{ex}

\begin{prob}
List all subsets of $\{a, b, c, d\}$.
\end{prob}

target_excerpt:
\begin{prob}
$\{a, b, c, d\}$ चे सर्व उपसंच लिहा.
\end{prob}

source_excerpt:
\begin{prob}
Show that if $A$ has $n$ !!{element}s, then $\Pow{A}$ has $2^n$
!!{element}s.
\end{prob}

target_excerpt:
\begin{prob}
$A$ मध्ये $n$ !!{element}s असतील, तर $\Pow{A}$ मध्ये $2^n$
!!{element}s असतात हे दाखवा.
\end{prob}

source_excerpt:
\begin{figure}
  \olasset{assets/diagrams/union.tikz}
  \caption{The union $A \cup B$ of two sets is set of !!{element}s of
   $A$ together with those of~$B$.}
  \ollabel{fig:union}
\end{figure}

target_excerpt:
\begin{figure}
  \olasset{assets/diagrams/union.tikz}
  \caption{दोन संचांचा संयोग $A \cup B$ म्हणजे $A$ मधील आणि $B$ मधील
    !!{element}s एकत्र घेऊन बनणारा संच.}
  \ollabel{fig:union}
\end{figure}

source_excerpt:
This operation on sets---combining them---is very useful and common,
and so we give it a formal name and a symbol.
\end{explain}

target_excerpt:
संच एकत्र करणारी ही क्रिया अतिशय उपयुक्त आहे आणि वारंवार वापरली जाते.
म्हणून तिला आपण आकारिक नाव आणि चिन्ह देतो.
\end{explain}

source_excerpt:
The union of a set with the empty set is identical to the set: $\{a,
b, c \} \cup \emptyset = \{a, b, c \}$.
\end{ex}

\begin{prob}
Prove that if $A \subseteq B$, then $A \cup B = B$.
\end{prob}

target_excerpt:
\begin{prob}
$A \subseteq B$ असेल, तर $A \cup B = B$ हे सिद्ध करा.
\end{prob}

source_excerpt:
\begin{explain}
We can also consider a ``dual'' operation to union. This is the
operation that forms the set of all !!{element}s that are !!{element}s
of~$A$ and are also !!{element}s of~$B$. This operation is called
\emph{intersection}, and can be depicted as in \olref{fig:intersection}.
\begin{figure}
  \olasset{assets/diagrams/intersection.tikz}
  \caption{The intersection $A \cap B$ of two sets is the set of
    !!{element}s they have in common.}
  \ollabel{fig:intersection}
\end{figure}
\end{explain}

target_excerpt:
\begin{explain}
संयोगाच्या ``द्वैत'' क्रियेचाही विचार करता येतो. या क्रियेत असे सर्व
!!{element}s घेतले जातात की जे $A$ मधील !!{element}s आणि
$B$ मधीलही !!{element}s आहेत, आणि त्यांचा संच बनवला जातो.
या क्रियेला \emph{छेद} म्हणतात. तिचे चित्र \olref{fig:intersection} प्रमाणे काढता येते.
\begin{figure}
  \olasset{assets/diagrams/intersection.tikz}
  \caption{दोन संचांचा छेद $A \cap B$ म्हणजे त्यांतील सामाईक
    !!{element}s यांचा संच.}
  \ollabel{fig:intersection}
\end{figure}
\end{explain}

source_excerpt:
\begin{ex}
If two sets have no !!{element}s in common, their intersection is empty:
$\{ a, b, c\} \cap \{ 0, 1\} = \emptyset$.

target_excerpt:
\begin{ex}
दोन संचांत सामाईक !!{element}s नसतील, तर त्यांचा छेद रिक्त असतो:
$\{ a, b, c\} \cap \{ 0, 1\} = \emptyset$.

source_excerpt:
The intersection of any set with the empty set is empty: $\{a, b, c \}
\cap \emptyset = \emptyset$.
\end{ex}

target_excerpt:
कोणत्याही संचाचा रिक्त संचाशी छेद रिक्त असतो:
$\{a, b, c \}
\cap \emptyset = \emptyset$.
\end{ex}

source_excerpt:
\begin{prob}
Prove rigorously that if $A \subseteq B$, then $A \cap B = A$.
\end{prob}

target_excerpt:
\begin{prob}
$A \subseteq B$ असेल, तर $A \cap B = A$ हे काटेकोरपणे सिद्ध करा.
\end{prob}

source_excerpt:
\begin{defn}
If $A$ is a set of sets, then $\bigcup A$ is the set of !!{element}s of
!!{element}s of~$A$:
\begin{align*}
\bigcup A & = \Setabs{x}{x \text{ belongs to !!a{element} of } A},
\text{ i.e.,}\\
& = \Setabs{x}{\text{there is a } B \in A
  \text{ so that } x \in B}
\end{align*}
\end{defn}

target_excerpt:
\begin{defn}
$A$ हा संचांचा संच असेल, तर $\bigcup A$ म्हणजे $A$ मधील
!!{element}s यांत असणाऱ्या !!{element}s यांचा संच:
\begin{align*}
\bigcup A & = \Setabs{x}{x \text{ ही पुढील संचाच्या एका !!a{element}ात असते: } A},
\text{ म्हणजे,}\\
& = \Setabs{x}{\text{असा } B \in A
  \text{ असतो की } x \in B}
\end{align*}
\end{defn}

source_excerpt:
\begin{defn}
If $A$ is a set of sets, then $\bigcap A$ is the set of objects which
all elements of~$A$ have in common:
\begin{align*}
\bigcap A & = \Setabs{x}{x \text{ belongs to every !!{element} of } A},
\text{ i.e.,}\\
 & = \Setabs{x}{\text{for all } B \in A, x \in B}
\end{align*}
\end{defn}

target_excerpt:
\begin{defn}
$A$ हा संचांचा संच असेल, तर $\bigcap A$ म्हणजे $A$ मधील सर्व घटकांत
सामाईक असणाऱ्या वस्तूंचा संच:
\begin{align*}
\bigcap A & = \Setabs{x}{x \text{ ही पुढील संचाच्या प्रत्येक !!{element}ात असते: } A},
\text{ म्हणजे,}\\
 & = \Setabs{x}{\text{प्रत्येक } B \in A, x \in B}
\end{align*}
\end{defn}

source_excerpt:
\begin{ex}
Suppose $A = \{ \{ a, b \}, \{ a, d, e \}, \{ a, d \} \}$.
Then $\bigcup A = \{ a, b, d, e \}$ and $\bigcap A = \{ a \}$.
\end{ex}
\begin{prob}
    Show that if $A$ is a set and $A \in B$, then $A \subseteq \bigcup B$.
\end{prob}

target_excerpt:
\begin{ex}
$A = \{ \{ a, b \}, \{ a, d, e \}, \{ a, d \} \}$ असे समजा.
मग $\bigcup A = \{ a, b, d, e \}$ आणि $\bigcap A = \{ a \}$.
\end{ex}
\begin{prob}
    $A$ हा संच असेल आणि $A \in B$ असेल, तर $A \subseteq \bigcup B$ हे दाखवा.
\end{prob}

source_excerpt:
We could also do the same for a sequence of sets $A_1$, $A_2$, \dots
\begin{align*}
\bigcup_i A_i & = \Setabs{x}{x \text{ belongs to one of the } A_i}\\
\bigcap_i A_i & = \Setabs{x}{x \text{ belongs to every } A_i}.
\end{align*}

target_excerpt:
$A_1$, $A_2$, \dots या संचांच्या अनुक्रमासाठीही हेच करता येईल:
\begin{align*}
\bigcup_i A_i & = \Setabs{x}{x \text{ ही पुढीलपैकी एखाद्या संचात असते: } A_i}\\
\bigcap_i A_i & = \Setabs{x}{x \text{ ही पुढील प्रत्येक संचात असते: } A_i}.
\end{align*}

source_excerpt:
When we have an \emph{index} of sets, i.e., some set $I$ such that we
are considering $A_i$ for each $i \in I$, we may also use these
abbreviations:
\begin{align*}
    \bigcup_{i \in I} A_i & = \bigcup \Setabs{A_i }{i \in I}\\
    \bigcap_{i \in I} A_i & = \bigcap\Setabs{A_i}{i \in I}
\end{align*}

target_excerpt:
संचांसाठी \emph{निर्देशांक संच} दिलेला असेल, म्हणजे एखादा $I$ संच असा असेल की,
प्रत्येक $i \in I$ साठी आपण $A_i$ चा विचार करत असू, तर पुढील संक्षिप्त
रूपेही वापरता येतात:
\begin{align*}
    \bigcup_{i \in I} A_i & = \bigcup \Setabs{A_i }{i \in I}\\
    \bigcap_{i \in I} A_i & = \bigcap\Setabs{A_i}{i \in I}
\end{align*}

source_excerpt:
\begin{figure}
  \olasset{assets/diagrams/difference.tikz}
  \caption{The difference $A \setminus B$ of two sets is the set of
    those !!{element}s of~$A$ which are not also !!{element}s of~$B$.}
  \ollabel{difference}
\end{figure}

target_excerpt:
\begin{figure}
  \olasset{assets/diagrams/difference.tikz}
