source_excerpt:
\begin{prop}\ollabel{prop:extensionality-strictlinearorders}
If $<$ is a strict linear order on $A$, then:
\[
  (\forall a, b \in A)((\forall x \in A)(x < a \liff x < b) \lif a = b).
\]
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:extensionality-strictlinearorders}
$<$ हा $A$ वरील काटेकोर रेषीय क्रम असेल, तर:
\[
  (\forall a, b \in A)((\forall x \in A)(x < a \liff x < b) \lif a = b).
\]
\end{prop}

source_excerpt:
\begin{proof}
Suppose $(\forall x \in A)(x < a \liff x < b)$. If $a < b$, then $a <
a$, contradicting the fact that $<$ is irreflexive; so $a \nless b$.
Exactly similarly, $b \nless a$. So $a = b$, as $<$ is connected.
\end{proof}

target_excerpt:
\begin{proof}
$(\forall x \in A)(x < a \liff x < b)$ असे समजा. $a < b$ असेल, तर
$a < a$; पण $<$ अपरावर्ती आहे याच्याशी हे विसंगत आहे. म्हणून $a \nless b$.
अगदी त्याचप्रमाणे $b \nless a$. $<$ संयोजित असल्याने $a = b$.
\end{proof}

$x \in A$ च्या उत्तरवर्तींना त्याची \emph{अपत्ये} असेही म्हणतात.
$y$ हा $x$ चा उत्तरवर्ती असेल, तर $x$ ला $y$ चा \emph{पूर्ववर्ती}
किंवा \emph{पालक} म्हणतो.

source_excerpt:
\begin{prop}
If $\tuple{A,\le}$ is a tree, then every $x \in A$ other than the root
has at most one predecessor.
\end{prop}

target_excerpt:
