source_excerpt:
\begin{defn}[Assumption]
An \emph{assumption} is any !!{sentence}
in the topmost position of any branch.
\end{defn}

\begin{prop}[Compactness]
  \ollabel{prop:proves-compact}
  \begin{enumerate}
  \item If $\Gamma \Proves !A$ then there is a finite subset $\Gamma_0
    \subseteq \Gamma$ such that $\Gamma_0 \Proves !A$.
  \item If every finite subset of~$\Gamma$ is
    consistent, then $\Gamma$ is consistent.
  \end{enumerate}
\end{prop}

target_excerpt:
\begin{prop}[संहतता]
  \ollabel{prop:proves-compact}
  \begin{enumerate}
  \item $\Gamma \Proves !A$ असेल, तर एखादा सांत उपसंच $\Gamma_0
    \subseteq \Gamma$ असा आहे की $\Gamma_0 \Proves !A$.
  \item $\Gamma$ चा प्रत्येक सांत उपसंच सुसंगत असेल, तर $\Gamma$ सुसंगत
    असतो.
  \end{enumerate}
\end{prop}

source_excerpt:
\begin{proof}
  \begin{enumerate}
    \item If $\Gamma \Proves !A$, then there is
      !!a{derivation}~$\delta$ of~$!A$ from~$\Gamma$. Let $\Gamma_0$
      be the set of !!{undischarged} assumptions of~$\delta$.  Since
      any !!{derivation} is finite, $\Gamma_0$ can only contain
      finitely many !!{sentence}s.  So, $\delta$ is !!a{derivation}
      of~$!A$ from a finite~$\Gamma_0 \subseteq \Gamma$.
    \item This is the contrapositive of (1) for the special case $!A
      \ident \lfalse$.
  \end{enumerate}
\end{proof}

target_excerpt:
\begin{proof}
  \begin{enumerate}
    \item $\Gamma \Proves !A$ असेल, तर $\Gamma$ पासून $!A$ ची
      !!a{derivation}~$\delta$ असते. $\Gamma_0$ हा $\delta$ मधील
      !!{undischarged} गृहीतकांचा संच असू द्या. प्रत्येक !!{derivation} सांत
      असल्यामुळे $\Gamma_0$ मधील !!{sentence}s ची संख्या सांतच असते.
      म्हणून $\delta$ ही सांत~$\Gamma_0 \subseteq \Gamma$ पासून $!A$ ची
      !!a{derivation} आहे.
    \item (1) मध्ये $!A
      \ident \lfalse$ हे विशेष प्रकरण घेतल्यावर मिळणारे हे निषेधात्मक उलट
      विधान आहे.
  \end{enumerate}
\end{proof}

