source_excerpt:
\begin{prob}
Consider adding to $\Lang{L_0}$ a ternary connective $\diamondsuit$
with evaluation given by
\begin{gather*}
  \pValue{v}(\diamondsuit( !A , !B , !C ) ) = \begin{cases}
    \pValue{v}( !B ) &
    \text{if $\pValue{v}(!A) = \True$;}\\
    \pValue{v}( !C ) &
    \text{if $\pValue{v}(!A) = \False $}.
  \end{cases}
\end{gather*}
Write down the truth table for this connective.
\end{prob}

target_excerpt:
\begin{prob}
$\Lang{L_0}$ मध्ये $\diamondsuit$ हा त्रिस्थानी संयोजक वाढवण्याचा विचार
करा; त्याचे मूल्यन पुढीलप्रमाणे दिले आहे:
\begin{gather*}
  \pValue{v}(\diamondsuit( !A , !B , !C ) ) = \begin{cases}
    \pValue{v}( !B ) &
    \text{जर $\pValue{v}(!A) = \True$;}\\
    \pValue{v}( !C ) &
    \text{जर $\pValue{v}(!A) = \False $}.
  \end{cases}
\end{gather*}
या संयोजकाचे सत्यताकोष्टक लिहा.
\end{prob}

