  \olasset{assets/diagrams/difference.tikz}
  \caption{The difference $A \setminus B$ of two sets is the set of
    those !!{element}s of~$A$ which are not also !!{element}s of~$B$.}
  \ollabel{difference}
\end{figure}

target_excerpt:
