\end{figure}

source_excerpt:
\begin{prob}
    Prove that if $A \subsetneq B$, then $B \setminus A \neq \emptyset$.
\end{prob}

target_excerpt:
\begin{prob}
    $A \subsetneq B$ असेल, तर $B \setminus A \neq \emptyset$ हे सिद्ध करा.
\end{prob}

source_excerpt:
The \emph{application} of $R$ to $A$ is $\funimage{R}{A} = \{y :
(\exists x \in A)Rxy\}$
\end{defn}

target_excerpt:
$R$ चा $A$ वर \emph{प्रयोग} म्हणजे $\funimage{R}{A} = \{y :
(\exists x \in A)Rxy\}$
\end{defn}

source_excerpt:
\begin{ex}
Let $S \subseteq \Int^2$ be the successor relation on~$\Int$, i.e.,
$S = \Setabs{\tuple{x, y} \in \Int^2}{x + 1 = y}$, so that $Sxy$ iff $x + 1 = y$.

The \emph{reflexive transitive closure} of $R$ is $R^* = R^+ \cup
\Id{A}$.
\end{defn}

\begin{ex}
Take the successor relation $S \subseteq \Int^2$. $S^2xy$ iff $x + 2 =
y$, $S^3xy$ iff $x + 3 = y$, etc. So $S^+xy$ iff $x + n = y$ for some
$n \geq 1$. In other words, $S^+xy$ iff $x < y$, and $S^*xy$ iff $x \le
y$.
\end{ex}

\begin{prob}
Show that the transitive closure of $R$ is in fact transitive.
\end{prob}

target_excerpt:
\begin{prob}
$R$ चे संक्रमक संवरण खरोखर संक्रमक आहे, हे दाखवा.
\end{prob}

source_excerpt:
\begin{prob}
  Show that if $A$ and $B$ are !!{enumerable}, so is $A \cup B$. To do
  this, suppose there are !!{surjective} functions $f\colon \PosInt \to
  A$ and $g\colon \PosInt \to B$, and define !!a{surjective}
  function~$h\colon \PosInt \to A \cup B$ and prove that it is
  !!{surjective}. Also consider the cases where $A$ or~$B = \emptyset$.
\end{prob}

\begin{prob}
  Show by induction on $n$ that if $A_1$, $A_2$, \dots, $A_n$ are all
  !!{enumerable}, so is $A_1 \cup \dots \cup A_n$. You may assume the
  fact that if two sets $A$ and~$B$ are !!{enumerable}, so is~$A \cup
  B$.
\end{prob}

\begin{prob}
Show that the !!{enumerable} union of !!{enumerable} sets is
!!{enumerable}. That is, whenever $A_1$, $A_2$, \dots{} are sets, and
each $A_i$ is !!{enumerable}, then the union $\bigcup_{i=1}^\infty
A_i$ of all of them is also !!{enumerable}. [NB: this is hard!]
\end{prob}

target_excerpt:
\begin{prob}
!!{enumerable} इतक्या !!{enumerable} संचांचा संयोग !!{enumerable} असतो,
हे दाखवा. म्हणजे, $A_1$, $A_2$, \dots{} हे संच असतील आणि प्रत्येक
$A_i$ हा !!{enumerable} असेल, तर त्या सर्वांचा संयोग
$\bigcup_{i=1}^\infty A_i$ हाही !!{enumerable} असतो. [टीप: हे कठीण आहे!]
\end{prob}

source_excerpt:
\begin{prob}
Show that if $\cardeq{A}{C}$ and $\cardeq{B}{D}$, and $A \cap B =
C \cap D = \emptyset$, then $\cardeq{A \cup B}{C \cup D}$.
\end{prob}

target_excerpt:
\begin{prob}
$\cardeq{A}{C}$ आणि $\cardeq{B}{D}$ असेल, आणि $A \cap B =
C \cap D = \emptyset$ असेल, तर $\cardeq{A \cup B}{C \cup D}$ आहे,
हे दाखवा.
\end{prob}

source_excerpt:
\begin{prob}
Show that if $A$ and $B$ are !!{enumerable}, so is $A \cup B$.
\end{prob}

target_excerpt:
\begin{prob}
$A$ आणि $B$ हे !!{enumerable} असतील, तर $A \cup B$ सुद्धा गणनीय
आहे, हे दाखवा.
\end{prob}

source_excerpt:
\begin{prob}
Show by induction on $n$ that if $A_1$, $A_2$, \dots, $A_n$ are all
!!{enumerable}, so is $A_1 \cup \dots \cup A_n$.
\end{prob}

target_excerpt:
\begin{prob}
$A_1$, $A_2$, \dots, $A_n$ हे सर्व !!{enumerable} असतील, तर
$A_1 \cup \dots \cup A_n$ सुद्धा गणनीय आहे, हे $n$ वरील गणिती विगमनाने
दाखवा.
\end{prob}

source_excerpt:
\begin{proof}
There are finite $\Gamma_0$ and $\Gamma_1 \subseteq \Gamma$ such that
$\Log{LK}$ !!{derive}s $\Gamma_0 \Sequent !A$ and $!A, \Gamma_1
\Sequent \quad$.  Let the $\Log{LK}$-!!{derivation} of $\Gamma_0 \Sequent
!A$ be~$\pi_0$ and the $\Log{LK}$-!!{derivation} of $\Gamma_1, !A
\Sequent \quad$ be~$\pi_1$. We can then !!{derive}
\begin{prooftree}
\AxiomC{}
\RightLabel{$\pi_0$}
\Deduce$ \Gamma_0 \fCenter !A $
\AxiomC{}
\RightLabel{$\pi_1$}
\Deduce$!A, \Gamma_1 \fCenter $
\RightLabel{\Cut}
\BinaryInf$ \Gamma_0,\Gamma_1 \fCenter $
\end{prooftree}

target_excerpt:
\begin{proof}
अशी सांत $\Gamma_0$ आणि $\Gamma_1 \subseteq \Gamma$ असतात की
$\Log{LK}$ !!{derive}s $\Gamma_0 \Sequent !A$ आणि $!A, \Gamma_1
\Sequent \quad$. $\Gamma_0 \Sequent !A$ ची $\Log{LK}$-!!{derivation}
~$\pi_0$ आणि $\Gamma_1, !A \Sequent \quad$ ची $\Log{LK}$-!!{derivation}
~$\pi_1$ अशी नावे देऊ. मग आपण !!{derive} करू शकतो
\begin{prooftree}
\AxiomC{}
\RightLabel{$\pi_0$}
\Deduce$ \Gamma_0 \fCenter !A $
\AxiomC{}
\RightLabel{$\pi_1$}
\Deduce$!A, \Gamma_1 \fCenter $
\RightLabel{\Cut}
\BinaryInf$ \Gamma_0,\Gamma_1 \fCenter $
\end{prooftree}

source_excerpt:
Since $\Gamma_0 \subseteq \Gamma$ and $\Gamma_1 \subseteq \Gamma$,
$\Gamma_0 \cup \Gamma_1 \subseteq \Gamma$, hence $\Gamma$~is inconsistent.
\end{proof}

target_excerpt:
कारण $\Gamma_0 \subseteq \Gamma$ आणि $\Gamma_1 \subseteq \Gamma$,
$\Gamma_0 \cup \Gamma_1 \subseteq \Gamma$; म्हणून $\Gamma$ विसंगत आहे.
\end{proof}

source_excerpt:
\begin{prob}
Prove that $\Gamma \Proves \lnot !A$ iff $\Gamma \cup \{!A\}$ is inconsistent.
\end{prob}

target_excerpt:
\begin{prob}
$\Gamma \Proves \lnot !A$ तेव्हा आणि केवळ तेव्हाच, जेव्हा $\Gamma \cup \{!A\}$
विसंगत असते, हे सिद्ध करा.
\end{prob}

source_excerpt:
\begin{prop}\ollabel{prop:provability-exhaustive}
  If $\Gamma \cup \{!A\}$ and $\Gamma \cup \{\lnot !A\}$ are both
  inconsistent, then $\Gamma$ is inconsistent.
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:provability-exhaustive}
  जर $\Gamma \cup \{!A\}$ आणि $\Gamma \cup \{\lnot !A\}$ दोन्ही
  विसंगत असतील, तर $\Gamma$ विसंगत आहे.
\end{prop}

source_excerpt:
\begin{proof}
There are finite sets $\Gamma_0 \subseteq \Gamma$ and $\Gamma_1
\subseteq \Gamma$ and $\Log{LK}$-!!{derivation}s $\pi_0$ and $\pi_1$
of $!A, \Gamma_0 \Sequent \quad$ and $\lnot !A, \Gamma_1 \Sequent
\quad$, respectively. We can then !!{derive}
\begin{prooftree}
\AxiomC{}
\RightLabel{$\pi_0$}
\Deduce$ !A, \Gamma_0 \fCenter $
\RightLabel{\RightR{\lnot}}
\UnaryInf$ \Gamma_0 \fCenter \lnot !A$
\AxiomC{}
\RightLabel{$\pi_1$}
\Deduce$\lnot !A, \Gamma_1 \fCenter  $
\RightLabel{\Cut}
\BinaryInf$ \Gamma_0, \Gamma_1 \fCenter $
\end{prooftree}
Since $\Gamma_0 \subseteq \Gamma$ and $\Gamma_1 \subseteq \Gamma$,
$\Gamma_0 \cup \Gamma_1 \subseteq \Gamma$. Hence $\Gamma$ is
inconsistent.
\end{proof}

target_excerpt:
\begin{proof}
अशी सांत संच $\Gamma_0 \subseteq \Gamma$ आणि $\Gamma_1
\subseteq \Gamma$, तसेच $\Log{LK}$-!!{derivation}s $\pi_0$ आणि $\pi_1$
$!A, \Gamma_0 \Sequent \quad$ आणि $\lnot !A, \Gamma_1 \Sequent
\quad$ यांचे अनुक्रमे, असतात. मग आपण !!{derive} करू शकतो
\begin{prooftree}
\AxiomC{}
\RightLabel{$\pi_0$}
\Deduce$ !A, \Gamma_0 \fCenter $
\RightLabel{\RightR{\lnot}}
\UnaryInf$ \Gamma_0 \fCenter \lnot !A$
\AxiomC{}
\RightLabel{$\pi_1$}
\Deduce$\lnot !A, \Gamma_1 \fCenter  $
\RightLabel{\Cut}
\BinaryInf$ \Gamma_0, \Gamma_1 \fCenter $
\end{prooftree}
कारण $\Gamma_0 \subseteq \Gamma$ आणि $\Gamma_1 \subseteq \Gamma$,
$\Gamma_0 \cup \Gamma_1 \subseteq \Gamma$. म्हणून $\Gamma$ विसंगत आहे.
\end{proof}

