source_excerpt:
\begin{ex}
Let $S \subseteq \Int^2$ be the successor relation on~$\Int$, i.e.,
$S = \Setabs{\tuple{x, y} \in \Int^2}{x + 1 = y}$, so that $Sxy$ iff $x + 1 = y$.

The \emph{reflexive transitive closure} of $R$ is $R^* = R^+ \cup
\Id{A}$.
\end{defn}

\begin{ex}
Take the successor relation $S \subseteq \Int^2$. $S^2xy$ iff $x + 2 =
y$, $S^3xy$ iff $x + 3 = y$, etc. So $S^+xy$ iff $x + n = y$ for some
$n \geq 1$. In other words, $S^+xy$ iff $x < y$, and $S^*xy$ iff $x \le
y$.
\end{ex}

\begin{prob}
Show that the transitive closure of $R$ is in fact transitive.
\end{prob}

target_excerpt:
\begin{prob}
$R$ चे संक्रमक संवरण खरोखर संक्रमक आहे, हे दाखवा.
\end{prob}

\begin{explain}
~$A$ मधील !!{element}s ची~$B$ मधील !!{element}s शी संगती लावणारे
फलन $A$ आणि~$B$ यांच्यामधील एक संबंध ठरवते: $f(x) = y$ असेल
तेव्हा आणि केवळ तेव्हाच $x$ आणि $y$ यांच्यात हा संबंध असतो.
खरे तर, उदाहरणार्थ गणिताच्या पायाभूत घटकांची संख्या कमी करायची असेल,
तर आपण फलन~$f$ आणि हा संबंध, म्हणजे जोड्यांचा एक संच, \emph{एकरूप}
मानू शकतो. मग असा प्रश्न उभा राहतो: कोणते संबंध अशा रीतीने फलने ठरवतात?
\end{explain}

source_excerpt:
\begin{prop}\ollabel{prop:graph-function}
Let $R \subseteq A \times B$ be such that:
\begin{enumerate}
\item If $Rxy$ and $Rxz$ then $y = z$; and
\item for every $x \in A$ there is some $y \in B$ such that $\tuple{x,
y} \in R$.
\end{enumerate}
Then $R$ is the graph of the function $f\colon A \to B$ defined by
$f(x) = y$ iff $Rxy$.
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:graph-function}
$R \subseteq A \times B$ हा संबंध पुढील अटी पूर्ण करतो असे समजा:
\begin{enumerate}
\item $Rxy$ आणि $Rxz$ असल्यास $y = z$ असते; आणि
\item प्रत्येक $x \in A$ साठी $\tuple{x,
y} \in R$ असणारा काही $y \in B$ असतो.
\end{enumerate}
मग $f(x) = y$ तेव्हा आणि केवळ तेव्हाच $Rxy$, अशा व्याख्येने मिळणाऱ्या
फलन $f\colon A \to B$ चा आलेख $R$ असतो.
\end{prop}

source_excerpt:
\begin{proof}
Suppose there is a $y$ such that $Rxy$.  If there were another $z \neq
y$ such that $Rxz$, the condition on~$R$ would be violated. Hence, if
there is a $y$ such that $Rxy$, this $y$ is unique, and so $f$ is
well-defined.  Obviously, $R_f = R$.
\end{proof}

target_excerpt:
\begin{proof}
$Rxy$ असणारा एक $y$ आहे असे समजा. $Rxz$ असणारा दुसरा $z \neq y$
असता, तर~$R$ वरील अट मोडली गेली असती. म्हणून $Rxy$ असणारा एक $y$
असेल, तर हा $y$ एकमेव असतो. त्यामुळे $f$ सुस्पष्टपणे परिभाषित आहे.
उघडच, $R_f = R$.
\end{proof}

~$f$ चे~$C$ वरील \emph{उपयोजन} म्हणजे $\funimage{f}{C} =
\Setabs{f(x)}{x \in C}$. यालाच~$f$ अंतर्गत~$C$ ची \emph{प्रतिमा}
असेही म्हणतो.
\end{defn}

