\begin{defn}[विन्यासात्मक अनन्यता]
$\ident$ हे चिन्ह चिन्हमालांमधील विन्यासात्मक अनन्यता व्यक्त करते;
म्हणजे $!A \ident !B$ तेव्हा आणि केवळ तेव्हाच, जेव्हा $!A$ आणि $!B$
या समान लांबीच्या चिन्हमाला असतात आणि प्रत्येक स्थानी त्यांच्यात तेच
चिन्ह असते.
\end{defn}

source_excerpt:
\begin{thm}[\emph{Principle of induction on !!{formula}s}]
  \ollabel{thm:induction}
  If some property~$P$ holds for all the atomic !!{formula}s and is
  such that
  \begin{enumerate}
    \tagitem{prvNot}{it holds for $\lnot !A$ whenever it holds
      for~$!A$;}{}
    \tagitem{prvAnd}{it holds for $(!A \land !B)$
      whenever it holds for $!A$ and~$!B$;}{}
    \tagitem{prvOr}{it holds for $(!A \lor !B)$
      whenever it holds for $!A$ and~$!B$;}{}
    \tagitem{prvIf}{it holds for $(!A \lif !B)$
      whenever it holds for $!A$ and~$!B$;}{}
    \tagitem{prvIff}{it holds for $(!A \liff !B)$
      whenever it holds for $!A$ and~$!B$;}{}
  \end{enumerate}
  then $P$ holds for all !!{formula}s.
\end{thm}

target_excerpt:
\begin{thm}[\emph{!!{formula}s वरील विगमनाचे तत्त्व}]
  \ollabel{thm:induction}
  एखादा गुणधर्म~$P$ सर्व आण्विक !!{formula}s साठी लागू होत असेल आणि
  पुढील अटी पूर्ण करत असेल:
  \begin{enumerate}
    \tagitem{prvNot}{तो~$!A$ साठी लागू असताना $\lnot !A$ साठीही
      लागू होतो;}{ }
    \tagitem{prvAnd}{तो~$!A$ आणि~$!B$ यांच्यासाठी लागू असताना
      $(!A \land !B)$ साठीही लागू होतो;}{ }
    \tagitem{prvOr}{तो~$!A$ आणि~$!B$ यांच्यासाठी लागू असताना
      $(!A \lor !B)$ साठीही लागू होतो;}{ }
    \tagitem{prvIf}{तो~$!A$ आणि~$!B$ यांच्यासाठी लागू असताना
      $(!A \lif !B)$ साठीही लागू होतो;}{ }
    \tagitem{prvIff}{तो~$!A$ आणि~$!B$ यांच्यासाठी लागू असताना
      $(!A \liff !B)$ साठीही लागू होतो;}{ }
  \end{enumerate}
  तर $P$ सर्व !!{formula}s साठी लागू होतो.
\end{thm}

