source_excerpt:
\begin{prop}\ollabel{prop:enum-bij}
If $f\colon \PosInt \to A$ is !!{surjective} (i.e., an enumeration
of~$A$), there is !!a{bijection} $g\colon Z \to A$ where $Z$ is
either~$\PosInt$ or $\{1, \dots, n\}$ for some~$n \in \PosInt$.
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:enum-bij}
$f\colon \PosInt \to A$ हे !!{surjective} असेल (म्हणजे~$A$
चे प्रगणन असेल), तर !!a{bijection} $g\colon Z \to A$ असते,
जेथे $Z$ हा~$\PosInt$ किंवा कोणत्या तरी~$n \in \PosInt$
साठी $\{1, \dots, n\}$ असतो.
\end{prop}

source_excerpt:
\begin{cor}\ollabel{cor:enum-nat-bij}
A set $A$ is !!{enumerable} iff it is empty or there is !!a{bijection}
$f\colon N \to A$ where either $N = \Nat$ or $N = \{0, \dots, n\}$ for
some $n \in \Nat$.
\end{cor}

target_excerpt:
\begin{cor}\ollabel{cor:enum-nat-bij}
संच $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच, जेव्हा
तो रिक्त असतो किंवा !!a{bijection} $f\colon N \to A$ असते,
जेथे $N = \Nat$ किंवा कोणत्या तरी $n \in \Nat$ साठी
$N = \{0, \dots, n\}$ असते.
\end{cor}

source_excerpt:
\begin{proof}
$A$ is !!{enumerable} iff $A$ is empty or there is !!a{surjective}
$f\colon \PosInt \to A$. By \olref{prop:enum-bij}, the latter holds
iff there is !!a{bijective} function~$f\colon Z \to A$ where $Z =
\PosInt$ or $Z = \{1, \dots, n\}$ for some $n \in \PosInt$. By the
same argument as in the proof of \olref{prop:enum-shift}, that in turn
is the case iff there is !!a{bijection} $g\colon N \to A$ where either
$N = \Nat$ or $N = \{0, \dots, n-1\}$.
\end{proof}

\begin{defn}\ollabel{comparisondef}
  $A$ is \emph{equinumerous} with $B$, written $\cardeq{A}{B}$, iff
  there is !!a{bijection} $f \colon A \to B$.
\end{defn}

target_excerpt:
\begin{defn}\ollabel{comparisondef}
  $A$ हा $B$ शी \emph{तुल्यबल} असतो, आणि ते $\cardeq{A}{B}$ असे लिहितो,
  तेव्हा आणि केवळ तेव्हाच, जेव्हा $f \colon A \to B$ असे
  !!a{bijection} असते.
\end{defn}

source_excerpt:
\begin{defn}
$A$ is \emph{smaller than}~$B$, written $\cardless{A}{B}$, iff there
is !!a{injection}~$f\colon A \to B$ but no !!{bijection}~$g\colon A
\to B$, i.e., $\cardle{A}{B}$ and $\cardneq{A}{B}$.
\end{defn}

\begin{editorial}
  This section proves the non-enumerability of $\Bin^\omega$ and
  $\Pow{\Nat}$ using the definitions in \olref[enm-alt]{sec}, i.e.,
  requiring a bijection with~$\Nat$ instead of a surjection from
  $\PosInt$.
\end{editorial}

target_excerpt:
\begin{editorial}
  या विभागात \olref[enm-alt]{sec} मधील व्याख्या वापरून
  $\Bin^\omega$ आणि $\Pow{\Nat}$ यांची अगणनीयता सिद्ध केली आहे;
  म्हणजे $\PosInt$ पासून आच्छादन मागण्याऐवजी~$\Nat$ शी एकास-एक
  आच्छादन आवश्यक मानले आहे.
\end{editorial}

source_excerpt:
\begin{prop}\ollabel{sbhelper}
If $A \subseteq B \subseteq C$ and $A \approx C$, then $\cardeq{\cardeq{A}{B}}{C}$.
\end{prop}

target_excerpt:
\begin{prop}\ollabel{sbhelper}
जर $A \subseteq B \subseteq C$ आणि $A \approx C$, तर $\cardeq{B}{C}$.
\end{prop}
%READERNOTE{MRINF-003: गोठवलेल्या इंग्रजी निष्कर्षात तुल्यबलता-उक्तीच पहिला संच म्हणून बसवली आहे. गृहीतके आणि पुढील उपयोग यांवरून B आणि C तुल्यबल आहेत हाच अनिवार्य निष्कर्ष मराठीत दिला आहे.}

source_excerpt:
\begin{defn}[Function]
A \emph{function} $f \colon A \to B$ is a mapping of each !!{element}
of~$A$ to an !!{element} of~$B$.

We call $A$ the \emph{domain} of~$f$ and $B$ the \emph{codomain}
of~$f$.  The !!{element}s of~$A$ are called inputs or \emph{arguments}
of~$f$, and the !!{element} of~$B$ that is paired with an argument~$x$
by~$f$ is called the \emph{value of~$f$} for argument~$x$,
written~$f(x)$.

target_excerpt:
~$f$ ची \emph{व्याप्ती} $\ran{f}$ म्हणजे सहप्रांताचा असा उपसंच की
त्याचे घटक कोणत्या तरी फलसाधकासाठीची~$f$ ची मूल्ये असतात;
$\ran{f} = \Setabs{f(x)}{x \in A}$.
\end{defn}

source_excerpt:
\begin{figure}
  \olasset{assets/diagrams/function.tikz}
  \caption{A function is a mapping of each !!{element} of one set to
    !!a{element} of another. An arrow points from an argument in the
    domain to the corresponding value in the codomain.}
  \ollabel{fig:function}
\end{figure}

target_excerpt:
\begin{figure}
  \olasset{assets/diagrams/function.tikz}
  \caption{फलन एका संचातील प्रत्येक !!{element} ची दुसऱ्या संचातील
    !!a{element} शी संगती लावते. बाण प्रांतातील फलसाधकापासून
    सहप्रांतातील त्याच्या संगत मूल्याकडे जातो.}
  \ollabel{fig:function}
\end{figure}

source_excerpt:
\begin{ex}
Multiplication takes pairs of natural numbers as inputs and maps them
to natural numbers as outputs, so goes from $\Nat \times \Nat$ (the
domain) to $\Nat$ (the codomain). As it turns out, the range is also
$\Nat$, since every $n \in \Nat$ is $n \times 1$.
\end{ex}

target_excerpt:
\begin{ex}
गुणाकार नैसर्गिक संख्यांच्या जोड्या आदान म्हणून घेतो आणि त्यांना प्रदान
म्हणून नैसर्गिक संख्या जोडतो. म्हणून तो $\Nat \times \Nat$ या प्रांताकडून
$\Nat$ या सहप्रांताकडे जातो. त्याची व्याप्तीही $\Nat$ च असते, कारण
प्रत्येक $n \in \Nat$ हा $n \times 1$ असतो.
\end{ex}

\begin{ex}
गुणाकार हे फलन आहे, कारण तो प्रत्येक आदानाशी---नैसर्गिक संख्यांच्या
प्रत्येक जोडीशी---एकच प्रदान जोडतो: $\times \colon \Nat^2 \to \Nat$.
याउलट, नैसर्गिक संख्या~$n$ शी $x^2 = n$ असणारी वास्तव संख्या~$x$
जोडण्याची संगती फलन होत नाही, कारण प्रत्येक धन पूर्णांक~$n$ ची दोन
वर्गमुळे असतात: $\sqrt{n}$ आणि~$-\sqrt{n}$. फक्त धन वर्गमूळ देऊन
आपण तिचे फलन करू शकतो: फक्त ऋणेतर (प्रधान) वर्गमूळ परत द्यायचे,
$\sqrt{\phantom{X}} \colon \Nat \to \Real$.
\end{ex}
%READERNOTE{OLFUN-002 — गोठवलेल्या इंग्रजी स्रोतामध्ये सर्व नैसर्गिक संख्यांसाठी positive square root म्हटले आहे. शून्याचे प्रधान वर्गमूळ शून्य असल्यामुळे येथे ऋणेतर (प्रधान) असे दुरुस्त केले आहे; धन पूर्णांकांना दोन वास्तव वर्गमुळे असतात हे आधीचे विधान योग्य आहे.}

\begin{ex}
वर्गातील प्रत्येक विद्यार्थ्याशी त्याची अंतिम श्रेणी जोडणारा संबंध हे
फलन आहे---एकाच वर्गात कोणत्याही विद्यार्थ्याला दोन वेगवेगळ्या अंतिम
श्रेणी मिळू शकत नाहीत. वर्गातील प्रत्येक विद्यार्थ्याशी त्याचे पालक
जोडणारा संबंध फलन नाही: विद्यार्थ्यांचे पालक शून्य, दोन किंवा अधिक असू शकतात.
\end{ex}

\begin{ex}\ollabel{examplefunext}
$g \colon \Nat \to \Nat$ ची व्याख्या $g(x) = x+2-1$ अशी करू.
यावरून $g$ हे नैसर्गिक संख्या आदान म्हणून घेऊन नैसर्गिक संख्या प्रदान
करणारे फलन आहे हे कळते. नैसर्गिक संख्या x दिली, की $g$ हा~$x$ च्या
उत्तरवर्ती संख्येच्या उत्तरवर्ती संख्येची पूर्ववर्ती संख्या,
म्हणजेच $x+1$, देईल.
\end{ex}
%READERNOTE{OLFUN-003 — गोठवलेल्या इंग्रजी स्रोताच्या गद्यामध्ये याच उदाहरणात आदानासाठी आधी $n$ आणि लगेच x वापरले आहेत. सूत्र न बदलता मराठी गद्याने x हे एकच नाव सातत्याने वापरले आहे.}

source_excerpt:
\begin{ex}
We can also define functions by cases. For instance, we could define
$h \colon \Nat \to \Nat$  by
\[
h(x) =
\begin{cases}
  \frac{x}{2} & \text{if $x$ is even} \\
  \frac{x+1}{2} & \text{if $x$ is odd.}
\end{cases}
\]
Since every natural number is either even or odd, the output of this
function will always be a natural number. Just remember that if you
define a function by cases, every possible input must fall into
exactly one case.  In some cases, this will require a proof that the
cases are exhaustive and exclusive.
\end{ex}

target_excerpt:
\begin{ex}
प्रकरणे पाडूनही फलनाची व्याख्या करता येते. उदाहरणार्थ,
$h \colon \Nat \to \Nat$ ची व्याख्या अशी करता येईल:
\[
h(x) =
\begin{cases}
  \frac{x}{2} & \text{जर $x$ सम असेल} \\
  \frac{x+1}{2} & \text{जर $x$ विषम असेल.}
\end{cases}
\]
प्रत्येक नैसर्गिक संख्या सम किंवा विषम असते, म्हणून या फलनाचे प्रदान
नेहमी नैसर्गिक संख्या असेल. प्रकरणे पाडून फलनाची व्याख्या करताना
प्रत्येक शक्य आदान नेमक्या एका प्रकरणात बसले पाहिजे, हे लक्षात ठेवा.
काही वेळा सर्व शक्यता त्या प्रकरणांत येतात आणि कोणतीही शक्यता दोन
प्रकरणांत येत नाही याची सिद्धता करावी लागेल.
\end{ex}

source_excerpt:
\begin{explain}
It will be useful to introduce a kind of taxonomy for some of the
kinds of functions which we encounter most frequently.

target_excerpt:
\begin{explain}
आपल्याला वारंवार भेटणाऱ्या फलनांच्या काही प्रकारांचे वर्गीकरण करून
घेणे उपयोगी ठरेल.

source_excerpt:
\begin{figure}
  \olasset{assets/diagrams/surjective.tikz}
  \caption{!!^a{surjective} function has every !!{element} of the
    codomain as a value.}
  \ollabel{fig:surjective}
\end{figure}
\end{explain}

target_excerpt:
\begin{figure}
  \olasset{assets/diagrams/surjective.tikz}
  \caption{!!^a{surjective} फलनात सहप्रांतातील प्रत्येक !!{element}
    हे फलनाचे मूल्य असते.}
  \ollabel{fig:surjective}
\end{figure}
\end{explain}

\begin{explain}
$f$ हे !!a{surjection} आहे असे दाखवायचे असल्यास, $f$ च्या सहप्रांतातील
प्रत्येक वस्तू कोणत्या तरी आदान $x$ साठी $f(x)$ चे मूल्य आहे असे दाखवावे लागते.

source_excerpt:
Note that any function \emph{induces} !!a{surjection}. After all,
given a function $f \colon A \to B$, let $f' \colon A \to \ran{f}$ be
defined by $f'(x) = f(x)$. Since $\ran{f}$ is \emph{defined} as
$\Setabs{f(x) \in B}{x \in A}$, this function $f'$ is guaranteed to be
!!a{surjection}
\end{explain}

target_excerpt:
कोणत्याही फलनापासून एक !!a{surjection} \emph{निर्माण होते}, हे लक्षात घ्या.
कारण $f \colon A \to B$ हे फलन दिले असल्यास, $f' \colon A \to \ran{f}$
ची व्याख्या $f'(x) = f(x)$ अशी करू. $\ran{f}$ ची \emph{व्याख्याच}
$\Setabs{f(x) \in B}{x \in A}$ अशी असल्यामुळे हे फलन $f'$ निश्चितच
!!a{surjection} असते.
\end{explain}

source_excerpt:
\begin{explain}
Now, any function maps each possible input to a unique output. But
there are also functions which never map different inputs to the same
outputs. Such functions are called !!{injective}, and can be pictured
as in \olref{fig:injective}.
\begin{figure}
  \olasset{assets/diagrams/injective.tikz}
  \caption{!!^a{injective} function never maps two different
    arguments to the same value.}
  \ollabel{fig:injective}
\end{figure}
\end{explain}

target_excerpt:
\begin{explain}
कोणतेही फलन प्रत्येक शक्य आदानाशी एकमेव प्रदान जोडते. पण वेगवेगळ्या
आदानांशी कधीच एकच प्रदान न जोडणारी फलनेही असतात. अशा फलनांना
!!{injective} म्हणतात. त्यांची आकृती \olref{fig:injective} प्रमाणे काढता येते.
\begin{figure}
  \olasset{assets/diagrams/injective.tikz}
  \caption{!!^a{injective} फलन कधीच दोन वेगवेगळ्या फलसाधकांशी
    एकच मूल्य जोडत नाही.}
  \ollabel{fig:injective}
\end{figure}
\end{explain}

source_excerpt:
\begin{explain}
If you want to show that $f$ is !!a{injection}, you need to show that
for any !!{element}s $x$ and $y$ of $f$'s domain, if $f(x)=f(y)$, then
$x=y$.
\end{explain}

target_excerpt:
\begin{explain}
$f$ हे !!a{injection} आहे असे दाखवायचे असल्यास, $f$ च्या प्रांतातील
कोणत्याही !!{element}s $x$ आणि $y$ साठी $f(x)=f(y)$ असल्यास $x=y$
असते असे दाखवावे लागते.
\end{explain}

source_excerpt:
\begin{ex}
The constant function $f\colon \Nat \to \Nat$ given by $f(x) = 1$ is
neither !!{injective}, nor !!{surjective}.

target_excerpt:
\begin{ex}
$f(x) = 1$ ने दिलेले स्थिर फलन $f\colon \Nat \to \Nat$ हे
!!{injective} ही नाही आणि !!{surjective} ही नाही.

source_excerpt:
The function $f \colon \Nat \to \Nat$ defined by:
\[
  f(x) =
  \begin{cases}
    \frac{x}{2} & \text{if $x$ is even} \\
    \frac{x+1}{2} & \text{if $x$ is odd.}
  \end{cases}
\]
is !!{surjective}, but not !!{injective}.
\end{ex}

target_excerpt:
पुढीलप्रमाणे व्याख्या केलेले फलन $f \colon \Nat \to \Nat$:
\[
  f(x) =
  \begin{cases}
    \frac{x}{2} & \text{जर $x$ सम असेल} \\
    \frac{x+1}{2} & \text{जर $x$ विषम असेल.}
  \end{cases}
\]
हे !!{surjective} आहे, पण !!{injective} नाही.
\end{ex}

source_excerpt:
\begin{explain}
Often enough, we want to consider functions which are both
!!{injective} and !!{surjective}. We call such functions
!!{bijective}. They look like the function pictured in
\olref{fig:bijective}. !!^{bijection}s are also sometimes called
\emph{one-to-one correspondences}, since they uniquely pair elements
of the codomain with elements of the domain.
\begin{figure}
  \olasset{assets/diagrams/bijective.tikz}
  \caption{!!^a{bijective} function uniquely pairs the elements of the
    codomain with those of the domain.}
  \ollabel{fig:bijective}
\end{figure}
\end{explain}

target_excerpt:
\begin{explain}
अनेकदा !!{injective} आणि !!{surjective} हे दोन्ही गुणधर्म असलेल्या
फलनांचा विचार करायचा असतो. अशा फलनांना !!{bijective} म्हणतो.
ती \olref{fig:bijective} मधील फलनासारखी दिसतात. !!^{bijection}s ना
कधी कधी \emph{एकास-एक संगती} असेही म्हणतात, कारण ती सहप्रांतातील
घटकांची प्रांतातील घटकांशी एकमेव जोडी लावतात.
\begin{figure}
  \olasset{assets/diagrams/bijective.tikz}
  \caption{!!^a{bijective} फलन सहप्रांतातील घटकांची प्रांतातील
    घटकांशी एकमेव जोडी लावते.}
  \ollabel{fig:bijective}
\end{figure}
\end{explain}

source_excerpt:
\begin{ex}
A function enumerating the positive integers ($\PosInt$) is simply the
identity function given by $f(n) = n$. A function enumerating the
natural numbers $\Nat$ is the function $g(n) = n - 1$.
\end{ex}

target_excerpt:
\begin{ex}
धन पूर्णांकांचे ($\PosInt$) प्रगणन करणारे फलन म्हणजे फक्त
$f(n) = n$ ने दिलेले एकरूपता फलन. नैसर्गिक संख्या $\Nat$ यांचे
प्रगणन करणारे फलन म्हणजे $g(n) = n - 1$.
\end{ex}

source_excerpt:
\begin{ex}
A function enumerating the natural numbers is simply the identity
function $\Id{\Nat} \colon \Nat \to \Nat$ given by $\Id{\Nat}(n) = n$. A
function enumerating the \emph{positive} natural numbers, $\Nat^+ =
\Nat \setminus \{0\}$, is the function $g(n) = n + 1$, i.e., the
successor function.
\end{ex}

target_excerpt:
\begin{ex}
नैसर्गिक संख्यांचे प्रगणन करणारे फलन म्हणजे फक्त $\Id{\Nat} \colon
\Nat \to \Nat$ हे $\Id{\Nat}(n) = n$ ने दिलेले एकरूपता फलन.
\emph{धन} नैसर्गिक संख्या $\Nat^+ = \Nat \setminus \{0\}$ यांचे
प्रगणन करणारे फलन $g(n) = n + 1$ आहे; म्हणजेच ते उत्तरवर्ती फलन आहे.
\end{ex}

हे केल्यानंतर, नेहमीप्रमाणे, $f$ हा !!a{element} असलेल्या तुल्यतावर्गासाठी
आपण $\equivrep{f}{\Realequiv}$ असे लिहू. मात्र मजकूर वाचनीय ठेवण्यासाठी
पुढे अधोलिखित भाग वगळून फक्त $\equivrep{f}{}$ असे लिहू. प्रत्येक $q
\in \Rat$ साठी $q_{\Real} = \equivrep{c_{q}}{}$ असेही आपण ठरवतो,
जिथे प्रत्येक $n \in \Nat$ साठी $c_q(n) = q$ असे स्थिर फलन $c_{q}$
आहे. मग वास्तव संख्यांवरील मूलभूत संबंध आणि क्रिया परिभाषित करतो;
उदाहरणार्थ:
\begin{align*}
    \equivrep{f}{} + \equivrep{g}{} &=  \equivrep{(f + g)}{} \\
    \equivrep{f}{} \times   \equivrep{g}{} &= \equivrep{(f \times g)}{}
\end{align*}
जिथे $(f + g)(n) = f(n) + g(n)$ आणि $(f \times g)(n) = f(n) \times
g(n)$. $f$ आणि $g$ कोशी क्रमिका असतील तेव्हा $(f + g)$, $(f-g)$ आणि
$(f\times g)$ यांपैकी प्रत्येकही कोशी क्रमिका आहे हे अर्थात तपासावे
लागेल; तसे ते आहेत, आणि ही सिद्धता तुमच्यासाठी सोडली आहे.
%READERNOTE{MRARITH-012: गोठवलेला मजकूर येथे बेरीज, वजाबाकी आणि गुणाकाराने कोशी क्रमिका मिळतात एवढीच संवृति तपासायला सांगतो. तुल्यतावर्गांवरील क्रिया सुव्याख्यायित होण्यासाठी प्रतिनिधी बदलल्यावर वर्ग बदलत नाही हेही तपासणे आवश्यक आहे; तो स्वतंत्र तपशील स्रोतामध्ये दिलेला नाही.}

source_excerpt:
\begin{defn}
A function $g \colon B \to A$ is an \emph{inverse} of a function $f
\colon A \to B$ if $f(g(y)) = y$ and $g(f(x)) = x$ for all $x \in A$
and $y \in B$.
\end{defn}

target_excerpt:
\begin{defn}
सर्व $x \in A$ आणि $y \in B$ साठी $f(g(y)) = y$ आणि $g(f(x)) = x$
असेल, तर $g \colon B \to A$ हे फलन $f \colon A \to B$ या फलनाचा
\emph{व्युत्क्रम} असते.
\end{defn}

source_excerpt:
\begin{prop}
If $f\colon A \to B$ is !!{injective}, then there is a \emph{left
inverse}~$g\colon B \to A$ of~$f$ so that $g(f(x)) = x$ for all $x
\in A$.
\end{prop}

target_excerpt:
\begin{prop}
A अरिक्त असेल आणि $f\colon A \to B$ हे !!{injective} असेल,
तर~$f$ चा एक
\emph{डावा व्युत्क्रम}~$g\colon B \to A$ असतो, आणि सर्व $x \in A$
साठी $g(f(x)) = x$ असते.
\end{prop}
%READERNOTE{OLFUN-001 — गोठवलेल्या इंग्रजी प्रमेयात A अरिक्त असण्याची अट सुटली आहे. रिक्त A पासून अरिक्त B कडेचे रिक्त फलन एकास-एक असूनही B पासून A कडे फलन नसते. नेमकी सामान्य अट: एकास-एक फलनाला डावा व्युत्क्रम तेव्हा आणि केवळ तेव्हाच असतो, जेव्हा A अरिक्त असतो किंवा B रिक्त असतो. मराठी प्रमेयात साधी पुरेशी A अरिक्त ही अट जोडली आहे.}

source_excerpt:
\begin{prob}
Show that if $f\colon A \to B$ has a left inverse~$g$, then $f$~is
!!{injective}.
\end{prob}

target_excerpt:
\begin{prob}
$f\colon A \to B$ ला डावा व्युत्क्रम~$g$ असल्यास $f$ हे
!!{injective} असते, हे दाखवा.
\end{prob}

source_excerpt:
\begin{prop}
    If $f\colon A \to B$ is !!{surjective}, then there is a
    \emph{right inverse}~$h\colon B \to A$ of~$f$ so that $f(h(y)) =
    y$ for all~$y \in B$.
\end{prop}

target_excerpt:
\begin{prop}
    $f\colon A \to B$ हे !!{surjective} असेल, तर~$f$ चा एक
    \emph{उजवा व्युत्क्रम}~$h\colon B \to A$ असतो, आणि सर्व~$y \in B$
    साठी $f(h(y)) = y$ असते.
\end{prop}

source_excerpt:
\begin{prob}
Show that if $f\colon A \to B$ has a right inverse~$h$, then $f$~is
!!{surjective}.
\end{prob}

target_excerpt:
\begin{prob}
$f\colon A \to B$ ला उजवा व्युत्क्रम~$h$ असल्यास $f$ हे
!!{surjective} असते, हे दाखवा.
\end{prob}

source_excerpt:
\begin{explain}
  By combining the ideas in the previous proof, we now get that every
  !!{bijection} has an inverse, i.e., there is a single function
  which is both a left and right inverse of~$f$.
\end{explain}

target_excerpt:
\begin{explain}
  मागील सिद्धतेतील कल्पना एकत्र केल्यावर प्रत्येक !!{bijection} ला
  व्युत्क्रम असतो हे मिळते. म्हणजे~$f$ चा डावा आणि उजवा व्युत्क्रम
  असे दोन्ही असणारे एकच फलन असते.
\end{explain}

source_excerpt:
\begin{prop}\ollabel{prop:bijection-inverse}
If $f\colon A \to B$ is !!{bijective}, there is a
function~$f^{-1}\colon B \to A$ so that for all $x \in A$,
$f^{-1}(f(x)) = x$ and for all $y \in B$, $f(f^{-1}(y)) = y$.
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:bijection-inverse}
$f\colon A \to B$ हे !!{bijective} असेल, तर एक
फलन~$f^{-1}\colon B \to A$ असते, आणि सर्व $x \in A$ साठी
$f^{-1}(f(x)) = x$ तसेच सर्व $y \in B$ साठी $f(f^{-1}(y)) = y$ असते.
\end{prop}

source_excerpt:
\begin{proof}
Exercise.
\end{proof}

target_excerpt:
\begin{proof}
सरावासाठी.
\end{proof}

source_excerpt:
\begin{prob}
Prove \olref[sfr][fun][inv]{prop:bijection-inverse}. You have to
define~$f^{-1}$, show that it is a function, and show that it is an
inverse of~$f$, i.e., $f^{-1}(f(x)) = x$ and $f(f^{-1}(y)) = y$ for
all $x \in A$ and $y \in B$.
\end{prob}

target_excerpt:
\begin{prob}
\olref[sfr][fun][inv]{prop:bijection-inverse} सिद्ध करा. ~$f^{-1}$ ची
व्याख्या करा, ते फलन आहे हे दाखवा आणि ते~$f$ चा व्युत्क्रम आहे हे
दाखवा. म्हणजे, सर्व $x \in A$ आणि $y \in B$ साठी
$f^{-1}(f(x)) = x$ आणि $f(f^{-1}(y)) = y$ हे दाखवा.
\end{prob}

\begin{explain}
व्युत्क्रम मिळवण्याची थोडी अधिक व्यापक पद्धत आहे. \olref[kin]{sec}
मध्ये आपण पाहिले की प्रत्येक फलन $f$ पासून सर्व $x \in A$ साठी
$f'(x) = f(x)$ असे ठेवून !!a{surjection} $f' \colon A \to \ran{f}$
मिळते. उघडच, ~$f$ हे !!{injective} असेल, तर~$f'$ हे !!{bijective}
असते. म्हणून \olref{prop:bijection-inverse} नुसार त्याला एकमेव
व्युत्क्रम असतो. संकेतलेखनात अगदी थोडी सवलत घेऊन आपण कधी कधी
$f'$ च्या व्युत्क्रमाला फक्त ``~$f$ चा व्युत्क्रम'' म्हणतो.
\end{explain}

