source_excerpt:
\begin{defn}
A function $g \colon B \to A$ is an \emph{inverse} of a function $f
\colon A \to B$ if $f(g(y)) = y$ and $g(f(x)) = x$ for all $x \in A$
and $y \in B$.
\end{defn}

target_excerpt:
\begin{defn}
सर्व $x \in A$ आणि $y \in B$ साठी $f(g(y)) = y$ आणि $g(f(x)) = x$
असेल, तर $g \colon B \to A$ हे फलन $f \colon A \to B$ या फलनाचा
\emph{व्युत्क्रम} असते.
\end{defn}

source_excerpt:
\begin{prop}
If $f\colon A \to B$ is !!{injective}, then there is a \emph{left
inverse}~$g\colon B \to A$ of~$f$ so that $g(f(x)) = x$ for all $x
\in A$.
\end{prop}

target_excerpt:
\begin{prop}
A अरिक्त असेल आणि $f\colon A \to B$ हे !!{injective} असेल,
तर~$f$ चा एक
\emph{डावा व्युत्क्रम}~$g\colon B \to A$ असतो, आणि सर्व $x \in A$
साठी $g(f(x)) = x$ असते.
\end{prop}
%READERNOTE{OLFUN-001 — गोठवलेल्या इंग्रजी प्रमेयात A अरिक्त असण्याची अट सुटली आहे. रिक्त A पासून अरिक्त B कडेचे रिक्त फलन एकास-एक असूनही B पासून A कडे फलन नसते. नेमकी सामान्य अट: एकास-एक फलनाला डावा व्युत्क्रम तेव्हा आणि केवळ तेव्हाच असतो, जेव्हा A अरिक्त असतो किंवा B रिक्त असतो. मराठी प्रमेयात साधी पुरेशी A अरिक्त ही अट जोडली आहे.}

source_excerpt:
\begin{prob}
Show that if $f\colon A \to B$ has a left inverse~$g$, then $f$~is
!!{injective}.
\end{prob}

target_excerpt:
\begin{prob}
$f\colon A \to B$ ला डावा व्युत्क्रम~$g$ असल्यास $f$ हे
!!{injective} असते, हे दाखवा.
\end{prob}

source_excerpt:
\begin{prop}
    If $f\colon A \to B$ is !!{surjective}, then there is a
    \emph{right inverse}~$h\colon B \to A$ of~$f$ so that $f(h(y)) =
    y$ for all~$y \in B$.
\end{prop}

target_excerpt:
\begin{prop}
    $f\colon A \to B$ हे !!{surjective} असेल, तर~$f$ चा एक
    \emph{उजवा व्युत्क्रम}~$h\colon B \to A$ असतो, आणि सर्व~$y \in B$
    साठी $f(h(y)) = y$ असते.
\end{prop}

source_excerpt:
\begin{prob}
Show that if $f\colon A \to B$ has a right inverse~$h$, then $f$~is
!!{surjective}.
\end{prob}

target_excerpt:
\begin{prob}
$f\colon A \to B$ ला उजवा व्युत्क्रम~$h$ असल्यास $f$ हे
!!{surjective} असते, हे दाखवा.
\end{prob}

source_excerpt:
\begin{explain}
  By combining the ideas in the previous proof, we now get that every
  !!{bijection} has an inverse, i.e., there is a single function
  which is both a left and right inverse of~$f$.
\end{explain}

target_excerpt:
\begin{explain}
  मागील सिद्धतेतील कल्पना एकत्र केल्यावर प्रत्येक !!{bijection} ला
  व्युत्क्रम असतो हे मिळते. म्हणजे~$f$ चा डावा आणि उजवा व्युत्क्रम
  असे दोन्ही असणारे एकच फलन असते.
\end{explain}

source_excerpt:
\begin{prop}\ollabel{prop:bijection-inverse}
If $f\colon A \to B$ is !!{bijective}, there is a
function~$f^{-1}\colon B \to A$ so that for all $x \in A$,
$f^{-1}(f(x)) = x$ and for all $y \in B$, $f(f^{-1}(y)) = y$.
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:bijection-inverse}
$f\colon A \to B$ हे !!{bijective} असेल, तर एक
फलन~$f^{-1}\colon B \to A$ असते, आणि सर्व $x \in A$ साठी
$f^{-1}(f(x)) = x$ तसेच सर्व $y \in B$ साठी $f(f^{-1}(y)) = y$ असते.
\end{prop}

source_excerpt:
\begin{proof}
Exercise.
\end{proof}

target_excerpt:
\begin{proof}
सरावासाठी.
\end{proof}

source_excerpt:
\begin{prob}
Prove \olref[sfr][fun][inv]{prop:bijection-inverse}. You have to
define~$f^{-1}$, show that it is a function, and show that it is an
inverse of~$f$, i.e., $f^{-1}(f(x)) = x$ and $f(f^{-1}(y)) = y$ for
all $x \in A$ and $y \in B$.
\end{prob}

target_excerpt:
\begin{prob}
\olref[sfr][fun][inv]{prop:bijection-inverse} सिद्ध करा. ~$f^{-1}$ ची
व्याख्या करा, ते फलन आहे हे दाखवा आणि ते~$f$ चा व्युत्क्रम आहे हे
दाखवा. म्हणजे, सर्व $x \in A$ आणि $y \in B$ साठी
$f^{-1}(f(x)) = x$ आणि $f(f^{-1}(y)) = y$ हे दाखवा.
\end{prob}

\begin{explain}
व्युत्क्रम मिळवण्याची थोडी अधिक व्यापक पद्धत आहे. \olref[kin]{sec}
मध्ये आपण पाहिले की प्रत्येक फलन $f$ पासून सर्व $x \in A$ साठी
$f'(x) = f(x)$ असे ठेवून !!a{surjection} $f' \colon A \to \ran{f}$
मिळते. उघडच, ~$f$ हे !!{injective} असेल, तर~$f'$ हे !!{bijective}
असते. म्हणून \olref{prop:bijection-inverse} नुसार त्याला एकमेव
व्युत्क्रम असतो. संकेतलेखनात अगदी थोडी सवलत घेऊन आपण कधी कधी
$f'$ च्या व्युत्क्रमाला फक्त ``~$f$ चा व्युत्क्रम'' म्हणतो.
\end{explain}

source_excerpt:
\begin{proof}
  Exercise.
\end{proof}

target_excerpt:
\begin{proof}
  सरावासाठी.
\end{proof}

source_excerpt:
\begin{prob}
  Prove \olref[sfr][fun][inv]{prop:left-right}.
\end{prob}

target_excerpt:
\begin{prob}
  \olref[sfr][fun][inv]{prop:left-right} सिद्ध करा.
\end{prob}

source_excerpt:
\begin{prop}\ollabel{prop:inverse-unique}
Every function~$f$ has at most one inverse.
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:inverse-unique}
प्रत्येक फलन~$f$ ला जास्तीत जास्त एक व्युत्क्रम असतो.
\end{prop}

source_excerpt:
\begin{proof}
  Suppose $g$ and $h$ are both inverses of~$f$. Then in particular
  $g$~is a left inverse of~$f$ and $h$~is a right inverse. By
  \olref{prop:left-right}, $g = h$.
\end{proof}

target_excerpt:
\begin{proof}
  $g$ आणि $h$ हे दोन्ही~$f$ चे व्युत्क्रम आहेत असे समजा. मग विशेषतः
  ~$g$ हा~$f$ चा डावा व्युत्क्रम आणि~$h$ हा उजवा व्युत्क्रम असतो.
  \olref{prop:left-right} नुसार $g = h$.
\end{proof}

source_excerpt:
\begin{editorial}
This chapter discusses enumerations, countability and uncountability.
Several sections come in two versions: a more elementary one, that
takes enumerations to be lists, or surjections from $\PosInt$; and a
more abstract one that defines enumerations as bijections with $\Nat$.
\end{editorial}

target_excerpt:
\begin{editorial}
या प्रकरणात प्रगणने, गणनीयता आणि अगणनीयता यांची चर्चा आहे.
काही विभागांच्या दोन आवृत्त्या आहेत: अधिक प्राथमिक आवृत्तीत प्रगणने
म्हणजे याद्या किंवा $\PosInt$ पासूनची आच्छादने मानली आहेत;
अधिक अमूर्त आवृत्तीत प्रगणनांची व्याख्या $\Nat$ बरोबरच्या
एकास-एक आच्छादनांनी केली आहे.
\end{editorial}

\begin{editorial}
पुढील \olref[sfr][siz][enm-alt]{sec},
\olref[sfr][siz][nen-alt]{sec} आणि \olref[sfr][siz][red-alt]{sec}
हे अनुक्रमे \olref[sfr][siz][enm]{sec},
\olref[sfr][siz][nen]{sec} आणि \olref[sfr][siz][red]{sec}
यांचे पर्यायी विभाग आहेत. टिम बटन यांनी त्यांच्या Open Set Theory
या ग्रंथात वापरण्यासाठी ते तयार केले. ते किंचित अधिक प्रगत आहेत आणि
संच सिद्धांताच्या संदर्भात अधिक योग्य अशी गणनीयतेची भिन्न व्याख्या
वापरतात: यादी देता येणे किंवा $\PosInt$ पासूनच्या आच्छादक फलनाची
व्याप्ती असणे याऐवजी $\Nat$ किंवा त्याच्या आरंभीच्या खंडाशी एकास-एक
आच्छादन असणे.
\end{editorial}

source_excerpt:
\begin{explain}
We've already given examples of sets by listing their !!{element}s.
Let's discuss in more general terms how and when we can list the
!!{element}s of a set, even if that set is infinite.
\end{explain}

target_excerpt:
\begin{explain}
संचांचे !!{element}s यादीत देऊन आपण आधीच संचांची उदाहरणे दिली आहेत.
संच अनंत असला, तरी त्याच्या !!{element}s ची यादी कशी आणि कधी
देता येते, याची आता अधिक व्यापकपणे चर्चा करू.
\end{explain}

source_excerpt:
\begin{prop}
  If $A$ has an enumeration, it has an enumeration without
  repetitions.
\end{prop}

target_excerpt:
\begin{prop}
  $A$ चे प्रगणन असेल, तर त्याचे पुनरुक्ती नसलेले प्रगणनही असते.
\end{prop}

source_excerpt:
\begin{defn}
  \ollabel{defn:enumerable}
  A set~$A$ is !!{enumerable} iff it is empty or has an enumeration.
\end{defn}

target_excerpt:
\begin{defn}
  \ollabel{defn:enumerable}
  संच~$A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच,
  जेव्हा तो रिक्त असतो किंवा त्याचे प्रगणन असते.
\end{defn}

source_excerpt:
\begin{ex}
A function enumerating the positive integers ($\PosInt$) is simply the
identity function given by $f(n) = n$. A function enumerating the
natural numbers $\Nat$ is the function $g(n) = n - 1$.
\end{ex}

target_excerpt:
\begin{ex}
धन पूर्णांकांचे ($\PosInt$) प्रगणन करणारे फलन म्हणजे फक्त
$f(n) = n$ ने दिलेले एकरूपता फलन. नैसर्गिक संख्या $\Nat$ यांचे
प्रगणन करणारे फलन म्हणजे $g(n) = n - 1$.
\end{ex}

source_excerpt:
\begin{ex}
The functions $f\colon \PosInt \to \PosInt$ and $g \colon \PosInt \to
\PosInt$ given by
\begin{align*}
f(n) & = 2n \text{ and}\\
g(n) & = 2n - 1
\end{align*}
enumerate the even positive integers and the odd positive integers,
respectively. However, neither function is an enumeration of
$\PosInt$, since neither is !!{surjective}.
\end{ex}

target_excerpt:
\begin{ex}
$f\colon \PosInt \to \PosInt$ आणि $g \colon \PosInt \to \PosInt$
ही फलने अशी दिली आहेत:
\begin{align*}
f(n) & = 2n \text{ आणि}\\
g(n) & = 2n - 1
\end{align*}
ती अनुक्रमे सम धन पूर्णांकांचे आणि विषम धन पूर्णांकांचे प्रगणन करतात.
मात्र यांपैकी कोणतेही फलन $\PosInt$ चे प्रगणन नाही, कारण कोणतेही
!!{surjective} नाही.
\end{ex}

source_excerpt:
\begin{prob}
Define an enumeration of the positive squares $1$, $4$, $9$, $16$, \dots
\end{prob}

target_excerpt:
\begin{prob}
धन वर्गसंख्या $1$, $4$, $9$, $16$, \dots{} यांचे प्रगणन परिभाषित करा.
\end{prob}

source_excerpt:
\begin{ex}
The function $f(n) = (-1)^{n} \lceil \frac{(n-1)}{2}\rceil$ (where
$\lceil x \rceil$ denotes the \emph{ceiling} function, which rounds
$x$ up to the nearest integer) enumerates the set of
integers~$\Int$. Notice how $f$ generates the values of $\Int$ by
``hopping'' back and forth between positive and negative integers:
\[
\begin{array}{c c c c c c c c}
f(1) & f(2) & f(3) & f(4) & f(5) & f(6) & f(7) & \dots \\ \\
- \lceil \tfrac{0}{2} \rceil & \lceil \tfrac{1}{2}\rceil & - \lceil \tfrac{2}{2} \rceil & \lceil \tfrac{3}{2} \rceil & - \lceil \tfrac{4}{2} \rceil  & \lceil \tfrac{5}{2}
\rceil & - \lceil \tfrac{6}{2} \rceil & \dots \\ \\
0 & 1 & -1 & 2 & -2 & 3 & \dots
\end{array}
\]
You can also think of $f$ as defined by cases as follows:
\[
f(n) = \begin{cases}
  0 & \text{if $n = 1$}\\
  n/2 & \text{if $n$ is even}\\
  -(n-1)/2 & \text{if $n$ is odd and $>1$}
  \end{cases}
\]
\end{ex}

target_excerpt:
\begin{ex}
$f(n) = (-1)^{n} \lceil \frac{(n-1)}{2}\rceil$ हे फलन पूर्णांकांचा
संच~$\Int$ प्रगणित करते. येथे $\lceil x \rceil$ हे
\emph{ऊर्ध्व पूर्णांक फलन} दर्शवते; ते $x$ ला त्याच्यापेक्षा कमी
नसलेल्या सर्वांत जवळच्या पूर्णांकाकडे नेते. धन आणि ऋण पूर्णांकांमध्ये
आलटूनपालटून ``उड्या मारून'' $f$ हे $\Int$ ची मूल्ये कशी निर्माण
करते ते पाहा:
\[
\begin{array}{c c c c c c c c}
f(1) & f(2) & f(3) & f(4) & f(5) & f(6) & f(7) & \dots \\ \\
- \lceil \tfrac{0}{2} \rceil & \lceil \tfrac{1}{2}\rceil & - \lceil \tfrac{2}{2} \rceil & \lceil \tfrac{3}{2} \rceil & - \lceil \tfrac{4}{2} \rceil  & \lceil \tfrac{5}{2}
\rceil & - \lceil \tfrac{6}{2} \rceil & \dots \\ \\
0 & 1 & -1 & 2 & -2 & 3 & -3 & \dots
\end{array}
\]
%READERNOTE{OLSIZ-001: गोठवलेल्या इंग्रजी तक्त्याच्या शेवटच्या ओळीत f(7) साठी अपेक्षित −3 हे मूल्य सुटले आहे; सूत्र आणि वरील दोन ओळी ते मूल्य निश्चित करतात. मराठी तक्त्यात −3 समाविष्ट करून ही उणीव दुरुस्त केली आहे.}
$f$ ची व्याख्या पुढीलप्रमाणे प्रकरणे पाडून केली आहे असेही मानता येते:
\[
f(n) = \begin{cases}
  0 & \text{जर $n = 1$ असेल}\\
  n/2 & \text{जर $n$ सम असेल}\\
  -(n-1)/2 & \text{जर $n$ विषम आणि $>1$ असेल}
  \end{cases}
\]
\end{ex}

source_excerpt:
\begin{prob}
  Show that if $A$ and $B$ are !!{enumerable}, so is $A \cup B$. To do
  this, suppose there are !!{surjective} functions $f\colon \PosInt \to
  A$ and $g\colon \PosInt \to B$, and define !!a{surjective}
  function~$h\colon \PosInt \to A \cup B$ and prove that it is
  !!{surjective}. Also consider the cases where $A$ or~$B = \emptyset$.
\end{prob}

\begin{prob}
  Show that if $B \subseteq A$ and $A$ is !!{enumerable}, so is~$B$. To
  do this, suppose there is !!a{surjective} function $f\colon \PosInt \to
  A$. Define !!a{surjective} function~$g\colon \PosInt \to B$ and prove
  that it is !!{surjective}. What happens if $B = \emptyset$?
\end{prob}

target_excerpt:
\begin{prob}
  $B \subseteq A$ आणि $A$ हा !!{enumerable} असेल, तर~$B$ हाही
  गणनीय असतो, हे दाखवा. यासाठी एक !!a{surjective} फलन
  $f\colon \PosInt \to A$ आहे असे समजा. एक !!a{surjective}
  फलन~$g\colon \PosInt \to B$ परिभाषित करा आणि ते
  !!{surjective} आहे हे सिद्ध करा. $B = \emptyset$ असल्यास काय होते?
\end{prob}

source_excerpt:
\begin{prob}
  Show by induction on $n$ that if $A_1$, $A_2$, \dots, $A_n$ are all
  !!{enumerable}, so is $A_1 \cup \dots \cup A_n$. You may assume the
  fact that if two sets $A$ and~$B$ are !!{enumerable}, so is~$A \cup
  B$.
\end{prob}

\begin{prop}\ollabel{prop:enum-bij}
If $f\colon \PosInt \to A$ is !!{surjective} (i.e., an enumeration
of~$A$), there is !!a{bijection} $g\colon Z \to A$ where $Z$ is
either~$\PosInt$ or $\{1, \dots, n\}$ for some~$n \in \PosInt$.
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:enum-bij}
$f\colon \PosInt \to A$ हे !!{surjective} असेल (म्हणजे~$A$
चे प्रगणन असेल), तर !!a{bijection} $g\colon Z \to A$ असते,
जेथे $Z$ हा~$\PosInt$ किंवा कोणत्या तरी~$n \in \PosInt$
साठी $\{1, \dots, n\}$ असतो.
\end{prop}

  फलन $g$ हे !!{surjective} आहे, कारण~$A$ मधील कोणताही घटक
  $f(1)$, $f(2)$, \dots{} यांमध्ये येतो ($f$ हे !!{surjective}
  असल्यामुळे), आणि म्हणून कधी ना कधी तो कोणत्या तरी~$i$
  साठीचे~$g(i)$ चे मूल्य होईल. ते !!{injective} ही आहे:
  $g(j) = g(i)$ असणारे $j < i$ असते, तर $g(i)$ हे मूल्य
  आधीच $g(1)$, \dots, $g(i-1)$ यांमध्ये आलेले असते;
  पण हे~$g$ च्या आपल्या व्याख्येविरुद्ध आहे.
\end{proof}

source_excerpt:
\begin{proof}
$A$ is !!{enumerable} iff $A$ is empty or there is !!a{surjective}
$f\colon \PosInt \to A$. By \olref{prop:enum-bij}, the latter holds
iff there is !!a{bijective} function~$f\colon Z \to A$ where $Z =
\PosInt$ or $Z = \{1, \dots, n\}$ for some $n \in \PosInt$. By the
same argument as in the proof of \olref{prop:enum-shift}, that in turn
is the case iff there is !!a{bijection} $g\colon N \to A$ where either
$N = \Nat$ or $N = \{0, \dots, n-1\}$.
\end{proof}

\begin{prob}
  According to \olref[sfr][siz][enm]{defn:enumerable}, a set $A$ is
  enumerable iff $A = \emptyset$ or there is !!a{surjective} $f\colon
  \PosInt \to A$.  It is also possible to define ``!!{enumerable} set''
  precisely by: a set is enumerable iff there is !!a{injective}
  function $g\colon A \to \PosInt$.  Show that the definitions are
  equivalent, i.e., show that there is !!a{injective} function
  $g\colon A \to \PosInt$ iff either $A = \emptyset$ or there is
  !!a{surjective} $f\colon \PosInt \to A$.
\end{prob}

This function $g$ is the \emph{inverse} of an enumeration of a set of
pairs. Such functions are called \emph{pairing functions}.
\end{explain}

target_excerpt:
हे फलन $g$ म्हणजे जोड्यांच्या संचाच्या एका प्रगणनाचे \emph{व्युत्क्रम}
आहे. अशा फलनांना \emph{जोडीकरण फलने} म्हणतात.
\end{explain}

source_excerpt:
\begin{prob}
Give an enumeration of the set of all non-negative rational numbers.
\end{prob}

target_excerpt:
\begin{prob}
सर्व ऋणेतर परिमेय संख्यांच्या संचाचे एक प्रगणन द्या.
\end{prob}

source_excerpt:
\begin{prob}
Show that $\Rat$ is !!{enumerable}. Recall that any rational number
can be written as a fraction $z/m$ with $z \in \Int$, $m \in \Nat^+$.
\end{prob}

target_excerpt:
\begin{prob}
$\Rat$ हा !!{enumerable} आहे, हे दाखवा. कोणतीही परिमेय संख्या
$z/m$ या अपूर्णांकाच्या रूपात लिहिता येते, जेथे $z \in \Int$ आणि
$m \in \Nat^+$ असतात, हे आठवा.
\end{prob}

source_excerpt:
\begin{prob}
Define an enumeration of $\Bin^*$.
\end{prob}

target_excerpt:
\begin{prob}
$\Bin^*$ चे एक प्रगणन परिभाषित करा.
\end{prob}

source_excerpt:
\begin{prob}
Let $f \colon A \times B \to \Nat$ be an arbitrary pairing function.
Show that the inverse of $f$ is an enumeration of $A \times B$.
\end{prob}

target_excerpt:
\begin{prob}
$f \colon A \times B \to \Nat$ हे कोणतेही जोडीकरण फलन असू द्या.
हे $f$ आच्छादकही असेल, तर त्याचे व्युत्क्रम $A \times B$ चे प्रगणन
आहे, हे दाखवा. सर्वसाधारण बाबतीत व्युत्क्रम केवळ फलनाच्या व्याप्तीवर
परिभाषित असते; यावरून जोड्यांचा हा संच गणनीय आहे, हे सिद्ध करा.
  %READERNOTE{MRSIZ-002: गोठवलेल्या इंग्रजी सरावात कोणत्याही एकास-एक जोडीकरण फलनाचे व्युत्क्रम थेट प्रगणन असल्याचा दावा आहे. फलन आच्छादक नसेल, तर त्याचे व्युत्क्रम सर्व नैसर्गिक संख्यांवर परिभाषित नसते. मराठी सरावात आच्छादक बाब आणि सामान्य अंशतः-व्युत्क्रम बाब वेगळ्या केल्या आहेत.}
\end{prob}

source_excerpt:
\begin{explain}
Accordingly, in our second enumeration of $\Nat^2$, the pair
$\tuple{0,0}$ has code $h(0,0) = 2^0(2\cdot 0+1) - 1 = 0$;
$\tuple{1,2}$ has code $2^{1} \cdot (2 \cdot 2 + 1) - 1 = 2
\cdot 5 - 1 = 9$; $\tuple{2,6}$ has code $2^{2} \cdot (2
\cdot 6 + 1) - 1 = 51$.
\end{explain}

target_excerpt:
\begin{explain}
त्यानुसार, $\Nat^2$ च्या आपल्या दुसऱ्या प्रगणनात $\tuple{0,0}$ या
जोडीचा संकेतांक $h(0,0) = 2^0(2\cdot 0+1) - 1 = 0$ आहे;
$\tuple{1,2}$ हिचा संकेतांक $2^{1} \cdot (2 \cdot 2 + 1) - 1 = 2
\cdot 5 - 1 = 9$ आहे; आणि $\tuple{2,6}$ हिचा संकेतांक $2^{2} \cdot (2
\cdot 6 + 1) - 1 = 51$ आहे.
\end{explain}

source_excerpt:
\begin{editorial}
  This section proves the non-enumerability of $\Bin^\omega$ and
  $\Pow{\PosInt}$ using the definition in \olref[enm]{sec}. It is
  designed to be a little more elementary and a little more detailed
  than the version in \olref[enm-alt]{sec}
\end{editorial}

target_excerpt:
\begin{editorial}
  या विभागात \olref[enm]{sec} मधील व्याख्या वापरून $\Bin^\omega$ आणि
  $\Pow{\PosInt}$ यांची अगणनीयता सिद्ध केली आहे. ही मांडणी
  \olref[enm-alt]{sec} मधील आवृत्तीपेक्षा थोडी अधिक प्राथमिक आणि
  थोडी अधिक तपशीलवार ठेवली आहे.
\end{editorial}

\begin{explain}
या सिद्धता-पद्धतीला ``कर्णीकरण'' म्हणतात, कारण तिच्यात सरणीच्या
कर्णरेषेचा वापर करून~$\overline{s}$ ची व्याख्या केली जाते. कर्णीकरणात
सरणी असलीच पाहिजे असे नाही: प्रत्यक्ष सरणी किंवा कर्णरेषा नसतानाही
हीच कल्पना वापरून संच !!{enumerable} नाहीत, हे दाखवता येते.
\end{explain}

\begin{prob}\label{sfr:siz:nen:prob:f-posint}
$f \colon \PosInt \to \PosInt$ अशा फलनांचा संच !!{nonenumerable}
आहे, हे स्पष्ट कर्णरेषीय युक्तिवादाने दाखवा. म्हणजे, $f_1$, $f_2$,
\dots{} ही फलनांची यादी असेल आणि प्रत्येक $f_i\colon
\PosInt \to \PosInt$ असेल, तर या यादीत नसलेले कोणते तरी
$\overline{f}\colon \PosInt \to \PosInt$ असते, हे दाखवा.
\end{prob}

source_excerpt:
\begin{prob}
Show that if there is an !!{injective} function $g\colon B \to A$, and
$B$~is !!{nonenumerable}, then so is~$A$. Do this by showing how you
can use~$g$ to turn an enumeration of~$A$ into one of~$B$.
\end{prob}

target_excerpt:
\begin{prob}
$g\colon B \to A$ असे !!{injective} फलन असेल आणि $B$ हा
!!{nonenumerable} असेल, तर $A$ हाही अगणनीय असतो, हे दाखवा.
$g$ वापरून~$A$ चे प्रगणन~$B$ च्या प्रगणनात कसे रूपांतरित करता येते,
हे दाखवून सिद्धता द्या.
\end{prob}

source_excerpt:
So if $\Pow{\PosInt}$ were !!{enumerable}, $\Bin^\omega$ would be
!!{enumerable}.  But $\Bin^\omega$ is !!{nonenumerable}
(\olref[nen]{thm:nonenum-bin-omega}). Hence $\Pow{\PosInt}$ is
!!{nonenumerable}.
\end{proof}

\begin{prob}
Show that $\Nat^\omega$, the set of infinite sequences of
natural numbers, is !!{nonenumerable} by a reduction argument.
\end{prob}

target_excerpt:
\begin{prob}
नैसर्गिक संख्यांच्या सर्व अनंत अनुक्रमांचा संच~$\Nat^\omega$ हा
न्यूनीकरणाच्या युक्तिवादाने !!{nonenumerable} आहे, हे दाखवा.
\end{prob}

source_excerpt:
\begin{prob}
Let $P$ be the set of functions from the set of positive
integers to the set $\{0\}$, and let $Q$ be the set of \emph{partial}
functions from the set of positive integers to the set $\{0\}$. Show
that $P$~is !!{enumerable} and $Q$~is not. (Hint: reduce the problem
of enumerating $\Bin^\omega$ to enumerating~$Q$).
\end{prob}

\begin{prop}
If $\cardeq{A}{B}$, then $A$ is !!{enumerable} if
and only if $B$ is.
\end{prop}

target_excerpt:
\begin{prop}
$\cardeq{A}{B}$ असेल, तर $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ
तेव्हाच $B$ तसा असतो.
\end{prop}

source_excerpt:
\begin{editorial}
The following proof uses \olref[enm]{defn:enumerable} if
\olref[enm]{sec} is included and \olref[enm-alt]{defn:enumerable}
otherwise.
\end{editorial}

target_excerpt:
\begin{editorial}
पुढील सिद्धतेत \olref[enm]{sec} समाविष्ट असेल, तर
\olref[enm]{defn:enumerable} वापरली जाते; अन्यथा
\olref[enm-alt]{defn:enumerable} वापरली जाते.
\end{editorial}

source_excerpt:
\begin{prob}
Show that if $A$ is infinite and !!{enumerable}, then
$\cardeq{A}{\Nat}$.
\end{prob}

target_excerpt:
\begin{prob}
$A$ हा अनंत आणि !!{enumerable} असेल, तर $\cardeq{A}{\Nat}$ आहे, हे
दाखवा.
\end{prob}

source_excerpt:
\begin{defn}
  \ollabel{defn:enumerable}
  A set~$A$ is !!{enumerable} iff either $A = \emptyset$ or there is
  an enumeration of~$A$. We say that $A$ is !!{nonenumerable} iff $A$
  is not !!{enumerable}.
\end{defn}

target_excerpt:
\begin{defn}
  \ollabel{defn:enumerable}
  संच~$A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच, जेव्हा
  $A = \emptyset$ असते किंवा~$A$ चे प्रगणन असते. $A$ हा
  !!{nonenumerable} आहे असे म्हणतो तेव्हा आणि केवळ तेव्हाच, जेव्हा
  $A$ हा !!{enumerable} नसतो.
\end{defn}

source_excerpt:
\begin{explain}
So a set is !!{enumerable} iff it is empty or you can use an
enumeration to count out its !!{element}s.
\end{explain}

target_excerpt:
\begin{explain}
म्हणून संच रिक्त असेल किंवा प्रगणन वापरून त्यातील !!{element}s मोजता
येत असतील तेव्हा आणि केवळ तेव्हाच तो !!{enumerable} असतो.
\end{explain}

source_excerpt:
\begin{ex}
A function enumerating the natural numbers is simply the identity
function $\Id{\Nat} \colon \Nat \to \Nat$ given by $\Id{\Nat}(n) = n$. A
function enumerating the \emph{positive} natural numbers, $\Nat^+ =
\Nat \setminus \{0\}$, is the function $g(n) = n + 1$, i.e., the
successor function.
\end{ex}

target_excerpt:
\begin{ex}
नैसर्गिक संख्यांचे प्रगणन करणारे फलन म्हणजे फक्त $\Id{\Nat} \colon
\Nat \to \Nat$ हे $\Id{\Nat}(n) = n$ ने दिलेले एकरूपता फलन.
\emph{धन} नैसर्गिक संख्या $\Nat^+ = \Nat \setminus \{0\}$ यांचे
प्रगणन करणारे फलन $g(n) = n + 1$ आहे; म्हणजेच ते उत्तरवर्ती फलन आहे.
\end{ex}

source_excerpt:
\begin{prob}
Show that a set $A$ is !!{enumerable} iff either $A = \emptyset$ or
there is !!a{surjection} $f\colon \Nat \to A$. Show that $A$ is
!!{enumerable} iff there is !!a{injection} $g\colon A \to \Nat$.
\end{prob}

target_excerpt:
\begin{prob}
संच $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच $A =
\emptyset$ असते किंवा $f\colon \Nat \to A$ असे !!a{surjection}
असते, हे दाखवा. $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच
$g\colon A \to \Nat$ असे !!a{injection} असते, हेही दाखवा.
\end{prob}

source_excerpt:
\begin{ex}
The functions $f\colon \Nat \to \Nat$ and $g \colon \Nat \to \Nat$
given by
\begin{align*}
  f(n) & = 2n \text{ and}\\
  g(n) & = 2n+1
\end{align*}
respectively enumerate the even natural numbers and the odd natural
numbers. But neither is !!{surjective}, so neither is an enumeration
of $\Nat$.
\end{ex}

target_excerpt:
\begin{ex}
पुढीलप्रमाणे दिलेली $f\colon \Nat \to \Nat$ आणि $g \colon \Nat
\to \Nat$ ही फलने
\begin{align*}
  f(n) & = 2n \text{ आणि}\\
  g(n) & = 2n+1
\end{align*}
अनुक्रमे सम नैसर्गिक संख्यांचे आणि विषम नैसर्गिक संख्यांचे प्रगणन
करतात. पण यांपैकी कोणतेही फलन !!{surjective} नाही; म्हणून कोणतेही
$\Nat$ चे प्रगणन नाही.
\end{ex}

source_excerpt:
\begin{prob}
Define an enumeration of the square numbers $1$, $4$, $9$, $16$, \dots
\end{prob}

target_excerpt:
\begin{prob}
वर्गसंख्या $1$, $4$, $9$, $16$, \dots{} यांचे प्रगणन परिभाषित करा.
\end{prob}

source_excerpt:
\begin{prob}
Show that if $A$ and $B$ are !!{enumerable}, so is $A \cup B$.
\end{prob}

target_excerpt:
\begin{prob}
$A$ आणि $B$ हे !!{enumerable} असतील, तर $A \cup B$ सुद्धा गणनीय
आहे, हे दाखवा.
\end{prob}

source_excerpt:
\begin{prob}
Show by induction on $n$ that if $A_1$, $A_2$, \dots, $A_n$ are all
!!{enumerable}, so is $A_1 \cup \dots \cup A_n$.
\end{prob}

target_excerpt:
\begin{prob}
$A_1$, $A_2$, \dots, $A_n$ हे सर्व !!{enumerable} असतील, तर
$A_1 \cup \dots \cup A_n$ सुद्धा गणनीय आहे, हे $n$ वरील गणिती विगमनाने
दाखवा.
\end{prob}

source_excerpt:
\begin{prob}
Show that if there is an !!{injective} function $g\colon B \to A$, and
$B$~is !!{nonenumerable}, then so is~$A$. Do this by showing how you
can use~$g$ to turn an enumeration of~$A$ into one of~$B$.
\end{prob}

target_excerpt:
\begin{prob}
$g\colon B \to A$ असे !!{injective} फलन असेल आणि $B$ हा
!!{nonenumerable} असेल, तर $A$ हाही तसाच असतो, हे दाखवा. $g$ वापरून
~$A$ चे प्रगणन~$B$ च्या प्रगणनात कसे रूपांतरित करता येते हे दाखवून
सिद्धता द्या.
\end{prob}

