source_excerpt:
\begin{editorial}
This chapter discusses enumerations, countability and uncountability.
Several sections come in two versions: a more elementary one, that
takes enumerations to be lists, or surjections from $\PosInt$; and a
more abstract one that defines enumerations as bijections with $\Nat$.
\end{editorial}

target_excerpt:
\begin{editorial}
या प्रकरणात प्रगणने, गणनीयता आणि अगणनीयता यांची चर्चा आहे.
काही विभागांच्या दोन आवृत्त्या आहेत: अधिक प्राथमिक आवृत्तीत प्रगणने
म्हणजे याद्या किंवा $\PosInt$ पासूनची आच्छादने मानली आहेत;
अधिक अमूर्त आवृत्तीत प्रगणनांची व्याख्या $\Nat$ बरोबरच्या
एकास-एक आच्छादनांनी केली आहे.
\end{editorial}

\begin{editorial}
पुढील \olref[sfr][siz][enm-alt]{sec},
\olref[sfr][siz][nen-alt]{sec} आणि \olref[sfr][siz][red-alt]{sec}
हे अनुक्रमे \olref[sfr][siz][enm]{sec},
\olref[sfr][siz][nen]{sec} आणि \olref[sfr][siz][red]{sec}
यांचे पर्यायी विभाग आहेत. टिम बटन यांनी त्यांच्या Open Set Theory
या ग्रंथात वापरण्यासाठी ते तयार केले. ते किंचित अधिक प्रगत आहेत आणि
संच सिद्धांताच्या संदर्भात अधिक योग्य अशी गणनीयतेची भिन्न व्याख्या
वापरतात: यादी देता येणे किंवा $\PosInt$ पासूनच्या आच्छादक फलनाची
व्याप्ती असणे याऐवजी $\Nat$ किंवा त्याच्या आरंभीच्या खंडाशी एकास-एक
आच्छादन असणे.
\end{editorial}

source_excerpt:
\begin{defn}
  \ollabel{defn:enumerable}
  A set~$A$ is !!{enumerable} iff it is empty or has an enumeration.
\end{defn}

target_excerpt:
\begin{defn}
  \ollabel{defn:enumerable}
  संच~$A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच,
  जेव्हा तो रिक्त असतो किंवा त्याचे प्रगणन असते.
\end{defn}

source_excerpt:
\begin{prob}
  Show that if $A$ and $B$ are !!{enumerable}, so is $A \cup B$. To do
  this, suppose there are !!{surjective} functions $f\colon \PosInt \to
  A$ and $g\colon \PosInt \to B$, and define !!a{surjective}
  function~$h\colon \PosInt \to A \cup B$ and prove that it is
  !!{surjective}. Also consider the cases where $A$ or~$B = \emptyset$.
\end{prob}

\begin{prob}
  Show that if $B \subseteq A$ and $A$ is !!{enumerable}, so is~$B$. To
  do this, suppose there is !!a{surjective} function $f\colon \PosInt \to
  A$. Define !!a{surjective} function~$g\colon \PosInt \to B$ and prove
  that it is !!{surjective}. What happens if $B = \emptyset$?
\end{prob}

target_excerpt:
\begin{prob}
  $B \subseteq A$ आणि $A$ हा !!{enumerable} असेल, तर~$B$ हाही
  गणनीय असतो, हे दाखवा. यासाठी एक !!a{surjective} फलन
  $f\colon \PosInt \to A$ आहे असे समजा. एक !!a{surjective}
  फलन~$g\colon \PosInt \to B$ परिभाषित करा आणि ते
  !!{surjective} आहे हे सिद्ध करा. $B = \emptyset$ असल्यास काय होते?
\end{prob}

source_excerpt:
\begin{prob}
  Show by induction on $n$ that if $A_1$, $A_2$, \dots, $A_n$ are all
  !!{enumerable}, so is $A_1 \cup \dots \cup A_n$. You may assume the
  fact that if two sets $A$ and~$B$ are !!{enumerable}, so is~$A \cup
  B$.
\end{prob}

\begin{cor}\ollabel{cor:enum-nat}
A set $A$ is !!{enumerable} iff it is empty or there is
!!a{surjective} function $f\colon \Nat \to A$.
\end{cor}

target_excerpt:
\begin{cor}\ollabel{cor:enum-nat}
संच $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच, जेव्हा
तो रिक्त असतो किंवा !!a{surjective} फलन $f\colon \Nat \to A$ असते.
\end{cor}

source_excerpt:
\begin{cor}\ollabel{cor:enum-nat-bij}
A set $A$ is !!{enumerable} iff it is empty or there is !!a{bijection}
$f\colon N \to A$ where either $N = \Nat$ or $N = \{0, \dots, n\}$ for
some $n \in \Nat$.
\end{cor}

target_excerpt:
\begin{cor}\ollabel{cor:enum-nat-bij}
संच $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच, जेव्हा
तो रिक्त असतो किंवा !!a{bijection} $f\colon N \to A$ असते,
जेथे $N = \Nat$ किंवा कोणत्या तरी $n \in \Nat$ साठी
$N = \{0, \dots, n\}$ असते.
\end{cor}

source_excerpt:
\begin{prob}
  According to \olref[sfr][siz][enm]{defn:enumerable}, a set $A$ is
  enumerable iff $A = \emptyset$ or there is !!a{surjective} $f\colon
  \PosInt \to A$.  It is also possible to define ``!!{enumerable} set''
  precisely by: a set is enumerable iff there is !!a{injective}
  function $g\colon A \to \PosInt$.  Show that the definitions are
  equivalent, i.e., show that there is !!a{injective} function
  $g\colon A \to \PosInt$ iff either $A = \emptyset$ or there is
  !!a{surjective} $f\colon \PosInt \to A$.
\end{prob}

\begin{prop}\ollabel{natsquaredenumerable}
$\Nat \times \Nat$ is !!{enumerable}.
\end{prop}

target_excerpt:
\begin{prop}\ollabel{natsquaredenumerable}
$\Nat \times \Nat$ हा !!{enumerable} आहे.
\end{prop}

source_excerpt:
\begin{prop}
$\Nat^n$ is !!{enumerable}, for every $n \in \Nat$.
\end{prop}

target_excerpt:
\begin{prop}
प्रत्येक $n \in \Nat$ साठी $\Nat^n$ हा !!{enumerable} आहे.
\end{prop}

source_excerpt:
\begin{prob}\label{sfr:siz:zigzag:prob:posint-n}
Show that $(\PosInt)^n$ is !!{enumerable}, for every $n \in \Nat$.
\end{prob}

target_excerpt:
\begin{prob}\label{sfr:siz:zigzag:prob:posint-n}
प्रत्येक $n \in \Nat$ साठी $(\PosInt)^n$ हा !!{enumerable} आहे, हे दाखवा.
\end{prob}

source_excerpt:
\begin{prob}\label{sfr:siz:zigzag:prob:posint-star}
  Show that $(\PosInt)^*$ is !!{enumerable}. You may assume \cref{sfr:siz:zigzag:prob:posint-n}.
\end{prob}

target_excerpt:
\begin{prob}\label{sfr:siz:zigzag:prob:posint-star}
  $(\PosInt)^*$ हा !!{enumerable} आहे, हे दाखवा. तुम्ही \cref{sfr:siz:zigzag:prob:posint-n} गृहीत धरू शकता.
\end{prob}

source_excerpt:
\begin{prob}
Show that $\Rat$ is !!{enumerable}. Recall that any rational number
can be written as a fraction $z/m$ with $z \in \Int$, $m \in \Nat^+$.
\end{prob}

target_excerpt:
\begin{prob}
$\Rat$ हा !!{enumerable} आहे, हे दाखवा. कोणतीही परिमेय संख्या
$z/m$ या अपूर्णांकाच्या रूपात लिहिता येते, जेथे $z \in \Int$ आणि
$m \in \Nat^+$ असतात, हे आठवा.
\end{prob}

source_excerpt:
\begin{prob}
Recall from your introductory logic course that each possible truth
table expresses a truth function. In other words, the truth functions
are all functions from $\Bin^k \to \Bin$ for some~$k$. Prove that the
set of all truth functions is enumerable.
\end{prob}

target_excerpt:
\begin{prob}
प्रास्ताविक तर्कशास्त्राच्या अभ्यासक्रमातून आठवा की प्रत्येक संभाव्य
सत्यताकोष्टक एक सत्यता-फलन व्यक्त करतो. दुसऱ्या शब्दांत, सत्यता-फलने
म्हणजे कोणत्या तरी~$k$ साठी $\Bin^k \to \Bin$ अशी सर्व फलने आहेत.
सर्व सत्यता-फलनांचा संच गणनीय आहे, हे सिद्ध करा.
\end{prob}

source_excerpt:
\begin{prob}
Show that the set of all finite subsets of an arbitrary infinite
!!{enumerable} set is !!{enumerable}.
\end{prob}

target_excerpt:
\begin{prob}
कोणत्याही अनंत !!{enumerable} संचाच्या सर्व सांत उपसंचांचा संच
!!{enumerable} आहे, हे दाखवा.
\end{prob}

\begin{prob}
$\Nat$ च्या एखाद्या सांत उपसंचाचा पूरक असलेल्या $\Nat$ च्या उपसंचाला
\emph{सांत-पूरक} म्हणतात. म्हणजे, $A \subseteq \Nat$ हा सांत-पूरक
असतो तेव्हा आणि केवळ तेव्हाच, जेव्हा $\Nat\setminus A$ हा सांत असतो.
%READERNOTE{OLSIZ-002: गोठवलेल्या इंग्रजी वाक्यात “complement of a finite set Nat” अशी संबंधदर्शक शब्दांशिवाय अपूर्ण रचना आहे. लगेचचे सूत्र अभिप्रेत अर्थ ठरवते: Nat मधील एखाद्या सांत उपसंचाचा Nat-सापेक्ष पूरक. मराठी मजकुरात हा संबंध स्पष्ट केला आहे.}
$\Nat$ चे सांत आणि सांत-पूरक उपसंच हेच ज्याचे !!{element}s आहेत,
असा संच $I$ घ्या. $I$ हा !!{enumerable} आहे, हे दाखवा.
\end{prob}

source_excerpt:
\begin{prob}
Show that the !!{enumerable} union of !!{enumerable} sets is
!!{enumerable}. That is, whenever $A_1$, $A_2$, \dots{} are sets, and
each $A_i$ is !!{enumerable}, then the union $\bigcup_{i=1}^\infty
A_i$ of all of them is also !!{enumerable}. [NB: this is hard!]
\end{prob}

target_excerpt:
\begin{prob}
!!{enumerable} इतक्या !!{enumerable} संचांचा संयोग !!{enumerable} असतो,
हे दाखवा. म्हणजे, $A_1$, $A_2$, \dots{} हे संच असतील आणि प्रत्येक
$A_i$ हा !!{enumerable} असेल, तर त्या सर्वांचा संयोग
$\bigcup_{i=1}^\infty A_i$ हाही !!{enumerable} असतो. [टीप: हे कठीण आहे!]
\end{prob}

source_excerpt:
\begin{prob}
Let $f \colon A \times B \to \Nat$ be an arbitrary pairing function.
Show that the inverse of $f$ is an enumeration of $A \times B$.
\end{prob}

target_excerpt:
\begin{prob}
$f \colon A \times B \to \Nat$ हे कोणतेही जोडीकरण फलन असू द्या.
हे $f$ आच्छादकही असेल, तर त्याचे व्युत्क्रम $A \times B$ चे प्रगणन
आहे, हे दाखवा. सर्वसाधारण बाबतीत व्युत्क्रम केवळ फलनाच्या व्याप्तीवर
परिभाषित असते; यावरून जोड्यांचा हा संच गणनीय आहे, हे सिद्ध करा.
  %READERNOTE{MRSIZ-002: गोठवलेल्या इंग्रजी सरावात कोणत्याही एकास-एक जोडीकरण फलनाचे व्युत्क्रम थेट प्रगणन असल्याचा दावा आहे. फलन आच्छादक नसेल, तर त्याचे व्युत्क्रम सर्व नैसर्गिक संख्यांवर परिभाषित नसते. मराठी सरावात आच्छादक बाब आणि सामान्य अंशतः-व्युत्क्रम बाब वेगळ्या केल्या आहेत.}
\end{prob}

source_excerpt:
\begin{editorial}
  This section proves the non-enumerability of $\Bin^\omega$ and
  $\Pow{\PosInt}$ using the definition in \olref[enm]{sec}. It is
  designed to be a little more elementary and a little more detailed
  than the version in \olref[enm-alt]{sec}
\end{editorial}

target_excerpt:
\begin{editorial}
  या विभागात \olref[enm]{sec} मधील व्याख्या वापरून $\Bin^\omega$ आणि
  $\Pow{\PosInt}$ यांची अगणनीयता सिद्ध केली आहे. ही मांडणी
  \olref[enm-alt]{sec} मधील आवृत्तीपेक्षा थोडी अधिक प्राथमिक आणि
  थोडी अधिक तपशीलवार ठेवली आहे.
\end{editorial}

source_excerpt:
\begin{thm}
\ollabel{thm:nonenum-bin-omega}
$\Bin^\omega$~is !!{nonenumerable}.
\end{thm}

target_excerpt:
\begin{thm}
\ollabel{thm:nonenum-bin-omega}
$\Bin^\omega$ हा !!{nonenumerable} आहे.
\end{thm}

\begin{explain}
या सिद्धता-पद्धतीला ``कर्णीकरण'' म्हणतात, कारण तिच्यात सरणीच्या
कर्णरेषेचा वापर करून~$\overline{s}$ ची व्याख्या केली जाते. कर्णीकरणात
सरणी असलीच पाहिजे असे नाही: प्रत्यक्ष सरणी किंवा कर्णरेषा नसतानाही
हीच कल्पना वापरून संच !!{enumerable} नाहीत, हे दाखवता येते.
\end{explain}

source_excerpt:
\begin{thm}
\ollabel{thm:nonenum-pownat}
$\Pow{\PosInt}$ is not !!{enumerable}.
\end{thm}

target_excerpt:
\begin{thm}
\ollabel{thm:nonenum-pownat}
$\Pow{\PosInt}$ हा !!{enumerable} नाही.
\end{thm}

source_excerpt:
\begin{prob}
Show that $\Pow{\Nat}$ is !!{nonenumerable} by a diagonal argument.
\end{prob}

target_excerpt:
\begin{prob}
कर्णरेषीय युक्तिवादाने $\Pow{\Nat}$ हा !!{nonenumerable} आहे, हे दाखवा.
\end{prob}

\begin{prob}\label{sfr:siz:nen:prob:f-posint}
$f \colon \PosInt \to \PosInt$ अशा फलनांचा संच !!{nonenumerable}
आहे, हे स्पष्ट कर्णरेषीय युक्तिवादाने दाखवा. म्हणजे, $f_1$, $f_2$,
\dots{} ही फलनांची यादी असेल आणि प्रत्येक $f_i\colon
\PosInt \to \PosInt$ असेल, तर या यादीत नसलेले कोणते तरी
$\overline{f}\colon \PosInt \to \PosInt$ असते, हे दाखवा.
\end{prob}

source_excerpt:
\begin{editorial}
  This section proves non-enumerability by reduction, matching the
  results in \olref[nen]{sec}. An alternative, slightly more condensed
  version matching the results in \olref[nen-alt]{sec} is provided in
  \olref[red-alt]{sec}.
\end{editorial}

target_excerpt:
\begin{editorial}
  या विभागात \olref[nen]{sec} मधील निष्कर्षांशी जुळणारी अगणनीयता
  न्यूनीकरणाने सिद्ध केली आहे. \olref[nen-alt]{sec} मधील निष्कर्षांशी
  जुळणारी, किंचित अधिक संक्षिप्त पर्यायी आवृत्ती \olref[red-alt]{sec}
  मध्ये दिली आहे.
\end{editorial}

source_excerpt:
\begin{prob}
Show that if there is an !!{injective} function $g\colon B \to A$, and
$B$~is !!{nonenumerable}, then so is~$A$. Do this by showing how you
can use~$g$ to turn an enumeration of~$A$ into one of~$B$.
\end{prob}

target_excerpt:
\begin{prob}
$g\colon B \to A$ असे !!{injective} फलन असेल आणि $B$ हा
!!{nonenumerable} असेल, तर $A$ हाही अगणनीय असतो, हे दाखवा.
$g$ वापरून~$A$ चे प्रगणन~$B$ च्या प्रगणनात कसे रूपांतरित करता येते,
हे दाखवून सिद्धता द्या.
\end{prob}

source_excerpt:
So if $\Pow{\PosInt}$ were !!{enumerable}, $\Bin^\omega$ would be
!!{enumerable}.  But $\Bin^\omega$ is !!{nonenumerable}
(\olref[nen]{thm:nonenum-bin-omega}). Hence $\Pow{\PosInt}$ is
!!{nonenumerable}.
\end{proof}

\begin{prob}
Show that the set of all \emph{sets of} pairs of positive integers is
!!{nonenumerable} by a reduction argument.
\end{prob}

target_excerpt:
\begin{prob}
धन पूर्णांकांच्या जोड्यांच्या \emph{सर्व संचांचा} संच न्यूनीकरणाच्या
युक्तिवादाने !!{nonenumerable} आहे, हे दाखवा.
\end{prob}

source_excerpt:
\begin{prob}\label{sfr:siz:red:prob:nat-nat}
  Show that the set~$X$ of all functions $f\colon \Nat \to \Nat$ is
  !!{nonenumerable} by a reduction argument (Hint: give a surjective
  function from $X$ to~$\Bin^\omega$.)
\end{prob}

target_excerpt:
\begin{prob}\label{sfr:siz:red:prob:nat-nat}
  $f\colon \Nat \to \Nat$ अशा सर्व फलनांचा संच~$X$ हा न्यूनीकरणाच्या
  युक्तिवादाने !!{nonenumerable} आहे, हे दाखवा. (सूचना: $X$ पासून
  $\Bin^\omega$ कडे जाणारे आच्छादक फलन द्या.)
\end{prob}

source_excerpt:
\begin{prob}
Show that $\Nat^\omega$, the set of infinite sequences of
natural numbers, is !!{nonenumerable} by a reduction argument.
\end{prob}

target_excerpt:
\begin{prob}
नैसर्गिक संख्यांच्या सर्व अनंत अनुक्रमांचा संच~$\Nat^\omega$ हा
न्यूनीकरणाच्या युक्तिवादाने !!{nonenumerable} आहे, हे दाखवा.
\end{prob}

source_excerpt:
\begin{prob}
Let $P$ be the set of functions from the set of positive
integers to the set $\{0\}$, and let $Q$ be the set of \emph{partial}
functions from the set of positive integers to the set $\{0\}$. Show
that $P$~is !!{enumerable} and $Q$~is not. (Hint: reduce the problem
of enumerating $\Bin^\omega$ to enumerating~$Q$).
\end{prob}

\begin{prob}
Let $S$ be the set of all !!{surjective} functions from the set of
positive integers to the set \{0,1\}, i.e., $S$ consists of all
!!{surjective}~$f\colon \PosInt \to \Bin$.  Show that $S$ is
!!{nonenumerable}.
\end{prob}

target_excerpt:
\begin{prob}
$S$ हा धन पूर्णांकांच्या संचापासून \{0,1\} या संचाकडे जाणाऱ्या सर्व
!!{surjective} फलनांचा संच असू द्या; म्हणजे, $S$ मध्ये सर्व
!!{surjective}~$f\colon \PosInt \to \Bin$ आहेत. $S$ हा
!!{nonenumerable} आहे, हे दाखवा.
\end{prob}

source_excerpt:
\begin{prob}
Show that the set~$\Real$ of all real numbers is !!{nonenumerable}.
\end{prob}

target_excerpt:
\begin{prob}
सर्व वास्तव संख्यांचा संच~$\Real$ हा !!{nonenumerable} आहे, हे दाखवा.
\end{prob}

source_excerpt:
\begin{prop}
If $\cardeq{A}{B}$, then $A$ is !!{enumerable} if
and only if $B$ is.
\end{prop}

target_excerpt:
\begin{prop}
$\cardeq{A}{B}$ असेल, तर $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ
तेव्हाच $B$ तसा असतो.
\end{prop}

source_excerpt:
\begin{editorial}
The following proof uses \olref[enm]{defn:enumerable} if
\olref[enm]{sec} is included and \olref[enm-alt]{defn:enumerable}
otherwise.
\end{editorial}

target_excerpt:
\begin{editorial}
पुढील सिद्धतेत \olref[enm]{sec} समाविष्ट असेल, तर
\olref[enm]{defn:enumerable} वापरली जाते; अन्यथा
\olref[enm-alt]{defn:enumerable} वापरली जाते.
\end{editorial}

source_excerpt:
\begin{prob}
Show that if $A$ is infinite and !!{enumerable}, then
$\cardeq{A}{\Nat}$.
\end{prob}

target_excerpt:
\begin{prob}
$A$ हा अनंत आणि !!{enumerable} असेल, तर $\cardeq{A}{\Nat}$ आहे, हे
दाखवा.
\end{prob}

source_excerpt:
\begin{editorial}
We present the slow proof if \olref[nen]{sec} is
present, otherwise a faster proof matching \olref[nen-alt]{sec}.
\end{editorial}

target_excerpt:
\begin{editorial}
\olref[nen]{sec} समाविष्ट असेल, तर आपण संथ सिद्धता देतो; अन्यथा
\olref[nen-alt]{sec} शी जुळणारी अधिक जलद सिद्धता देतो.
\end{editorial}

source_excerpt:
\begin{defn}
  \ollabel{defn:enumerable}
  A set~$A$ is !!{enumerable} iff either $A = \emptyset$ or there is
  an enumeration of~$A$. We say that $A$ is !!{nonenumerable} iff $A$
  is not !!{enumerable}.
\end{defn}

target_excerpt:
\begin{defn}
  \ollabel{defn:enumerable}
  संच~$A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच, जेव्हा
  $A = \emptyset$ असते किंवा~$A$ चे प्रगणन असते. $A$ हा
  !!{nonenumerable} आहे असे म्हणतो तेव्हा आणि केवळ तेव्हाच, जेव्हा
  $A$ हा !!{enumerable} नसतो.
\end{defn}

source_excerpt:
\begin{explain}
So a set is !!{enumerable} iff it is empty or you can use an
enumeration to count out its !!{element}s.
\end{explain}

target_excerpt:
\begin{explain}
म्हणून संच रिक्त असेल किंवा प्रगणन वापरून त्यातील !!{element}s मोजता
येत असतील तेव्हा आणि केवळ तेव्हाच तो !!{enumerable} असतो.
\end{explain}

source_excerpt:
\begin{prob}
Show that a set $A$ is !!{enumerable} iff either $A = \emptyset$ or
there is !!a{surjection} $f\colon \Nat \to A$. Show that $A$ is
!!{enumerable} iff there is !!a{injection} $g\colon A \to \Nat$.
\end{prob}

target_excerpt:
\begin{prob}
संच $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच $A =
\emptyset$ असते किंवा $f\colon \Nat \to A$ असे !!a{surjection}
असते, हे दाखवा. $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच
$g\colon A \to \Nat$ असे !!a{injection} असते, हेही दाखवा.
\end{prob}

source_excerpt:
\begin{prob}
Show that if $A$ and $B$ are !!{enumerable}, so is $A \cup B$.
\end{prob}

target_excerpt:
\begin{prob}
$A$ आणि $B$ हे !!{enumerable} असतील, तर $A \cup B$ सुद्धा गणनीय
आहे, हे दाखवा.
\end{prob}

source_excerpt:
\begin{prob}
Show by induction on $n$ that if $A_1$, $A_2$, \dots, $A_n$ are all
!!{enumerable}, so is $A_1 \cup \dots \cup A_n$.
\end{prob}

target_excerpt:
\begin{prob}
$A_1$, $A_2$, \dots, $A_n$ हे सर्व !!{enumerable} असतील, तर
$A_1 \cup \dots \cup A_n$ सुद्धा गणनीय आहे, हे $n$ वरील गणिती विगमनाने
दाखवा.
\end{prob}

source_excerpt:
\begin{editorial}
  This section proves the non-enumerability of $\Bin^\omega$ and
  $\Pow{\Nat}$ using the definitions in \olref[enm-alt]{sec}, i.e.,
  requiring a bijection with~$\Nat$ instead of a surjection from
  $\PosInt$.
\end{editorial}

target_excerpt:
\begin{editorial}
  या विभागात \olref[enm-alt]{sec} मधील व्याख्या वापरून
  $\Bin^\omega$ आणि $\Pow{\Nat}$ यांची अगणनीयता सिद्ध केली आहे;
  म्हणजे $\PosInt$ पासून आच्छादन मागण्याऐवजी~$\Nat$ शी एकास-एक
  आच्छादन आवश्यक मानले आहे.
\end{editorial}

source_excerpt:
\begin{explain}
The set $\Nat$ of natural numbers is infinite. It is also trivially
!!{enumerable}. But the remarkable fact is that there are
\emph{!!{nonenumerable}} sets, i.e., sets which are not !!{enumerable}
(see \olref[sfr][siz][enm-alt]{defn:enumerable}).

\begin{thm}
\ollabel{thm:nonenum-bin-omega}
$\Bin^\omega$~is !!{nonenumerable}.
\end{thm}

target_excerpt:
\begin{thm}
\ollabel{thm:nonenum-bin-omega}
$\Bin^\omega$~हा !!{nonenumerable} आहे.
\end{thm}

source_excerpt:
\begin{thm}
\ollabel{thm:nonenum-pownat}
$\Pow{\Nat}$ is not !!{enumerable}.
\end{thm}

target_excerpt:
\begin{thm}
\ollabel{thm:nonenum-pownat}
$\Pow{\Nat}$ हा !!{enumerable} नाही.
\end{thm}

source_excerpt:
\begin{editorial}
  This section proves non-enumerability by reduction, matching the
  results in \olref[nen-alt]{sec}. An alternative, slightly more
  elaborate version matching the results in \olref[nen]{sec} is
  provided in \olref[red]{sec}.
\end{editorial}

target_excerpt:
\begin{editorial}
  या विभागात \olref[nen-alt]{sec} मधील फलितांशी जुळणारी अगणनीयता
  न्यूनीकरणाने सिद्ध केली आहे. \olref[nen]{sec} मधील फलितांशी जुळणारी
  किंचित अधिक विस्तृत पर्यायी आवृत्ती \olref[red]{sec} मध्ये दिली आहे.
\end{editorial}

source_excerpt:
\begin{prob}
Show that if there is an !!{injective} function $g\colon B \to A$, and
$B$~is !!{nonenumerable}, then so is~$A$. Do this by showing how you
can use~$g$ to turn an enumeration of~$A$ into one of~$B$.
\end{prob}

target_excerpt:
\begin{prob}
$g\colon B \to A$ असे !!{injective} फलन असेल आणि $B$ हा
!!{nonenumerable} असेल, तर $A$ हाही तसाच असतो, हे दाखवा. $g$ वापरून
~$A$ चे प्रगणन~$B$ च्या प्रगणनात कसे रूपांतरित करता येते हे दाखवून
सिद्धता द्या.
\end{prob}

source_excerpt:
So if $\Pow{\Nat}$ were !!{enumerable}, $\Bin^\omega$ would be
!!{enumerable}.  But $\Bin^\omega$ is !!{nonenumerable}
(\olref[nen-alt]{thm:nonenum-bin-omega}). Hence $\Pow{\Nat}$ is
!!{nonenumerable}.
\end{proof}

\begin{prob}\label{sfr:siz:red:prob:nat-nat}
  Show that the set~$X$ of all functions $f\colon \Nat \to \Nat$ is
