source_excerpt:
\begin{editorial}
This chapter discusses enumerations, countability and uncountability.
Several sections come in two versions: a more elementary one, that
takes enumerations to be lists, or surjections from $\PosInt$; and a
more abstract one that defines enumerations as bijections with $\Nat$.
\end{editorial}

target_excerpt:
\begin{editorial}
या प्रकरणात प्रगणने, गणनीयता आणि अगणनीयता यांची चर्चा आहे.
काही विभागांच्या दोन आवृत्त्या आहेत: अधिक प्राथमिक आवृत्तीत प्रगणने
म्हणजे याद्या किंवा $\PosInt$ पासूनची आच्छादने मानली आहेत;
अधिक अमूर्त आवृत्तीत प्रगणनांची व्याख्या $\Nat$ बरोबरच्या
एकास-एक आच्छादनांनी केली आहे.
\end{editorial}

\begin{editorial}
पुढील \olref[sfr][siz][enm-alt]{sec},
\olref[sfr][siz][nen-alt]{sec} आणि \olref[sfr][siz][red-alt]{sec}
हे अनुक्रमे \olref[sfr][siz][enm]{sec},
\olref[sfr][siz][nen]{sec} आणि \olref[sfr][siz][red]{sec}
यांचे पर्यायी विभाग आहेत. टिम बटन यांनी त्यांच्या Open Set Theory
या ग्रंथात वापरण्यासाठी ते तयार केले. ते किंचित अधिक प्रगत आहेत आणि
संच सिद्धांताच्या संदर्भात अधिक योग्य अशी गणनीयतेची भिन्न व्याख्या
वापरतात: यादी देता येणे किंवा $\PosInt$ पासूनच्या आच्छादक फलनाची
व्याप्ती असणे याऐवजी $\Nat$ किंवा त्याच्या आरंभीच्या खंडाशी एकास-एक
आच्छादन असणे.
\end{editorial}

source_excerpt:
\begin{defn}\ollabel{comparisondef}
  $A$ is \emph{equinumerous} with $B$, written $\cardeq{A}{B}$, iff
  there is !!a{bijection} $f \colon A \to B$.
\end{defn}

target_excerpt:
\begin{defn}\ollabel{comparisondef}
  $A$ हा $B$ शी \emph{तुल्यबल} असतो, आणि ते $\cardeq{A}{B}$ असे लिहितो,
  तेव्हा आणि केवळ तेव्हाच, जेव्हा $f \colon A \to B$ असे
  !!a{bijection} असते.
\end{defn}

source_excerpt:
\begin{prop}\ollabel{equinumerosityisequi}
Equinumerosity is an equivalence relation.
\end{prop}

target_excerpt:
\begin{prop}\ollabel{equinumerosityisequi}
तुल्यबलता हा तुल्यता संबंध आहे.
\end{prop}

source_excerpt:
\begin{proof}
We must show that equinumerosity is reflexive, symmetric, and
transitive. Let $A, B$, and $C$ be sets.

target_excerpt:
\begin{proof}
तुल्यबलता परावर्ती, सममित आणि संक्रमक आहे, हे दाखवावे लागेल. $A, B$
आणि $C$ हे संच असू द्या.

source_excerpt:
\begin{prop}
If $\cardeq{A}{B}$, then $A$ is !!{enumerable} if
and only if $B$ is.
\end{prop}

target_excerpt:
\begin{prop}
$\cardeq{A}{B}$ असेल, तर $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ
तेव्हाच $B$ तसा असतो.
\end{prop}

source_excerpt:
\begin{prob}
Show that if $\cardeq{A}{C}$ and $\cardeq{B}{D}$, and $A \cap B =
C \cap D = \emptyset$, then $\cardeq{A \cup B}{C \cup D}$.
\end{prob}

target_excerpt:
\begin{prob}
$\cardeq{A}{C}$ आणि $\cardeq{B}{D}$ असेल, आणि $A \cap B =
C \cap D = \emptyset$ असेल, तर $\cardeq{A \cup B}{C \cup D}$ आहे,
हे दाखवा.
\end{prob}

source_excerpt:
\begin{prob}
Show that if $A$ is infinite and !!{enumerable}, then
$\cardeq{A}{\Nat}$.
\end{prob}

target_excerpt:
\begin{prob}
$A$ हा अनंत आणि !!{enumerable} असेल, तर $\cardeq{A}{\Nat}$ आहे, हे
दाखवा.
\end{prob}

source_excerpt:
\begin{defn}
$A$ is \emph{no larger than}~$B$, written $\cardle{A}{B}$, iff there
is !!a{injection} $f \colon A \to B$.
\end{defn}

target_excerpt:
\begin{defn}
$A$ हा $B$ पेक्षा \emph{आकारमानाने मोठा नाही}, हे $\cardle{A}{B}$ असे
लिहितो, तेव्हा आणि केवळ तेव्हाच, जेव्हा $f \colon A \to B$ असे
!!a{injection} असते.
\end{defn}

source_excerpt:
\begin{defn}
$A$ is \emph{smaller than}~$B$, written $\cardless{A}{B}$, iff there
is !!a{injection}~$f\colon A \to B$ but no !!{bijection}~$g\colon A
\to B$, i.e., $\cardle{A}{B}$ and $\cardneq{A}{B}$.
\end{defn}

\begin{thm}[Cantor]\ollabel{thm:cantor}
$\cardless{A}{\Pow{A}}$, for any set $A$.
\end{thm}

target_excerpt:
\begin{thm}[कँटर]\ollabel{thm:cantor}
कोणत्याही संच $A$ साठी $\cardless{A}{\Pow{A}}$.
\end{thm}

\begin{proof}
$f(x) = \{x\}$ हे $f \colon A \to \Pow{A}$ असे !!a{injection} आहे;
कारण $x \neq y$ असेल, तर विस्तारात्मकतेमुळे $\{x\} \neq \{y\}$ सुद्धा
असते, आणि म्हणून $f(x) \neq f(y)$. त्यामुळे $\cardle{A}{\Pow{A}}$.

source_excerpt:
\begin{thm}[Schr\"oder-Bernstein]
    \ollabel{thm:schroder-bernstein}
    If $\cardle{A}{B}$ and $\cardle{B}{A}$,
    then $\cardeq{A}{B}$.
\end{thm}

target_excerpt:
\begin{thm}[श्रेडर--बर्नस्टाइन]
    \ollabel{thm:schroder-bernstein}
    $\cardle{A}{B}$ आणि $\cardle{B}{A}$ असेल,
    तर $\cardeq{A}{B}$.
\end{thm}

source_excerpt:
\begin{prop}\ollabel{sbhelper}
If $A \subseteq B \subseteq C$ and $A \approx C$, then $\cardeq{\cardeq{A}{B}}{C}$.
\end{prop}

target_excerpt:
\begin{prop}\ollabel{sbhelper}
जर $A \subseteq B \subseteq C$ आणि $A \approx C$, तर $\cardeq{B}{C}$.
\end{prop}
%READERNOTE{MRINF-003: गोठवलेल्या इंग्रजी निष्कर्षात तुल्यबलता-उक्तीच पहिला संच म्हणून बसवली आहे. गृहीतके आणि पुढील उपयोग यांवरून B आणि C तुल्यबल आहेत हाच अनिवार्य निष्कर्ष मराठीत दिला आहे.}

