        \text{जर $\pValue{v}(!A) = \True$ आणि $\pValue{v}(!B) = \False$}.
      \end{cases}\\}{}
    \iftag{prvIff}{\pValue{v}(!A \liff !B) & = \begin{cases}
        \True &
        \text{जर $\pValue{v}(!A) = \pValue{v}(!B)$;}\\
        \False &
        \text{जर $\pValue{v}(!A) \neq \pValue{v}(!B)$}.
      \end{cases}}{}
\end{align*}
\end{defn}

source_excerpt:
\begin{prop}\ollabel{prop:enum-bij}
If $f\colon \PosInt \to A$ is !!{surjective} (i.e., an enumeration
of~$A$), there is !!a{bijection} $g\colon Z \to A$ where $Z$ is
either~$\PosInt$ or $\{1, \dots, n\}$ for some~$n \in \PosInt$.
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:enum-bij}
$f\colon \PosInt \to A$ हे !!{surjective} असेल (म्हणजे~$A$
चे प्रगणन असेल), तर !!a{bijection} $g\colon Z \to A$ असते,
जेथे $Z$ हा~$\PosInt$ किंवा कोणत्या तरी~$n \in \PosInt$
साठी $\{1, \dots, n\}$ असतो.
\end{prop}

source_excerpt:
\begin{cor}\ollabel{cor:enum-nat-bij}
A set $A$ is !!{enumerable} iff it is empty or there is !!a{bijection}
$f\colon N \to A$ where either $N = \Nat$ or $N = \{0, \dots, n\}$ for
some $n \in \Nat$.
\end{cor}

target_excerpt:
\begin{cor}\ollabel{cor:enum-nat-bij}
संच $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच, जेव्हा
तो रिक्त असतो किंवा !!a{bijection} $f\colon N \to A$ असते,
जेथे $N = \Nat$ किंवा कोणत्या तरी $n \in \Nat$ साठी
$N = \{0, \dots, n\}$ असते.
\end{cor}

source_excerpt:
\begin{proof}
$A$ is !!{enumerable} iff $A$ is empty or there is !!a{surjective}
$f\colon \PosInt \to A$. By \olref{prop:enum-bij}, the latter holds
iff there is !!a{bijective} function~$f\colon Z \to A$ where $Z =
\PosInt$ or $Z = \{1, \dots, n\}$ for some $n \in \PosInt$. By the
same argument as in the proof of \olref{prop:enum-shift}, that in turn
is the case iff there is !!a{bijection} $g\colon N \to A$ where either
$N = \Nat$ or $N = \{0, \dots, n-1\}$.
\end{proof}

\begin{proof}
Clearly this is a nonempty proper initial segment of the rationals; so
it suffices to show that it has no maximum. In particular, it suffices
to show that, where $p$ is a positive rational with $p^2 < 2$ and $q =
\frac{2p+2}{p+2}$, both $p < q$ and $q^2 < 2$. To see that $p < q$,
just note:
\begin{align*}
    p^2 &< 2\\
    p^2 + 2p &< 2 + 2p\\
    p(p + 2) &< 2 + 2p\\
    p &< \tfrac{2+2p}{p+2} = q
\end{align*}
To see that $q^2 < 2$, just note:
\begin{align*}
    p^2 &< 2\\
    2p^2 + 4p + 2 &< p^2 + 4p+ 4\\
    4p^2 + 8p + 4 &< 2(p^2 + 4p + 4)\\
    (2p+2)^2 & <2(p+2)^2\\
    \tfrac{(2p+2)^2}{(p+2)^2} &< 2\\
    q^2 &< 2
\end{align*}
\end{proof}
\end{document}

target_excerpt:
\begin{proof}
हा परिमेय संख्यांचा अरिक्त उचित आरंभीचा खंड आहे हे स्पष्ट आहे; म्हणून
त्याला महत्तम घटक नाही एवढे दाखवणे पुरेसे आहे. विशेषतः, $p$ ही $p^2 < 2$
असलेली धन परिमेय संख्या आणि $q = \frac{2p+2}{p+2}$ असेल, तर $p < q$
आणि $q^2 < 2$ हे दोन्ही दाखवणे पुरेसे आहे. $p < q$ हे पाहण्यासाठी फक्त
पुढील नोंद घ्या:
\begin{align*}
    p^2 &< 2\\
    p^2 + 2p &< 2 + 2p\\
    p(p + 2) &< 2 + 2p\\
    p &< \tfrac{2+2p}{p+2} = q
\end{align*}
$q^2 < 2$ हे पाहण्यासाठी फक्त पुढील नोंद घ्या:
\begin{align*}
    p^2 &< 2\\
    2p^2 + 4p + 2 &< p^2 + 4p+ 4\\
    4p^2 + 8p + 4 &< 2(p^2 + 4p + 4)\\
    (2p+2)^2 & <2(p+2)^2\\
    \tfrac{(2p+2)^2}{(p+2)^2} &< 2\\
    q^2 &< 2
\end{align*}
\end{proof}
\end{document}

