source_excerpt:
\begin{defn}
$A$ is \emph{no larger than}~$B$, written $\cardle{A}{B}$, iff there
is !!a{injection} $f \colon A \to B$.
\end{defn}

target_excerpt:
\begin{defn}
$A$ हा $B$ पेक्षा \emph{आकारमानाने मोठा नाही}, हे $\cardle{A}{B}$ असे
लिहितो, तेव्हा आणि केवळ तेव्हाच, जेव्हा $f \colon A \to B$ असे
!!a{injection} असते.
\end{defn}

source_excerpt:
\begin{defn}
$A$ is \emph{smaller than}~$B$, written $\cardless{A}{B}$, iff there
is !!a{injection}~$f\colon A \to B$ but no !!{bijection}~$g\colon A
\to B$, i.e., $\cardle{A}{B}$ and $\cardneq{A}{B}$.
\end{defn}

\begin{thm}[Cantor]\ollabel{thm:cantor}
$\cardless{A}{\Pow{A}}$, for any set $A$.
\end{thm}

target_excerpt:
\begin{thm}[कँटर]\ollabel{thm:cantor}
कोणत्याही संच $A$ साठी $\cardless{A}{\Pow{A}}$.
\end{thm}

\begin{proof}
$f(x) = \{x\}$ हे $f \colon A \to \Pow{A}$ असे !!a{injection} आहे;
कारण $x \neq y$ असेल, तर विस्तारात्मकतेमुळे $\{x\} \neq \{y\}$ सुद्धा
असते, आणि म्हणून $f(x) \neq f(y)$. त्यामुळे $\cardle{A}{\Pow{A}}$.

source_excerpt:
\begin{prob}
  Show that there cannot be !!a{injection} $g\colon \Pow{A} \to
  A$, for any set~$A$. Hint: Suppose $g\colon \Pow{A} \to A$ is
  !!{injective}. Consider $D = \Setabs{g(B)}{B \subseteq A \text{ and
  } g(B) \notin B}$. Let $x = g(D)$. Use the fact that $g$ is
  !!{injective} to derive a contradiction.
\end{prob}

target_excerpt:
\begin{prob}
  कोणत्याही संच~$A$ साठी $g\colon \Pow{A} \to
  A$ असे !!a{injection} असू शकत नाही, हे दाखवा. सूचना: $g\colon
  \Pow{A} \to A$ हे !!{injective} आहे, असे समजा. पुढील संच विचारात घ्या:
  $D = \Setabs{g(B)}{B \subseteq A \text{ आणि
  } g(B) \notin B}$. $x = g(D)$ असे घ्या. $g$ हे !!{injective} आहे हा
  हे तथ्य वापरून व्याघात मिळवा.
\end{prob}

source_excerpt:
\begin{thm}[Schr\"oder-Bernstein]
    \ollabel{thm:schroder-bernstein}
    If $\cardle{A}{B}$ and $\cardle{B}{A}$,
    then $\cardeq{A}{B}$.
\end{thm}

target_excerpt:
\begin{thm}[श्रेडर--बर्नस्टाइन]
    \ollabel{thm:schroder-bernstein}
    $\cardle{A}{B}$ आणि $\cardle{B}{A}$ असेल,
    तर $\cardeq{A}{B}$.
\end{thm}

वास्तव संख्या परिमेय संख्यांसारख्याच बऱ्याच अंशी वागतात. (तांत्रिक
भाषेत, दोन्ही \emph{क्रमित क्षेत्रांची} उदाहरणे आहेत; त्याची व्याख्या
\olref[check]{orderedfield} मध्ये पाहा.) आता, तुम्ही \olref[sfr][siz][]{chap}
मधील सराव सोडवले असतील, तर वास्तव संख्या परिमेय संख्यांपेक्षा काटेकोरपणे
अधिक आहेत, म्हणजे $\cardless{\Rat}{\Real}$, हे तुम्हाला माहीत असेल.
हे कँटर यांनी प्रथम सिद्ध केले. परंतु अपरिमेय संख्या, म्हणजे परिमेय
नसलेल्या वास्तव संख्या, अस्तित्वात आहेत हे सुमारे अडीच सहस्रकांपासून
माहीत आहे. खरे तर:
%\footnote{टीप: पारंपरिक संकेतानुसार ``$\sqrt{2}$'' धन वर्गमूळ दर्शवते; पुढील काही पृष्ठांत आपण तेच मूळ विचारात घेऊ.}
%READERNOTE{MRARITH-002: गोठवलेल्या इंग्रजीतील निष्क्रिय केलेली तळटीप √2 हे धन आणि ऋण अशी दोन्ही मुळे दर्शवते असे म्हणते. पारंपरिक मूलचिन्ह मात्र मुख्य, ऋणेतर वर्गमूळ दर्शवते; म्हणून मराठीतील निष्क्रिय तळटीप दुरुस्त केली आहे. सक्रिय वाचनीय मजकुरावर याचा परिणाम नाही.}
\begin{thm}\ollabel{root2irrational}
$\sqrt{2}$ ही परिमेय संख्या नाही; म्हणजे $\sqrt{2} \notin \Rat$.
\end{thm}

