source_excerpt:
\begin{thm}
\ollabel{thm:strong-generalization} If $c$ is a constant not occurring
in $\Gamma$ or $!A(x)$ and $\Gamma \Proves !A(c)$, then $\Gamma
\Proves \lforall[x][!A(x)]$.
\end{thm}

target_excerpt:
\begin{thm}
\ollabel{thm:strong-generalization} जर $c$ हे $\Gamma$ किंवा $!A(x)$ मध्ये
न येणारे स्थिर असेल आणि $\Gamma \Proves !A(c)$, तर $\Gamma
\Proves \lforall[x][!A(x)]$.
\end{thm}

source_excerpt:
\begin{explain}
Recall the convention that when $!A$ is !!a{formula} with the
!!{variable}~$x$ free, we indicate this by writing~$!A(x)$. In the
same context, $!A(t)$ then is short for~$\Subst{!A}{t}{x}$. So we
could also write the $\Intro\lexists$ rule as:
\begin{prooftree}
\AxiomC{$\Subst{!A}{t}{x}$}
\RightLabel{\Intro{\lexists}}
\UnaryInfC{$\lexists[x][!A]$}
\end{prooftree}
Note that $t$ may already occur in~$!A$, e.g., $!A$~might
be~$\Atom{\Obj P}{t,x}$.  Thus, inferring $\lexists[x][\Atom{\Obj
P}{t,x}]$ from~$\Atom{\Obj P}{t,t}$ is a correct application
of~$\Intro\lexists$---you may ``replace'' one or more, and not
necessarily all, occurrences of~$t$ in the premise by the bound
!!{variable}~$x$. However, the eigenvariable conditions in
$\Intro\lforall$ and~$\Elim\lexists$ require that the !!{constant}~$a$
does not occur in~$!A$. So, you cannot correctly infer
$\lforall[x][\Atom{\Obj P}{a,x}]$ from $\Atom{\Obj P}{a,a}$
using~$\Intro\lforall$.
\end{explain}

target_excerpt:
\begin{explain}
ही प्रथा आठवा: $!A$ हे असे !!a{formula} असेल की त्यात
!!{variable}~$x$ मुक्त असेल, तर हे आपण~$!A(x)$ असे लिहून दर्शवतो.
त्याच संदर्भात, मग $!A(t)$ हा~$\Subst{!A}{t}{x}$ चा संक्षेप असतो.
त्यामुळे $\Intro\lexists$ नियम पुढीलप्रमाणेही लिहिता येईल:
\begin{prooftree}
\AxiomC{$\Subst{!A}{t}{x}$}
\RightLabel{\Intro{\lexists}}
\UnaryInfC{$\lexists[x][!A]$}
\end{prooftree}
लक्षात घ्या की~$!A$ मध्ये $t$ आधीपासून येऊ शकते; उदा., $!A$ हे
$\Atom{\Obj P}{t,x}$ असू शकते. म्हणून,~$\Atom{\Obj P}{t,t}$ पासून
$\lexists[x][\Atom{\Obj P}{t,x}]$ निष्पन्न करणे हे~$\Intro\lexists$
चे योग्य उपयोजन आहे---आधारविधानात~$t$ जेथे येते त्यांपैकी एक किंवा
अधिक ठिकाणी त्याऐवजी बद्ध !!{variable}~$x$ घालता येतो; सर्वच ठिकाणी
असा ``बदल'' करणे आवश्यक नाही. परंतु $\Intro\lforall$ आणि
$\Elim\lexists$ मधील आयगेन चराच्या अटीनुसार !!{constant}~$a$ हा~$!A$
मध्ये येता कामा नये. म्हणून, $\Intro\lforall$ वापरून
$\Atom{\Obj P}{a,a}$ पासून $\lforall[x][\Atom{\Obj P}{a,x}]$ योग्य
रीतीने निष्पन्न करता येत नाही.
\end{explain}

source_excerpt:
\begin{prop}\ollabel{prop:provability-land}
  \begin{enumerate}
  \item \ollabel{prop:provability-land-left} Both $!A \land !B \Proves
    !A$ and $!A \land !B \Proves !B$.
  \item \ollabel{prop:provability-land-right} $!A, !B \Proves !A \land
    !B$.
  \end{enumerate}
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:provability-land}
  \begin{enumerate}
  \item \ollabel{prop:provability-land-left} $!A \land !B \Proves
    !A$ आणि $!A \land !B \Proves !B$ ही दोन्ही तथ्ये सत्य आहेत.
  \item \ollabel{prop:provability-land-right} $!A, !B \Proves !A \land
    !B$.
  \end{enumerate}
\end{prop}

source_excerpt:
\begin{proof}
  \begin{enumerate}
  \item Both sequents $!A \land !B \Sequent !A$ and $!A \land !B \Sequent
    !B$ are !!{derivable}:
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \RightLabel{\LeftR{\land}}
      \UnaryInf$!A \land !B \fCenter !A$
      \DisplayProof\qquad\bottomAlignProof
      \Axiom$!B \fCenter !B$
      \RightLabel{\LeftR{\land}}
      \UnaryInf$!A \land !B \fCenter !B$
    \end{prooftree}
    \item Here is !!a{derivation} of the sequent $!A, !B \Sequent !A \land !B$:
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \Axiom$!B \fCenter !B$
      \RightLabel{\RightR{\land}}
      \BinaryInf$!A, !B \fCenter !A \land !B$
    \end{prooftree}
  \end{enumerate}
\end{proof}

target_excerpt:
\begin{proof}
  \begin{enumerate}
  \item $!A \land !B \Sequent !A$ आणि $!A \land !B \Sequent
    !B$ या दोन्ही क्रमवर्ती !!{derivable} आहेत:
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \RightLabel{\LeftR{\land}}
      \UnaryInf$!A \land !B \fCenter !A$
      \DisplayProof\qquad\bottomAlignProof
      \Axiom$!B \fCenter !B$
      \RightLabel{\LeftR{\land}}
      \UnaryInf$!A \land !B \fCenter !B$
    \end{prooftree}
    \item $!A, !B \Sequent !A \land !B$ या क्रमवर्तीची !!a{derivation} येथे आहे:
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \Axiom$!B \fCenter !B$
      \RightLabel{\RightR{\land}}
      \BinaryInf$!A, !B \fCenter !A \land !B$
    \end{prooftree}
  \end{enumerate}
\end{proof}

source_excerpt:
\begin{prop}\ollabel{prop:provability-lor}
  \begin{enumerate}
  \item $!A \lor !B, \lnot !A, \lnot !B$ is inconsistent.
  \item Both $!A \Proves !A \lor !B$ and $!B \Proves !A \lor !B$.
  \end{enumerate}
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:provability-lor}
  \begin{enumerate}
  \item $!A \lor !B, \lnot !A, \lnot !B$ विसंगत आहे.
  \item $!A \Proves !A \lor !B$ आणि $!B \Proves !A \lor !B$ ही दोन्ही तथ्ये आहेत.
  \end{enumerate}
\end{prop}

source_excerpt:
\begin{proof}
  \begin{enumerate}
  \item We give !!a{derivation} of the sequent $!A \lor !B, \lnot !A,
    \lnot !B \Sequent$:
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \RightLabel{\LeftR{\lnot}}
      \UnaryInf$\lnot !A, !A \fCenter$
      \doubleLine
      \UnaryInf$!A, \lnot !A, \lnot !B \fCenter$
      \Axiom$!B \fCenter !B$
      \RightLabel{\LeftR{\lnot}}
      \UnaryInf$\lnot !B, !B \fCenter$
      \doubleLine
      \UnaryInf$!B, \lnot !A, \lnot !B \fCenter$
      \RightLabel{\LeftR{\lor}}
      \BinaryInf$ !A \lor !B, \lnot !A, \lnot !B \fCenter $
    \end{prooftree}
    (Recall that double inference lines indicate several weakening,
    contraction, and exchange inferences.)
  \item   Both sequents $!A \Sequent !A \lor !B$ and $!B \Sequent !A
    \lor !B$ have !!{derivation}s:
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \RightLabel{\RightR{\lor}}
      \UnaryInf$!A \fCenter !A \lor !B$
      \DisplayProof\qquad\bottomAlignProof
      \Axiom$!B \fCenter !B$
      \RightLabel{\RightR{\lor}}
      \UnaryInf$!B \fCenter !A \lor !B$
    \end{prooftree}
  \end{enumerate}
\end{proof}

target_excerpt:
\begin{proof}
  \begin{enumerate}
  \item $!A \lor !B, \lnot !A,
    \lnot !B \Sequent$ या क्रमवर्तीची !!a{derivation} देऊ:
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \RightLabel{\LeftR{\lnot}}
      \UnaryInf$\lnot !A, !A \fCenter$
      \doubleLine
      \UnaryInf$!A, \lnot !A, \lnot !B \fCenter$
      \Axiom$!B \fCenter !B$
      \RightLabel{\LeftR{\lnot}}
      \UnaryInf$\lnot !B, !B \fCenter$
      \doubleLine
      \UnaryInf$!B, \lnot !A, \lnot !B \fCenter$
      \RightLabel{\LeftR{\lor}}
      \BinaryInf$ !A \lor !B, \lnot !A, \lnot !B \fCenter $
    \end{prooftree}
    (दुहेरी अनुमान-रेषा दुर्बलीकरण, आकुंचन आणि अदलाबदल यांच्या अनेक अनुमानांना
    दर्शवतात, हे लक्षात ठेवा.)
  \item   $!A \Sequent !A \lor !B$ आणि $!B \Sequent !A
    \lor !B$ या दोन्ही क्रमवर्तींना !!{derivation}s आहेत:
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \RightLabel{\RightR{\lor}}
      \UnaryInf$!A \fCenter !A \lor !B$
      \DisplayProof\qquad\bottomAlignProof
      \Axiom$!B \fCenter !B$
      \RightLabel{\RightR{\lor}}
      \UnaryInf$!B \fCenter !A \lor !B$
    \end{prooftree}
  \end{enumerate}
\end{proof}

