target_excerpt:
\begin{prop}[एकमेव वाचनीयता]
$ \Frm[L_0]$ मधील कोणत्याही !!{formula}~$!A$ चे पुढीलपैकी नेमक्या एका
रूपात रचनाविश्लेषण करता येते:
\begin{enumerate}
\tagitem{prvFalse}{$\lfalse$.}{ }

source_excerpt:
\begin{proof}
Suppose $!A$ is atomic. Then the sequence~$\tuple{!A}$ is a
formation sequence for~$!A$.
%
Now suppose that $!B$ and~$!C$ have formation sequences
$\tuple{!B_0,\dotsc,!B_n}$ and $\tuple{!C_0,\dotsc,!C_m}$
respectively.
%
\begin{enumerate}
  \tagitem{prvNot}{If $!A \ident \lnot !B$,
      then $\tuple{!B_0,\dotsc,!B_n,\lnot !B_n}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvAnd}{If $!A \ident (!B \land !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \land !C_m)}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvOr}{If $!A \ident (!B \lor !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lor !C_m)}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvIf}{If $!A \ident (!B \lif !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lif !C_m)}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvIff}{If $!A \ident (!B \liff !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \liff !C_m)}$
      is a formation sequence for~$!A$.}{}
\end{enumerate}
By the principle of induction on !!{formula}s,
every !!{formula} has a formation sequence.
\end{proof}

target_excerpt:
\begin{proof}
$!A$ आण्विक आहे असे समजा. मग क्रमिका~$\tuple{!A}$ ही $!A$ साठी
रचनाक्रमिका आहे.
%
आता $!B$ आणि~$!C$ यांना अनुक्रमे $\tuple{!B_0,\dotsc,!B_n}$ आणि
$\tuple{!C_0,\dotsc,!C_m}$ या रचनाक्रमिका आहेत असे समजा.
%
\begin{enumerate}
  \tagitem{prvNot}{जर $!A \ident \lnot !B$, तर
      $\tuple{!B_0,\dotsc,!B_n,\lnot !B_n}$ ही $!A$ साठी
      रचनाक्रमिका आहे.}{}
  \tagitem{prvAnd}{जर $!A \ident (!B \land !C)$, तर
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \land !C_m)}$
      ही $!A$ साठी रचनाक्रमिका आहे.}{}
  \tagitem{prvOr}{जर $!A \ident (!B \lor !C)$, तर
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lor !C_m)}$
      ही $!A$ साठी रचनाक्रमिका आहे.}{}
  \tagitem{prvIf}{जर $!A \ident (!B \lif !C)$, तर
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lif !C_m)}$
      ही $!A$ साठी रचनाक्रमिका आहे.}{}
  \tagitem{prvIff}{जर $!A \ident (!B \liff !C)$, तर
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \liff !C_m)}$
      ही $!A$ साठी रचनाक्रमिका आहे.}{}
\end{enumerate}
!!{formula}s वरील विगमनाच्या तत्त्वानुसार प्रत्येक !!{formula} ला एक
रचनाक्रमिका असते.
\end{proof}

\begin{explain}
आरंभीची क्रमवर्ती कशी असते हे आपण सांगितले आहे आणि निगमन नियम दिले आहेत.
क्रमवर्ती कलनातील !!^{derivation}s यांपासून विगमनाधारित रीतीने निर्माण केल्या
जातात: प्रत्येक !!{derivation} ही एकतर स्वतःच आरंभीची क्रमवर्ती असते, किंवा
एका अनुमानाच्या वर असलेल्या एक किंवा दोन !!{derivation}s ने बनलेली असते.
\end{explain}

source_excerpt:
\begin{intro}
You may be familiar with different terminology and symbols than the
ones we use above. Logic texts (and teachers) commonly use either
$\sim$, $\neg$, and~!\ for ``negation'', $\wedge$, $\cdot$, and $\&$
for ``conjunction''.  Commonly used symbols for the ``conditional'' or
``implication'' are $\rightarrow$, $\Rightarrow$, and $\supset$.
\iftag{prvIff,defIff}{Symbols for ``biconditional,'' ``bi-implication,''
  or ``(material) equivalence'' are $\leftrightarrow$,
  $\Leftrightarrow$, and $\equiv$.}{}
\iftag{prvFalse,defFalse}{The $\lfalse$ symbol is variously called
  ``falsity,'' ``falsum,'' ``absurdity,'' or ``bottom.''}{}
\iftag{prvTrue,defTrue}{The $\ltrue$ symbol is variously called
  ``truth,'' ``verum,'' or ``top.''}{}
\end{intro}

target_excerpt:
\begin{intro}
वर आपण वापरलेल्या संज्ञांपेक्षा आणि चिन्हांपेक्षा वेगळ्या संज्ञा व
चिन्हे तुम्हाला परिचित असू शकतात. तर्कशास्त्राच्या ग्रंथांत (आणि
अध्यापनात) ``नकरण'' यासाठी सामान्यतः $\sim$, $\neg$, आणि~!\ यांपैकी
एखादे, तर ``संधियोग'' यासाठी $\wedge$, $\cdot$, आणि $\&$ यांपैकी
एखादे चिन्ह वापरतात. ``सशर्त (संकेतार्थक)'' किंवा ``अभिव्यंजन'' यांसाठी
$\rightarrow$, $\Rightarrow$, आणि $\supset$ ही चिन्हे सामान्यतः
वापरली जातात.
\iftag{prvIff,defIff}{``द्विसशर्त'', ``द्वि-अभिव्यंजन'' किंवा
  ``(वास्तविक) सममूल्यता'' यांसाठी $\leftrightarrow$,
  $\Leftrightarrow$, आणि $\equiv$ ही चिन्हे वापरतात.}{}
\iftag{prvFalse,defFalse}{$\lfalse$ या चिन्हाला वेगवेगळ्या ठिकाणी
  ``असत्यता'', ``फाल्सम'', ``विसंगती'' किंवा ``तळ'' म्हणतात.}{}
\iftag{prvTrue,defTrue}{$\ltrue$ या चिन्हाला वेगवेगळ्या ठिकाणी
  ``सत्यता'', ``वेरम'' किंवा ``शिखर'' म्हणतात.}{}
\end{intro}

