केवळ तेव्हाच, जेव्हा प्रत्येक~$!A \in \Gamma$ साठी $\pSat{v}{!A}$.
\end{defn}

source_excerpt:
\begin{prop}\ollabel{prop:sat-value}
  $\pSat{v}{!A}$ iff $\pValue{v}(!A) = \True$.
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:sat-value}
  $\pSat{v}{!A}$ तेव्हा आणि केवळ तेव्हाच, जेव्हा
  $\pValue{v}(!A) = \True$.
\end{prop}

