source_excerpt:
\begin{proof}
Suppose $!A$ is atomic. Then the sequence~$\tuple{!A}$ is a
formation sequence for~$!A$.
%
Now suppose that $!B$ and~$!C$ have formation sequences
$\tuple{!B_0,\dotsc,!B_n}$ and $\tuple{!C_0,\dotsc,!C_m}$
respectively.
%
\begin{enumerate}
  \tagitem{prvNot}{If $!A \ident \lnot !B$,
      then $\tuple{!B_0,\dotsc,!B_n,\lnot !B_n}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvAnd}{If $!A \ident (!B \land !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \land !C_m)}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvOr}{If $!A \ident (!B \lor !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lor !C_m)}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvIf}{If $!A \ident (!B \lif !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lif !C_m)}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvIff}{If $!A \ident (!B \liff !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \liff !C_m)}$
      is a formation sequence for~$!A$.}{}
\end{enumerate}
By the principle of induction on !!{formula}s,
every !!{formula} has a formation sequence.
\end{proof}

target_excerpt:
\begin{proof}
$!A$ आण्विक आहे असे समजा. मग क्रमिका~$\tuple{!A}$ ही $!A$ साठी
रचनाक्रमिका आहे.
%
आता $!B$ आणि~$!C$ यांना अनुक्रमे $\tuple{!B_0,\dotsc,!B_n}$ आणि
$\tuple{!C_0,\dotsc,!C_m}$ या रचनाक्रमिका आहेत असे समजा.
%
\begin{enumerate}
  \tagitem{prvNot}{जर $!A \ident \lnot !B$, तर
      $\tuple{!B_0,\dotsc,!B_n,\lnot !B_n}$ ही $!A$ साठी
      रचनाक्रमिका आहे.}{}
  \tagitem{prvAnd}{जर $!A \ident (!B \land !C)$, तर
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \land !C_m)}$
      ही $!A$ साठी रचनाक्रमिका आहे.}{}
  \tagitem{prvOr}{जर $!A \ident (!B \lor !C)$, तर
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lor !C_m)}$
      ही $!A$ साठी रचनाक्रमिका आहे.}{}
  \tagitem{prvIf}{जर $!A \ident (!B \lif !C)$, तर
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lif !C_m)}$
      ही $!A$ साठी रचनाक्रमिका आहे.}{}
  \tagitem{prvIff}{जर $!A \ident (!B \liff !C)$, तर
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \liff !C_m)}$
      ही $!A$ साठी रचनाक्रमिका आहे.}{}
\end{enumerate}
!!{formula}s वरील विगमनाच्या तत्त्वानुसार प्रत्येक !!{formula} ला एक
रचनाक्रमिका असते.
\end{proof}

source_excerpt:
\begin{defn}
  Given !!a{valuation}~$\pAssign{v}$, define the evaluation function
  $\pValue{v} \colon \Frm[L_0] \to \{\True, \False \}$ inductively by:
  \begin{align*}
    \iftag{prvFalse}{\pValue{v}(\lfalse) & = \False; \\}{}
    \iftag{prvTrue}{\pValue{v}(\ltrue) & = \True; \\}{}
    \pValue{v}(\Obj p_n) & = \pAssign{v}(\Obj p_n); \\
    \iftag{prvNot}{\pValue{v}(\lnot !A) & = \begin{cases}
        \True & \text{if } \pValue{v}(!A) = \False;\\
        \False & \text{otherwise.}
      \end{cases} \\ }{}
    \iftag{prvAnd}{\pValue{v}(!A \land !B) & = \begin{cases}
        \True &
        \text{if $\pValue{v}(!A) = \True$ and $\pValue{v}(!B) = \True$;}\\
        \False &
        \text{if $\pValue{v}(!A) = \False$ or $\pValue{v}(!B) = \False$}.
      \end{cases}\\}{}
    \iftag{prvOr}{\pValue{v}(!A \lor !B) & = \begin{cases}
        \True &
        \text{if $\pValue{v}(!A) = \True$ or $\pValue{v}(!B) = \True$;}\\
        \False &
        \text{if $\pValue{v}(!A) = \False$ and $\pValue{v}(!B) = \False$}.
      \end{cases}\\}{}
    \iftag{prvIf}{\pValue{v}(!A \lif !B) & = \begin{cases}
        \True &
        \text{if $\pValue{v}(!A) = \False$ or $\pValue{v}(!B) = \True$;}\\
        \False &
        \text{if $\pValue{v}(!A) = \True$ and $\pValue{v}(!B) = \False$}.
      \end{cases}\\}{}
    \iftag{prvIff}{\pValue{v}(!A \liff !B) & = \begin{cases}
        \True &
        \text{if $\pValue{v}(!A) = \pValue{v}(!B)$;}\\
        \False &
        \text{if $\pValue{v}(!A) \neq \pValue{v}(!B)$}.
      \end{cases}}{}
\end{align*}
\end{defn}

target_excerpt:
\begin{defn}
  दिलेले !!a{valuation}~$\pAssign{v}$ असताना, मूल्यन फलन
  $\pValue{v} \colon \Frm[L_0] \to \{\True, \False \}$ पुढीलप्रमाणे
  विगमनाने परिभाषित करू:
  \begin{align*}
    \iftag{prvFalse}{\pValue{v}(\lfalse) & = \False; \\}{}
    \iftag{prvTrue}{\pValue{v}(\ltrue) & = \True; \\}{}
    \pValue{v}(\Obj p_n) & = \pAssign{v}(\Obj p_n); \\
    \iftag{prvNot}{\pValue{v}(\lnot !A) & = \begin{cases}
        \True & \text{जर } \pValue{v}(!A) = \False;\\
        \False & \text{अन्यथा.}
      \end{cases} \\ }{}
    \iftag{prvAnd}{\pValue{v}(!A \land !B) & = \begin{cases}
        \True &
        \text{जर $\pValue{v}(!A) = \True$ आणि $\pValue{v}(!B) = \True$;}\\
        \False &
        \text{जर $\pValue{v}(!A) = \False$ किंवा $\pValue{v}(!B) = \False$}.
      \end{cases}\\}{}
    \iftag{prvOr}{\pValue{v}(!A \lor !B) & = \begin{cases}
        \True &
        \text{जर $\pValue{v}(!A) = \True$ किंवा $\pValue{v}(!B) = \True$;}\\
        \False &
        \text{जर $\pValue{v}(!A) = \False$ आणि $\pValue{v}(!B) = \False$}.
      \end{cases}\\}{}
    \iftag{prvIf}{\pValue{v}(!A \lif !B) & = \begin{cases}
        \True &
        \text{जर $\pValue{v}(!A) = \False$ किंवा $\pValue{v}(!B) = \True$;}\\
        \False &
        \text{जर $\pValue{v}(!A) = \True$ आणि $\pValue{v}(!B) = \False$}.
      \end{cases}\\}{}
    \iftag{prvIff}{\pValue{v}(!A \liff !B) & = \begin{cases}
        \True &
        \text{जर $\pValue{v}(!A) = \pValue{v}(!B)$;}\\
        \False &
        \text{जर $\pValue{v}(!A) \neq \pValue{v}(!B)$}.
      \end{cases}}{}
\end{align*}
\end{defn}

