source_excerpt:
\begin{thm}[\emph{Principle of induction on !!{formula}s}]
  \ollabel{thm:induction}
  If some property~$P$ holds for all the atomic !!{formula}s and is
  such that
  \begin{enumerate}
    \tagitem{prvNot}{it holds for $\lnot !A$ whenever it holds
      for~$!A$;}{}
    \tagitem{prvAnd}{it holds for $(!A \land !B)$
      whenever it holds for $!A$ and~$!B$;}{}
    \tagitem{prvOr}{it holds for $(!A \lor !B)$
      whenever it holds for $!A$ and~$!B$;}{}
    \tagitem{prvIf}{it holds for $(!A \lif !B)$
      whenever it holds for $!A$ and~$!B$;}{}
    \tagitem{prvIff}{it holds for $(!A \liff !B)$
      whenever it holds for $!A$ and~$!B$;}{}
  \end{enumerate}
  then $P$ holds for all !!{formula}s.
\end{thm}

target_excerpt:
\begin{thm}[\emph{!!{formula}s वरील विगमनाचे तत्त्व}]
  \ollabel{thm:induction}
  एखादा गुणधर्म~$P$ सर्व आण्विक !!{formula}s साठी लागू होत असेल आणि
  पुढील अटी पूर्ण करत असेल:
  \begin{enumerate}
    \tagitem{prvNot}{तो~$!A$ साठी लागू असताना $\lnot !A$ साठीही
      लागू होतो;}{ }
    \tagitem{prvAnd}{तो~$!A$ आणि~$!B$ यांच्यासाठी लागू असताना
      $(!A \land !B)$ साठीही लागू होतो;}{ }
    \tagitem{prvOr}{तो~$!A$ आणि~$!B$ यांच्यासाठी लागू असताना
      $(!A \lor !B)$ साठीही लागू होतो;}{ }
    \tagitem{prvIf}{तो~$!A$ आणि~$!B$ यांच्यासाठी लागू असताना
      $(!A \lif !B)$ साठीही लागू होतो;}{ }
    \tagitem{prvIff}{तो~$!A$ आणि~$!B$ यांच्यासाठी लागू असताना
      $(!A \liff !B)$ साठीही लागू होतो;}{ }
  \end{enumerate}
  तर $P$ सर्व !!{formula}s साठी लागू होतो.
\end{thm}

source_excerpt:
\begin{proof}
Suppose $!A$ is atomic. Then the sequence~$\tuple{!A}$ is a
formation sequence for~$!A$.
%
Now suppose that $!B$ and~$!C$ have formation sequences
$\tuple{!B_0,\dotsc,!B_n}$ and $\tuple{!C_0,\dotsc,!C_m}$
respectively.
%
\begin{enumerate}
  \tagitem{prvNot}{If $!A \ident \lnot !B$,
      then $\tuple{!B_0,\dotsc,!B_n,\lnot !B_n}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvAnd}{If $!A \ident (!B \land !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \land !C_m)}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvOr}{If $!A \ident (!B \lor !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lor !C_m)}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvIf}{If $!A \ident (!B \lif !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lif !C_m)}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvIff}{If $!A \ident (!B \liff !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \liff !C_m)}$
      is a formation sequence for~$!A$.}{}
\end{enumerate}
By the principle of induction on !!{formula}s,
every !!{formula} has a formation sequence.
\end{proof}

target_excerpt:
\begin{proof}
$!A$ आण्विक आहे असे समजा. मग क्रमिका~$\tuple{!A}$ ही $!A$ साठी
रचनाक्रमिका आहे.
%
आता $!B$ आणि~$!C$ यांना अनुक्रमे $\tuple{!B_0,\dotsc,!B_n}$ आणि
$\tuple{!C_0,\dotsc,!C_m}$ या रचनाक्रमिका आहेत असे समजा.
%
\begin{enumerate}
  \tagitem{prvNot}{जर $!A \ident \lnot !B$, तर
      $\tuple{!B_0,\dotsc,!B_n,\lnot !B_n}$ ही $!A$ साठी
      रचनाक्रमिका आहे.}{}
  \tagitem{prvAnd}{जर $!A \ident (!B \land !C)$, तर
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \land !C_m)}$
      ही $!A$ साठी रचनाक्रमिका आहे.}{}
  \tagitem{prvOr}{जर $!A \ident (!B \lor !C)$, तर
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lor !C_m)}$
      ही $!A$ साठी रचनाक्रमिका आहे.}{}
  \tagitem{prvIf}{जर $!A \ident (!B \lif !C)$, तर
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lif !C_m)}$
      ही $!A$ साठी रचनाक्रमिका आहे.}{}
  \tagitem{prvIff}{जर $!A \ident (!B \liff !C)$, तर
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \liff !C_m)}$
      ही $!A$ साठी रचनाक्रमिका आहे.}{}
\end{enumerate}
!!{formula}s वरील विगमनाच्या तत्त्वानुसार प्रत्येक !!{formula} ला एक
रचनाक्रमिका असते.
\end{proof}

\begin{defn}[विन्यासात्मक अनन्यता]
$\ident$ हे चिन्ह चिन्हमालांमधील विन्यासात्मक अनन्यता व्यक्त करते;
म्हणजे $!A \ident !B$ तेव्हा आणि केवळ तेव्हाच, जेव्हा $!A$ आणि $!B$
या समान लांबीच्या चिन्हमाला असतात आणि प्रत्येक स्थानी त्यांच्यात तेच
चिन्ह असते.
\end{defn}

