source_excerpt:
\begin{prop}
\ollabel{prop:semanticalfacts}
\begin{enumerate}
\item $!A$ is a tautology if and only if
  $\emptyset \Entails !A$;
\item If $\Gamma \Entails !A$ and $\Gamma \Entails !A \lif !B$ then
  $\Gamma \Entails !B$;
\item If $\Gamma$ is satisfiable then every finite subset of $\Gamma$
  is also satisfiable;
\item \ollabel{def:monotonicity} Monotonicity: if $\Gamma \subseteq \Delta$
  and $\Gamma \Entails !A$ then also $\Delta \Entails !A$;
\item \ollabel{def:Cut} Transitivity: if $\Gamma \Entails !A$ and
  $\Delta \cup \{ !A\} \Entails !B$ then $\Gamma \cup \Delta \Entails
  !B$.
\end{enumerate}
\end{prop}

target_excerpt:
\begin{prop}
\ollabel{prop:semanticalfacts}
\begin{enumerate}
\item $!A$ हे सर्वतः सत्य सूत्र तेव्हा आणि केवळ तेव्हाच असते, जेव्हा
  $\emptyset \Entails !A$;
\item $\Gamma \Entails !A$ आणि $\Gamma \Entails !A \lif !B$ असल्यास
  $\Gamma \Entails !B$;
\item $\Gamma$ पूर्ततायोग्य असेल, तर $\Gamma$ चा प्रत्येक सांत उपसंचही
  पूर्ततायोग्य असतो;
\item \ollabel{def:monotonicity} एकस्वनिकता: $\Gamma \subseteq \Delta$
  आणि $\Gamma \Entails !A$ असल्यास $\Delta \Entails !A$ हेही असते;
\item \ollabel{def:Cut} संक्रमकता: $\Gamma \Entails !A$ आणि
  $\Delta \cup \{ !A\} \Entails !B$ असल्यास $\Gamma \cup \Delta \Entails
  !B$.
\end{enumerate}
\end{prop}

source_excerpt:
\begin{prop}[Compactness]
  \ollabel{prop:proves-compact}
  \begin{enumerate}
  \item If $\Gamma \Proves !A$ then there is a finite subset $\Gamma_0
    \subseteq \Gamma$ such that $\Gamma_0 \Proves !A$.
  \item If every finite subset of~$\Gamma$ is
    consistent, then $\Gamma$ is consistent.
  \end{enumerate}
\end{prop}

target_excerpt:
\begin{prop}[संहतता]
  \ollabel{prop:proves-compact}
  \begin{enumerate}
  \item $\Gamma \Proves !A$ असेल, तर एखादा सांत उपसंच $\Gamma_0
    \subseteq \Gamma$ असा आहे की $\Gamma_0 \Proves !A$.
  \item $\Gamma$ चा प्रत्येक सांत उपसंच सुसंगत असेल, तर $\Gamma$ सुसंगत
    असतो.
  \end{enumerate}
\end{prop}

source_excerpt:
\begin{proof}
  \begin{enumerate}
    \item If $\Gamma \Proves !A$, then there is a finite subset
      $\Gamma_0 \subseteq \Gamma$ such that the sequent $\Gamma_0
      \Sequent !A$ has !!a{derivation}. Consequently, $\Gamma_0
      \Proves !A$.
    \item If $\Gamma$ is inconsistent, there is a finite
      subset~$\Gamma_0 \subseteq \Gamma$ such that $\Log{LK}$
      !!{derive}s $\Gamma_0 \Sequent \quad$. But then $\Gamma_0$ is a
      finite subset of~$\Gamma$ that is inconsistent.
  \end{enumerate}
\end{proof}

target_excerpt:
\begin{proof}
  \begin{enumerate}
    \item $\Gamma \Proves !A$ असेल, तर एखादा सांत उपसंच
      $\Gamma_0 \subseteq \Gamma$ असा आहे की $\Gamma_0
      \Sequent !A$ या क्रमवर्तीची !!a{derivation} आहे. परिणामी,
      $\Gamma_0 \Proves !A$.
    \item $\Gamma$ विसंगत असेल, तर एखादा सांत
      उपसंच~$\Gamma_0 \subseteq \Gamma$ असा आहे की $\Log{LK}$
      $\Gamma_0 \Sequent \quad$ हे !!{derive}s करते. पण मग $\Gamma_0$ हा
      $\Gamma$ चा विसंगत सांत उपसंच आहे.
  \end{enumerate}
\end{proof}

