source_excerpt:
\begin{defn}
\begin{enumerate}
\item !!^a{formula}~$!A$ is \emph{satisfiable} if for
  some~$\pAssign{v}$, $\pSat{v}{!A}$; it is
  \emph{unsatisfiable} if for no $\pAssign{v}$, $\pSat{v}{!A}$;
\item !!^a{formula}~$!A$ is a \emph{tautology} if $\pSat{v}{!A}$ for
  all !!{valuation}s~$\pAssign{v}$;
\item !!^a{formula}~$!A$ is \emph{contingent} if it is satisfiable but
  not a tautology;
\item If $\Gamma$ is a set of !!{formula}s, $\Gamma \Entails !A$ (``$\Gamma$
  entails $!A$'') if and only if $\pSat{v}{!A}$ for every
  !!{valuation}~$\pAssign{v}$ for which $\pSat{v}{\Gamma}$.
\item If $\Gamma$ is a set of !!{formula}s, $\Gamma$ is
  \emph{satisfiable} if there is !!a{valuation}~$\pAssign{v}$ for which
  $\pSat{v}{\Gamma}$, and $\Gamma$ is
  \emph{unsatisfiable} otherwise.
\end{enumerate}
\end{defn}

target_excerpt:
\begin{defn}
\begin{enumerate}
\item !!^a{formula}~$!A$ हे \emph{पूर्ततायोग्य} असते, जर एखाद्या
  $\pAssign{v}$ साठी $\pSat{v}{!A}$; आणि कोणत्याही $\pAssign{v}$ साठी
  $\pSat{v}{!A}$ नसल्यास ते \emph{अपूर्ततायोग्य} असते;
\item सर्व !!{valuation}s~$\pAssign{v}$ साठी $\pSat{v}{!A}$ असेल, तर
  !!^a{formula}~$!A$ हे \emph{सर्वतः सत्य सूत्र} असते;
\item !!^a{formula}~$!A$ हे पूर्ततायोग्य असेल, पण सर्वतः सत्य सूत्र नसेल,
  तर ते \emph{परिस्थितीवश} असते;
\item $\Gamma$ हा !!{formula}s चा संच असेल, तर $\Gamma \Entails !A$
  (``$\Gamma$ पासून $!A$ तार्किकरीत्या निष्पन्न होते'') तेव्हा आणि केवळ
  तेव्हाच, जेव्हा $\pSat{v}{\Gamma}$ असलेल्या प्रत्येक
  !!{valuation}~$\pAssign{v}$ साठी $\pSat{v}{!A}$.
\item $\Gamma$ हा !!{formula}s चा संच असेल, तर एखाद्या
  !!a{valuation}~$\pAssign{v}$ साठी $\pSat{v}{\Gamma}$ असल्यास $\Gamma$
  हा \emph{पूर्ततायोग्य} असतो; अन्यथा $\Gamma$ हा
  \emph{अपूर्ततायोग्य} असतो.
\end{enumerate}
\end{defn}

source_excerpt:
\begin{prop}\ollabel{prop:entails-unsat}
  $\Gamma \Entails !A$ if and only if $\Gamma \cup \{\lnot !A\}$
  is unsatisfiable.
\end{prop}

