\begin{prop}\ollabel{prop:entails-unsat}
  $\Gamma \Entails !A$ तेव्हा आणि केवळ तेव्हाच, जेव्हा
  $\Gamma \cup \{\lnot !A\}$ अपूर्ततायोग्य असतो.
\end{prop}

source_excerpt:
\begin{prop}
\ollabel{prop:semanticalfacts}
\begin{enumerate}
\item $!A$ is a tautology if and only if
  $\emptyset \Entails !A$;
\item If $\Gamma \Entails !A$ and $\Gamma \Entails !A \lif !B$ then
  $\Gamma \Entails !B$;
\item If $\Gamma$ is satisfiable then every finite subset of $\Gamma$
  is also satisfiable;
\item \ollabel{def:monotonicity} Monotonicity: if $\Gamma \subseteq \Delta$
  and $\Gamma \Entails !A$ then also $\Delta \Entails !A$;
\item \ollabel{def:Cut} Transitivity: if $\Gamma \Entails !A$ and
  $\Delta \cup \{ !A\} \Entails !B$ then $\Gamma \cup \Delta \Entails
  !B$.
\end{enumerate}
\end{prop}

target_excerpt:
\begin{prop}
\ollabel{prop:semanticalfacts}
\begin{enumerate}
\item $!A$ हे सर्वतः सत्य सूत्र तेव्हा आणि केवळ तेव्हाच असते, जेव्हा
  $\emptyset \Entails !A$;
\item $\Gamma \Entails !A$ आणि $\Gamma \Entails !A \lif !B$ असल्यास
  $\Gamma \Entails !B$;
\item $\Gamma$ पूर्ततायोग्य असेल, तर $\Gamma$ चा प्रत्येक सांत उपसंचही
  पूर्ततायोग्य असतो;
\item \ollabel{def:monotonicity} एकस्वनिकता: $\Gamma \subseteq \Delta$
  आणि $\Gamma \Entails !A$ असल्यास $\Delta \Entails !A$ हेही असते;
\item \ollabel{def:Cut} संक्रमकता: $\Gamma \Entails !A$ आणि
  $\Delta \cup \{ !A\} \Entails !B$ असल्यास $\Gamma \cup \Delta \Entails
  !B$.
\end{enumerate}
\end{prop}

source_excerpt:
\begin{prop}[Monotonicity]
\ollabel{prop:monotonicity}
If $\Gamma \subseteq \Delta$ and $\Gamma \Proves !A$, then $\Delta
\Proves !A$.
\end{prop}

target_excerpt:
\begin{prop}[एकस्वनिकता]
\ollabel{prop:monotonicity}
$\Gamma \subseteq \Delta$ आणि $\Gamma \Proves !A$ असेल, तर $\Delta
\Proves !A$.
\end{prop}

source_excerpt:
\begin{prop}[Monotonicity]
\ollabel{prop:monotonicity}
If $\Gamma \subseteq \Delta$ and $\Gamma \Proves !A$, then $\Delta
\Proves !A$.
\end{prop}

target_excerpt:
\begin{prop}[एकस्वनिकता]
\ollabel{prop:monotonicity}
$\Gamma \subseteq \Delta$ आणि $\Gamma \Proves !A$ असेल, तर $\Delta
\Proves !A$.
\end{prop}

source_excerpt:
\begin{proof}
Any !!{derivation} of $!A$ from $\Gamma$ is also !!a{derivation} of
$!A$ from~$\Delta$.
\end{proof}

target_excerpt:
\begin{proof}
$\Gamma$ पासून $!A$ ची कोणतीही !!{derivation} ही $\Delta$ पासून $!A$ चीही
!!a{derivation} असते.
\end{proof}

$\Gamma \Proves \lfalse$ असेल, तर संच $\Gamma$ विसंगत असतो. संपूर्ण
स्वयंसिद्धकीय पद्धत कोणत्याही~$!A$ साठी $\lfalse \lif !A$ हेही सिद्ध करेल;
त्यामुळे $\Gamma$ विसंगत असेल, तर कोणत्याही~$!A$ साठी $\Gamma \Proves !A$.

source_excerpt:
