source_excerpt:
\begin{prop}
\ollabel{prop:incons}
$\Gamma$ is inconsistent iff $\Gamma \Proves {!A}$ for every
  sentence~$!A$.
\end{prop}

target_excerpt:
\begin{prop}
\ollabel{prop:incons}
$\Gamma$ विसंगत असतो तेव्हा आणि केवळ तेव्हाच, जेव्हा प्रत्येक
  वाक्य~$!A$ साठी $\Gamma \Proves {!A}$.
\end{prop}

