source_excerpt:
\begin{prop}[Compactness]
  \ollabel{prop:proves-compact}
  \begin{enumerate}
  \item If $\Gamma \Proves !A$ then there is a finite subset $\Gamma_0
    \subseteq \Gamma$ such that $\Gamma_0 \Proves !A$.
  \item If every finite subset of~$\Gamma$ is
    consistent, then $\Gamma$ is consistent.
  \end{enumerate}
\end{prop}

target_excerpt:
\begin{prop}[संहतता]
  \ollabel{prop:proves-compact}
  \begin{enumerate}
  \item $\Gamma \Proves !A$ असेल, तर एखादा सांत उपसंच $\Gamma_0
    \subseteq \Gamma$ असा आहे की $\Gamma_0 \Proves !A$.
  \item $\Gamma$ चा प्रत्येक सांत उपसंच सुसंगत असेल, तर $\Gamma$ सुसंगत
    असतो.
  \end{enumerate}
\end{prop}

source_excerpt:
\begin{proof}
  \begin{enumerate}
    \item If $\Gamma \Proves !A$, then there is a finite subset
      $\Gamma_0 \subseteq \Gamma$ such that the sequent $\Gamma_0
      \Sequent !A$ has !!a{derivation}. Consequently, $\Gamma_0
      \Proves !A$.
    \item If $\Gamma$ is inconsistent, there is a finite
      subset~$\Gamma_0 \subseteq \Gamma$ such that $\Log{LK}$
      !!{derive}s $\Gamma_0 \Sequent \quad$. But then $\Gamma_0$ is a
      finite subset of~$\Gamma$ that is inconsistent.
  \end{enumerate}
\end{proof}

target_excerpt:
\begin{proof}
  \begin{enumerate}
    \item $\Gamma \Proves !A$ असेल, तर एखादा सांत उपसंच
      $\Gamma_0 \subseteq \Gamma$ असा आहे की $\Gamma_0
      \Sequent !A$ या क्रमवर्तीची !!a{derivation} आहे. परिणामी,
      $\Gamma_0 \Proves !A$.
    \item $\Gamma$ विसंगत असेल, तर एखादा सांत
      उपसंच~$\Gamma_0 \subseteq \Gamma$ असा आहे की $\Log{LK}$
      $\Gamma_0 \Sequent \quad$ हे !!{derive}s करते. पण मग $\Gamma_0$ हा
      $\Gamma$ चा विसंगत सांत उपसंच आहे.
  \end{enumerate}
\end{proof}

source_excerpt:
\begin{prop}\ollabel{prop:provability-contr}
  If $\Gamma \Proves !A$ and $\Gamma \cup \{!A\}$ is
  inconsistent, then $\Gamma$ is inconsistent.
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:provability-contr}
  जर $\Gamma \Proves !A$ आणि $\Gamma \cup \{!A\}$ विसंगत असेल, तर
  $\Gamma$ विसंगत आहे.
\end{prop}

source_excerpt:
\begin{proof}
There are finite $\Gamma_0$ and $\Gamma_1 \subseteq \Gamma$ such that
$\Log{LK}$ !!{derive}s $\Gamma_0 \Sequent !A$ and $!A, \Gamma_1
\Sequent \quad$.  Let the $\Log{LK}$-!!{derivation} of $\Gamma_0 \Sequent
!A$ be~$\pi_0$ and the $\Log{LK}$-!!{derivation} of $\Gamma_1, !A
\Sequent \quad$ be~$\pi_1$. We can then !!{derive}
\begin{prooftree}
\AxiomC{}
\RightLabel{$\pi_0$}
\Deduce$ \Gamma_0 \fCenter !A $
\AxiomC{}
\RightLabel{$\pi_1$}
\Deduce$!A, \Gamma_1 \fCenter $
\RightLabel{\Cut}
\BinaryInf$ \Gamma_0,\Gamma_1 \fCenter $
\end{prooftree}

target_excerpt:
\begin{proof}
अशी सांत $\Gamma_0$ आणि $\Gamma_1 \subseteq \Gamma$ असतात की
$\Log{LK}$ !!{derive}s $\Gamma_0 \Sequent !A$ आणि $!A, \Gamma_1
\Sequent \quad$. $\Gamma_0 \Sequent !A$ ची $\Log{LK}$-!!{derivation}
~$\pi_0$ आणि $\Gamma_1, !A \Sequent \quad$ ची $\Log{LK}$-!!{derivation}
~$\pi_1$ अशी नावे देऊ. मग आपण !!{derive} करू शकतो
\begin{prooftree}
\AxiomC{}
\RightLabel{$\pi_0$}
\Deduce$ \Gamma_0 \fCenter !A $
\AxiomC{}
\RightLabel{$\pi_1$}
\Deduce$!A, \Gamma_1 \fCenter $
\RightLabel{\Cut}
\BinaryInf$ \Gamma_0,\Gamma_1 \fCenter $
\end{prooftree}

source_excerpt:
Since $\Gamma_0 \subseteq \Gamma$ and $\Gamma_1 \subseteq \Gamma$,
$\Gamma_0 \cup \Gamma_1 \subseteq \Gamma$, hence $\Gamma$~is inconsistent.
\end{proof}

target_excerpt:
कारण $\Gamma_0 \subseteq \Gamma$ आणि $\Gamma_1 \subseteq \Gamma$,
$\Gamma_0 \cup \Gamma_1 \subseteq \Gamma$; म्हणून $\Gamma$ विसंगत आहे.
\end{proof}

source_excerpt:
\begin{prop}
\ollabel{prop:prov-incons}
$\Gamma \Proves !A$ iff $\Gamma \cup \{\lnot !A\}$ is inconsistent.
\end{prop}

target_excerpt:
\begin{prop}
\ollabel{prop:prov-incons}
$\Gamma \Proves !A$ तेव्हा आणि केवळ तेव्हाच, जेव्हा $\Gamma \cup \{\lnot !A\}$
विसंगत असते.
\end{prop}

source_excerpt:
If $\Gamma \cup \{\lnot !A\}$ is inconsistent, there is
!!a{derivation}~$\pi_1$ of $\lnot !A, \Gamma \Sequent \quad$. The
following is !!a{derivation} of $\Gamma \Sequent !A$:
\begin{prooftree}
  \Axiom$!A \fCenter !A$
  \RightLabel{\RightR{\lnot}}
  \UnaryInf$\fCenter !A, \lnot !A$
  \AxiomC{}
  \RightLabel{$\pi_1$}
  \Deduce$\lnot !A, \Gamma \fCenter$
  \RightLabel{\Cut}
  \BinaryInf$\Gamma \fCenter !A$
\end{prooftree}
\end{proof}

target_excerpt:
जर $\Gamma \cup \{\lnot !A\}$ विसंगत असेल, तर $\lnot !A, \Gamma
\Sequent \quad$ ची !!a{derivation}~$\pi_1$ असते. खालील $\Gamma \Sequent !A$
ची !!a{derivation} आहे:
\begin{prooftree}
  \Axiom$!A \fCenter !A$
  \RightLabel{\RightR{\lnot}}
  \UnaryInf$\fCenter !A, \lnot !A$
  \AxiomC{}
  \RightLabel{$\pi_1$}
  \Deduce$\lnot !A, \Gamma \fCenter$
  \RightLabel{\Cut}
  \BinaryInf$\Gamma \fCenter !A$
\end{prooftree}
\end{proof}

source_excerpt:
\begin{prob}
Prove that $\Gamma \Proves \lnot !A$ iff $\Gamma \cup \{!A\}$ is inconsistent.
\end{prob}

