source_excerpt:
\begin{prop}\ollabel{prop:explicit-inc}
  If $\Gamma \Proves !A$ and $\lnot !A \in \Gamma$, then $\Gamma$ is
  inconsistent.
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:explicit-inc}
  जर $\Gamma \Proves !A$ आणि $\lnot !A \in \Gamma$ असेल, तर $\Gamma$
  विसंगत आहे.
\end{prop}

source_excerpt:
\begin{proof}
  Suppose $\Gamma \Proves !A$ and $\lnot !A \in \Gamma$.  Then there
  is !!a{derivation}~$\pi$ of a sequent $\Gamma_0 \Sequent !A$. The
  sequent $\lnot !A, \Gamma_0 \Sequent \quad$ is also !!{derivable}:
  \begin{prooftree}
    \AxiomC{}
    \RightLabel{$\pi$}
    \Deduce$\Gamma_0 \fCenter !A$
    \Axiom$!A \fCenter !A$
    \RightLabel{\LeftR{\lnot}}
    \UnaryInf$\lnot !A, !A \fCenter$
    \RightLabel{\LeftR{\Exchange}}
    \UnaryInf$!A, \lnot !A \fCenter$
    \RightLabel{\Cut}
    \BinaryInf$\Gamma_0, \lnot !A \fCenter$
  \end{prooftree}
  Since $\lnot !A \in \Gamma$ and $\Gamma_0 \subseteq \Gamma$, this
  shows that $\Gamma$ is inconsistent.
\end{proof}

target_excerpt:
\begin{proof}
  समजा $\Gamma \Proves !A$ आणि $\lnot !A \in \Gamma$. मग $\Gamma_0 \Sequent
  !A$ ची !!a{derivation}~$\pi$ असते. $\lnot !A, \Gamma_0 \Sequent \quad$
  ही क्रमवर्तीही !!{derivable} आहे:
  \begin{prooftree}
    \AxiomC{}
    \RightLabel{$\pi$}
    \Deduce$\Gamma_0 \fCenter !A$
    \Axiom$!A \fCenter !A$
    \RightLabel{\LeftR{\lnot}}
    \UnaryInf$\lnot !A, !A \fCenter$
    \RightLabel{\LeftR{\Exchange}}
    \UnaryInf$!A, \lnot !A \fCenter$
    \RightLabel{\Cut}
    \BinaryInf$\Gamma_0, \lnot !A \fCenter$
  \end{prooftree}
  कारण $\lnot !A \in \Gamma$ आणि $\Gamma_0 \subseteq \Gamma$, यावरून
  $\Gamma$ विसंगत असल्याचे दिसते.
\end{proof}

source_excerpt:
\begin{prop}\ollabel{prop:provability-exhaustive}
  If $\Gamma \cup \{!A\}$ and $\Gamma \cup \{\lnot !A\}$ are both
  inconsistent, then $\Gamma$ is inconsistent.
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:provability-exhaustive}
  जर $\Gamma \cup \{!A\}$ आणि $\Gamma \cup \{\lnot !A\}$ दोन्ही
  विसंगत असतील, तर $\Gamma$ विसंगत आहे.
\end{prop}

source_excerpt:
\begin{proof}
There are finite sets $\Gamma_0 \subseteq \Gamma$ and $\Gamma_1
\subseteq \Gamma$ and $\Log{LK}$-!!{derivation}s $\pi_0$ and $\pi_1$
of $!A, \Gamma_0 \Sequent \quad$ and $\lnot !A, \Gamma_1 \Sequent
\quad$, respectively. We can then !!{derive}
\begin{prooftree}
\AxiomC{}
\RightLabel{$\pi_0$}
\Deduce$ !A, \Gamma_0 \fCenter $
\RightLabel{\RightR{\lnot}}
\UnaryInf$ \Gamma_0 \fCenter \lnot !A$
\AxiomC{}
\RightLabel{$\pi_1$}
\Deduce$\lnot !A, \Gamma_1 \fCenter  $
\RightLabel{\Cut}
\BinaryInf$ \Gamma_0, \Gamma_1 \fCenter $
\end{prooftree}
Since $\Gamma_0 \subseteq \Gamma$ and $\Gamma_1 \subseteq \Gamma$,
$\Gamma_0 \cup \Gamma_1 \subseteq \Gamma$. Hence $\Gamma$ is
inconsistent.
\end{proof}

target_excerpt:
\begin{proof}
अशी सांत संच $\Gamma_0 \subseteq \Gamma$ आणि $\Gamma_1
\subseteq \Gamma$, तसेच $\Log{LK}$-!!{derivation}s $\pi_0$ आणि $\pi_1$
$!A, \Gamma_0 \Sequent \quad$ आणि $\lnot !A, \Gamma_1 \Sequent
\quad$ यांचे अनुक्रमे, असतात. मग आपण !!{derive} करू शकतो
\begin{prooftree}
\AxiomC{}
\RightLabel{$\pi_0$}
\Deduce$ !A, \Gamma_0 \fCenter $
\RightLabel{\RightR{\lnot}}
\UnaryInf$ \Gamma_0 \fCenter \lnot !A$
\AxiomC{}
\RightLabel{$\pi_1$}
\Deduce$\lnot !A, \Gamma_1 \fCenter  $
\RightLabel{\Cut}
\BinaryInf$ \Gamma_0, \Gamma_1 \fCenter $
\end{prooftree}
कारण $\Gamma_0 \subseteq \Gamma$ आणि $\Gamma_1 \subseteq \Gamma$,
$\Gamma_0 \cup \Gamma_1 \subseteq \Gamma$. म्हणून $\Gamma$ विसंगत आहे.
\end{proof}

source_excerpt:
\begin{prop}\ollabel{prop:provability-lor}
  \begin{enumerate}
  \item $!A \lor !B, \lnot !A, \lnot !B$ is inconsistent.
  \item Both $!A \Proves !A \lor !B$ and $!B \Proves !A \lor !B$.
  \end{enumerate}
\end{prop}

target_excerpt:
\begin{prop}\ollabel{prop:provability-lor}
  \begin{enumerate}
  \item $!A \lor !B, \lnot !A, \lnot !B$ विसंगत आहे.
  \item $!A \Proves !A \lor !B$ आणि $!B \Proves !A \lor !B$ ही दोन्ही तथ्ये आहेत.
  \end{enumerate}
\end{prop}

source_excerpt:
\begin{proof}
  \begin{enumerate}
  \item We give !!a{derivation} of the sequent $!A \lor !B, \lnot !A,
    \lnot !B \Sequent$:
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \RightLabel{\LeftR{\lnot}}
      \UnaryInf$\lnot !A, !A \fCenter$
      \doubleLine
      \UnaryInf$!A, \lnot !A, \lnot !B \fCenter$
      \Axiom$!B \fCenter !B$
      \RightLabel{\LeftR{\lnot}}
      \UnaryInf$\lnot !B, !B \fCenter$
      \doubleLine
      \UnaryInf$!B, \lnot !A, \lnot !B \fCenter$
      \RightLabel{\LeftR{\lor}}
      \BinaryInf$ !A \lor !B, \lnot !A, \lnot !B \fCenter $
    \end{prooftree}
    (Recall that double inference lines indicate several weakening,
    contraction, and exchange inferences.)
  \item   Both sequents $!A \Sequent !A \lor !B$ and $!B \Sequent !A
    \lor !B$ have !!{derivation}s:
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \RightLabel{\RightR{\lor}}
      \UnaryInf$!A \fCenter !A \lor !B$
      \DisplayProof\qquad\bottomAlignProof
      \Axiom$!B \fCenter !B$
      \RightLabel{\RightR{\lor}}
      \UnaryInf$!B \fCenter !A \lor !B$
    \end{prooftree}
  \end{enumerate}
\end{proof}

target_excerpt:
\begin{proof}
  \begin{enumerate}
  \item $!A \lor !B, \lnot !A,
    \lnot !B \Sequent$ या क्रमवर्तीची !!a{derivation} देऊ:
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \RightLabel{\LeftR{\lnot}}
      \UnaryInf$\lnot !A, !A \fCenter$
      \doubleLine
      \UnaryInf$!A, \lnot !A, \lnot !B \fCenter$
      \Axiom$!B \fCenter !B$
      \RightLabel{\LeftR{\lnot}}
      \UnaryInf$\lnot !B, !B \fCenter$
      \doubleLine
      \UnaryInf$!B, \lnot !A, \lnot !B \fCenter$
      \RightLabel{\LeftR{\lor}}
      \BinaryInf$ !A \lor !B, \lnot !A, \lnot !B \fCenter $
    \end{prooftree}
    (दुहेरी अनुमान-रेषा दुर्बलीकरण, आकुंचन आणि अदलाबदल यांच्या अनेक अनुमानांना
    दर्शवतात, हे लक्षात ठेवा.)
  \item   $!A \Sequent !A \lor !B$ आणि $!B \Sequent !A
    \lor !B$ या दोन्ही क्रमवर्तींना !!{derivation}s आहेत:
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \RightLabel{\RightR{\lor}}
      \UnaryInf$!A \fCenter !A \lor !B$
      \DisplayProof\qquad\bottomAlignProof
      \Axiom$!B \fCenter !B$
      \RightLabel{\RightR{\lor}}
      \UnaryInf$!B \fCenter !A \lor !B$
    \end{prooftree}
  \end{enumerate}
\end{proof}

source_excerpt:
\begin{explain}
!!^a{derivation} system, such as the sequent calculus, is \emph{sound}
if it cannot !!{derive} things that do not actually hold.  Soundness is
thus a kind of guaranteed safety property for !!{derivation} systems.
Depending on which proof theoretic property is in question, we would
like to know for instance, that
\begin{enumerate}
\item every !!{derivable}~$!A$ is \iftag{FOL}{valid}{a tautology};
\item if !!a{sentence} is !!{derivable} from some others, it is also a
  consequence of them;
\item if a set of !!{sentence}s is inconsistent, it is unsatisfiable.
\end{enumerate}
These are important properties of !!a{derivation} system.  If any of
them do not hold, the !!{derivation} system is deficient---it would
!!{derive} too much.  Consequently, establishing the soundness of a
!!{derivation} system is of the utmost importance.

target_excerpt:
\begin{explain}
क्रमवर्ती कलनासारखी !!^a{derivation} पद्धत \emph{निर्दोष} असते, जर ती
प्रत्यक्षात धारण न करणाऱ्या गोष्टी !!{derive} करू शकत नसेल. त्यामुळे
निर्दोषता हा !!{derivation} पद्धतींसाठी हमी दिलेल्या सुरक्षिततेचा एक प्रकार
आहे. कोणता सिद्धता-उपपत्तीय गुणधर्म विचारात आहे यावर अवलंबून, उदाहरणार्थ,
आपल्याला पुढील गोष्टी हव्या असतात:
\begin{enumerate}
\item प्रत्येक !!{derivable}~$!A$ हे \iftag{FOL}{वैध}{सर्वतः सत्य सूत्र} असते;
\item एखादे !!a{sentence} इतर काही वाक्यांपासून !!{derivable} असेल, तर ते
  त्यांचे तार्किक परिणामही असते;
\item !!{sentence}s चा संच विसंगत असेल, तर तो अपूर्ततायोग्य असतो.
\end{enumerate}
हे !!a{derivation} पद्धतीचे महत्त्वाचे गुणधर्म आहेत. यांपैकी एखादा गुणधर्म
खरा नसेल, तर !!{derivation} पद्धतीत दोष आहे—ती खूप जास्त निष्पत्ती
!!{derive} करेल. म्हणून !!{derivation} पद्धतीची निर्दोषता सिद्ध करणे अत्यंत
महत्त्वाचे आहे.

source_excerpt:
A sequent is \emph{valid} iff every \iftag{FOL}{!!{structure}~$\Struct
  M$}{!!{valuation}~$\pAssign{v}$} satisfies it.
\end{defn}

\begin{proof}
Let $\pi$ be !!a{derivation} of $\Theta \Sequent \Xi$. We proceed by
induction on the number of inferences~$n$ in~$\pi$.

target_excerpt:
\begin{proof}
  $\Theta \Sequent \Xi$ ची !!a{derivation}~$\pi$ असू द्या. $\pi$ मधील
अनुमानांची संख्या~$n$ यावर विगमनाने पुढे जाऊ.

source_excerpt:
First, we consider the possible inferences with only one premise.
\begin{enumerate}
\item The last inference is a weakening.  Then $\Theta \Sequent \Xi$
  is either $!A, \Gamma \Sequent \Delta$ (if the last inference is
  \LeftR{\Weakening}) or $\Gamma \Sequent \Delta, !A$ (if it's
  \RightR{\Weakening}), and the !!{derivation} ends in one of
  \begin{prooftree}
    \AxiomC{}
    \Deduce$\Gamma \fCenter \Delta$
    \RightLabel{\LeftR{\Weakening}}
    \UnaryInf$!A, \Gamma \fCenter \Delta$
    \DisplayProof\qquad\bottomAlignProof
    \AxiomC{}
    \Deduce$\Gamma \fCenter \Delta$
    \RightLabel{\RightR{\Weakening}}
    \UnaryInf$\Gamma \fCenter \Delta, !A$
  \end{prooftree}
  By induction hypothesis, $\Gamma \Sequent \Delta$ is valid, i.e.,
  for every
  \iftag{FOL}{!!{structure}~$\Struct{M}$}{!!{valuation}~$\pAssign{v}$},
  either there is some $!C \in \Gamma$ such that
  $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{!C}$ or there is some $!C \in
  \Delta$ such that $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!C}$.

target_excerpt:
प्रथम, एकच आधारविधान असलेली संभाव्य अनुमाने पाहू.
\begin{enumerate}
\item शेवटचे अनुमान दुर्बलीकरण आहे. मग $\Theta \Sequent \Xi$ हे एकतर
  $!A, \Gamma \Sequent \Delta$ (शेवटचे अनुमान
  \LeftR{\Weakening} असेल) किंवा $\Gamma \Sequent \Delta, !A$ (ते
  \RightR{\Weakening} असेल), आणि !!{derivation} पुढीलपैकी एका रूपात संपते:
  \begin{prooftree}
    \AxiomC{}
    \Deduce$\Gamma \fCenter \Delta$
    \RightLabel{\LeftR{\Weakening}}
    \UnaryInf$!A, \Gamma \fCenter \Delta$
    \DisplayProof\qquad\bottomAlignProof
    \AxiomC{}
    \Deduce$\Gamma \fCenter \Delta$
    \RightLabel{\RightR{\Weakening}}
    \UnaryInf$\Gamma \fCenter \Delta, !A$
  \end{prooftree}
  विगमन गृहीतकानुसार $\Gamma \Sequent \Delta$ वैध आहे; म्हणजे प्रत्येक
  \iftag{FOL}{!!{structure}~$\Struct{M}$}{!!{valuation}~$\pAssign{v}$},
  एकतर एखादे $!C \in \Gamma$ असे आहे की
  $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{!C}$, किंवा एखादे $!C \in
  \Delta$ असे आहे की $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!C}$.

source_excerpt:
