\iftag{prvFalse,prvTrue}{पुढीलपैकी एका रूपाची क्रमवर्ती होय:
  \begin{enumerate}
    \item $!A \Sequent !A$
    \tagitem{prvTrue}{$\quad \Sequent \ltrue$}{}
    \tagitem{prvFalse}{$\lfalse \Sequent \quad$}{}
  \end{enumerate}}
{$!A \Sequent !A$ या रूपाची क्रमवर्ती होय}.
\end{defn}

