target_excerpt:
\begin{prop}[संहतता]
  \ollabel{prop:proves-compact}
  \begin{enumerate}
  \item $\Gamma \Proves !A$ असेल, तर एखादा सांत उपसंच $\Gamma_0
    \subseteq \Gamma$ असा आहे की $\Gamma_0 \Proves !A$.
  \item $\Gamma$ चा प्रत्येक सांत उपसंच सुसंगत असेल, तर $\Gamma$ सुसंगत
    असतो.
  \end{enumerate}
\end{prop}

source_excerpt:
\begin{proof}
  \begin{enumerate}
    \item If $\Gamma \Proves !A$, then there is
      !!a{derivation}~$\delta$ of~$!A$ from~$\Gamma$. Let $\Gamma_0$
      be the set of !!{undischarged} assumptions of~$\delta$.  Since
      any !!{derivation} is finite, $\Gamma_0$ can only contain
      finitely many !!{sentence}s.  So, $\delta$ is !!a{derivation}
      of~$!A$ from a finite~$\Gamma_0 \subseteq \Gamma$.
    \item This is the contrapositive of (1) for the special case $!A
      \ident \lfalse$.
  \end{enumerate}
\end{proof}

target_excerpt:
\begin{proof}
  \begin{enumerate}
    \item $\Gamma \Proves !A$ असेल, तर $\Gamma$ पासून $!A$ ची
      !!a{derivation}~$\delta$ असते. $\Gamma_0$ हा $\delta$ मधील
      !!{undischarged} गृहीतकांचा संच असू द्या. प्रत्येक !!{derivation} सांत
      असल्यामुळे $\Gamma_0$ मधील !!{sentence}s ची संख्या सांतच असते.
      म्हणून $\delta$ ही सांत~$\Gamma_0 \subseteq \Gamma$ पासून $!A$ ची
      !!a{derivation} आहे.
    \item (1) मध्ये $!A
      \ident \lfalse$ हे विशेष प्रकरण घेतल्यावर मिळणारे हे निषेधात्मक उलट
      विधान आहे.
  \end{enumerate}
\end{proof}

source_excerpt:
\begin{prop}[Transitivity]
\ollabel{prop:transitivity}
If $\Gamma \Proves !A$ and $\{!A\} \cup \Delta \Proves
!B$, then $\Gamma \cup \Delta \Proves !B$.
\end{prop}

target_excerpt:
\begin{prop}[संक्रमकता]
\ollabel{prop:transitivity}
$\Gamma \Proves !A$ आणि $\{!A\} \cup \Delta \Proves
!B$ असेल, तर $\Gamma \cup \Delta \Proves !B$.
\end{prop}

source_excerpt:
\begin{proof}
If $\Gamma \Proves !A$, there is a finite $\Gamma_0 \subseteq \Gamma$
and !!a{derivation}~$\pi_0$ of $\Gamma_0 \Sequent !A$.  If $\{!A\}
\cup \Delta \Proves !B$, then for some finite subset $\Delta_0
\subseteq \Delta$, there is !!a{derivation}~$\pi_1$ of $!A, \Delta_0
\Sequent !B$. Consider the following !!{derivation}:
\begin{prooftree}
  \AxiomC{}
  \RightLabel{$\pi_0$}
  \Deduce$\Gamma_0 \fCenter !A$
  \AxiomC{}
  \RightLabel{$\pi_1$}
  \Deduce$!A, \Delta_0 \fCenter !B$
  \RightLabel{\Cut}
  \BinaryInf$\Gamma_0, \Delta_0 \fCenter !B$
\end{prooftree}
Since $\Gamma_0 \cup \Delta_0 \subseteq \Gamma \cup \Delta$, this
shows $\Gamma \cup \Delta \Proves !B$.
\end{proof}

target_excerpt:
\begin{proof}
$\Gamma \Proves !A$ असेल, तर एखादा सांत $\Gamma_0 \subseteq \Gamma$
आणि $\Gamma_0 \Sequent !A$ ची !!a{derivation}~$\pi_0$ असते.
$\{!A\} \cup \Delta \Proves !B$ असेल, तर एखाद्या सांत उपसंचासाठी
$\Delta_0 \subseteq \Delta$, $!A, \Delta_0 \Sequent !B$ ची
!!a{derivation}~$\pi_1$ असते. पुढील !!{derivation} विचारात घ्या:
\begin{prooftree}
  \AxiomC{}
  \RightLabel{$\pi_0$}
  \Deduce$\Gamma_0 \fCenter !A$
  \AxiomC{}
  \RightLabel{$\pi_1$}
  \Deduce$!A, \Delta_0 \fCenter !B$
  \RightLabel{\Cut}
  \BinaryInf$\Gamma_0, \Delta_0 \fCenter !B$
\end{prooftree}
$\Gamma_0 \cup \Delta_0 \subseteq \Gamma \cup \Delta$ असल्यामुळे यावरून
$\Gamma \cup \Delta \Proves !B$ हे दिसते.
\end{proof}

source_excerpt:
\begin{prop}[Transitivity]
\ollabel{prop:transitivity}
If $\Gamma \Proves !A$ and $\{!A\} \cup \Delta \Proves
!B$, then $\Gamma \cup \Delta \Proves !B$.
\end{prop}

target_excerpt:
\begin{prop}[संक्रमकता]
\ollabel{prop:transitivity}
$\Gamma \Proves !A$ आणि $\{!A\} \cup \Delta \Proves
!B$ असेल, तर $\Gamma \cup \Delta \Proves !B$.
\end{prop}

source_excerpt:
\begin{proof}
If $\Gamma \Proves !A$, there is !!a{derivation}~$\delta_0$ of~$!A$
with all !!{undischarged} assumptions in~$\Gamma$.  If $\{!A\} \cup
\Delta \Proves !B$, then there is !!a{derivation}~$\delta_1$ of~$!B$
with all !!{undischarged} assumptions in~$\{!A\} \cup \Delta$.
Now consider:
\begin{prooftree}
  \AxiomC{$\Delta, \Discharge{!A}{1}$}
  \RightLabel{$\delta_1$}
  \DeduceC{$!B$}
  \DischargeRule{\Intro{\lif}}{1}
  \UnaryInfC{$!A \lif !B$}
  \AxiomC{$\Gamma$}
  \RightLabel{$\delta_0$}
  \DeduceC{$!A$}
  \RightLabel{\Elim{\lif}}
  \BinaryInfC{$!B$}
\end{prooftree}
The !!{undischarged} assumptions are now all among $\Gamma \cup
\Delta$, so this shows $\Gamma \cup \Delta \Proves !B$.
\end{proof}

target_excerpt:
\begin{proof}
$\Gamma \Proves !A$ असेल, तर $!A$ ची अशी !!a{derivation}~$\delta_0$ असते
की तिच्यातील सर्व !!{undischarged} गृहीतके $\Gamma$ मध्ये असतात. $\{!A\}
\cup \Delta \Proves !B$ असेल, तर $!B$ ची अशी !!a{derivation}~$\delta_1$
असते की तिच्यातील सर्व !!{undischarged} गृहीतके $\{!A\} \cup \Delta$ मध्ये
असतात. आता पुढील रचना विचारात घ्या:
\begin{prooftree}
  \AxiomC{$\Delta, \Discharge{!A}{1}$}
  \RightLabel{$\delta_1$}
  \DeduceC{$!B$}
  \DischargeRule{\Intro{\lif}}{1}
  \UnaryInfC{$!A \lif !B$}
  \AxiomC{$\Gamma$}
  \RightLabel{$\delta_0$}
  \DeduceC{$!A$}
  \RightLabel{\Elim{\lif}}
  \BinaryInfC{$!B$}
\end{prooftree}
आता सर्व !!{undischarged} गृहीतके $\Gamma \cup \Delta$ मध्ये आहेत; म्हणून
यावरून $\Gamma \cup \Delta \Proves !B$ हे दिसते.
\end{proof}

source_excerpt:
\begin{defn}[Theorems]
!!^a{sentence}~$!A$ is a \emph{theorem} if there is !!a{derivation}
in~$\Log{LK}$ of the sequent $\quad \Sequent !A$.  We write $\Proves
!A$ if $!A$ is a theorem and $\Proves/ !A$ if it is not.
\end{defn}

\begin{prop}[Reflexivity]
\ollabel{prop:reflexivity}
If $!A \in \Gamma$, then $\Gamma \Proves !A$.
\end{prop}

