source_excerpt:
\begin{editorial}
This chapter presents a natural deduction system in the style of
Gentzen/Prawitz.

To include or exclude material relevant to natural deduction as a
proof system, use the ``prfND'' tag.
\end{editorial}

target_excerpt:
नैसर्गिक निगमनाशी सिद्धता-पद्धती म्हणून संबंधित सामग्री समाविष्ट किंवा
वगळण्यासाठी ``prfND''`` टॅग वापरा.
\end{editorial}

source_excerpt:
\begin{defn}[Assumption]
An \emph{assumption} is any !!{sentence}
in the topmost position of any branch.
\end{defn}

\begin{prob}
Give !!{derivation}s that show the following:
\begin{enumerate}
\item $!A \land (!B \land !C) \Proves (!A \land !B) \land !C$.
\item $!A \lor (!B \lor !C) \Proves (!A \lor !B) \lor !C$.
\item $!A \lif (!B \lif !C) \Proves !B \lif (!A \lif !C)$.
\item $!A \Proves \lnot\lnot !A$.
\end{enumerate}
\end{prob}

target_excerpt:
\begin{prob}
पुढील गोष्टी दाखवणाऱ्या !!{derivation}s द्या:
\begin{enumerate}
\item $!A \land (!B \land !C) \Proves (!A \land !B) \land !C$.
\item $!A \lor (!B \lor !C) \Proves (!A \lor !B) \lor !C$.
\item $!A \lif (!B \lif !C) \Proves !B \lif (!A \lif !C)$.
\item $!A \Proves \lnot\lnot !A$.
\end{enumerate}
\end{prob}

source_excerpt:
\begin{prob}
Give !!{derivation}s that show the following:
\begin{enumerate}
\item $\Proves \lnot\lforall[x][!A(x)] \lif \lexists[x][\lnot!A(x)]$.
\item $(\lforall[x][!A(x)] \lif !B) \Proves \lexists[y][(!A(y) \lif !B)]$.
\item $\Proves \lexists[x][(!A(x) \lif \lforall[y][!A(y)])]$.
\end{enumerate}
(These all require the $\FalseCl$~rule.)
\end{prob}

target_excerpt:
\begin{prob}
पुढील गोष्टी दाखवणाऱ्या !!{derivation}s द्या:
\begin{enumerate}
\item $\Proves \lnot\lforall[x][!A(x)] \lif \lexists[x][\lnot!A(x)]$.
\item $(\lforall[x][!A(x)] \lif !B) \Proves \lexists[y][(!A(y) \lif !B)]$.
\item $\Proves \lexists[x][(!A(x) \lif \lforall[y][!A(y)])]$.
\end{enumerate}
(या सर्वांसाठी $\FalseCl$~नियम आवश्यक आहे.)
\end{prob}

source_excerpt:
\begin{editorial}
This section collects the definitions the provability relation
and consistency for natural deduction.
\end{editorial}

target_excerpt:
\begin{editorial}
या विभागात नैसर्गिक निगमनासाठी सिद्धतायोग्यता संबंध आणि सुसंगतता यांच्या
व्याख्या एकत्रित केल्या आहेत.
\end{editorial}

source_excerpt:
\begin{defn}[Theorems]
A !!{sentence}~$!A$ is a \emph{theorem} if there is !!a{derivation}
of~$!A$ in natural deduction in which all assumptions are
!!{discharged}.  We write $\Proves !A$ if $!A$ is a theorem and
$\Proves/ !A$ if it is not.
\end{defn}

\begin{prop}[Reflexivity]
\ollabel{prop:reflexivity}
If $!A \in \Gamma$, then $\Gamma \Proves !A$.
\end{prop}

target_excerpt:
\begin{prop}[परावर्तिता]
\ollabel{prop:reflexivity}
$!A \in \Gamma$ असेल, तर $\Gamma \Proves !A$.
\end{prop}

source_excerpt:
\begin{proof}
The assumption $!A$ by itself is !!a{derivation} of~$!A$ where every
!!{undischarged} assumption (i.e., $!A$) is in~$\Gamma$.
\end{proof}

target_excerpt:
\begin{proof}
केवळ $!A$ हे गृहीतक स्वतःच $!A$ ची अशी !!a{derivation} आहे की तिच्यातील
प्रत्येक !!{undischarged} गृहीतक (म्हणजे $!A$) $\Gamma$ मध्ये आहे.
\end{proof}

source_excerpt:
\begin{prop}[Monotonicity]
\ollabel{prop:monotonicity}
If $\Gamma \subseteq \Delta$ and $\Gamma \Proves !A$, then $\Delta
\Proves !A$.
\end{prop}

target_excerpt:
\begin{prop}[एकस्वनिकता]
\ollabel{prop:monotonicity}
$\Gamma \subseteq \Delta$ आणि $\Gamma \Proves !A$ असेल, तर $\Delta
\Proves !A$.
\end{prop}

source_excerpt:
\begin{proof}
Any !!{derivation} of $!A$ from $\Gamma$ is also !!a{derivation} of
$!A$ from~$\Delta$.
\end{proof}

target_excerpt:
\begin{proof}
$\Gamma$ पासून $!A$ ची कोणतीही !!{derivation} ही $\Delta$ पासून $!A$ चीही
!!a{derivation} असते.
\end{proof}

source_excerpt:
\begin{prop}[Transitivity]
\ollabel{prop:transitivity}
If $\Gamma \Proves !A$ and $\{!A\} \cup \Delta \Proves
!B$, then $\Gamma \cup \Delta \Proves !B$.
\end{prop}

target_excerpt:
\begin{prop}[संक्रमकता]
\ollabel{prop:transitivity}
$\Gamma \Proves !A$ आणि $\{!A\} \cup \Delta \Proves
!B$ असेल, तर $\Gamma \cup \Delta \Proves !B$.
\end{prop}

source_excerpt:
\begin{proof}
If $\Gamma \Proves !A$, there is !!a{derivation}~$\delta_0$ of~$!A$
with all !!{undischarged} assumptions in~$\Gamma$.  If $\{!A\} \cup
\Delta \Proves !B$, then there is !!a{derivation}~$\delta_1$ of~$!B$
with all !!{undischarged} assumptions in~$\{!A\} \cup \Delta$.
Now consider:
\begin{prooftree}
  \AxiomC{$\Delta, \Discharge{!A}{1}$}
  \RightLabel{$\delta_1$}
  \DeduceC{$!B$}
  \DischargeRule{\Intro{\lif}}{1}
  \UnaryInfC{$!A \lif !B$}
  \AxiomC{$\Gamma$}
  \RightLabel{$\delta_0$}
  \DeduceC{$!A$}
  \RightLabel{\Elim{\lif}}
  \BinaryInfC{$!B$}
\end{prooftree}
The !!{undischarged} assumptions are now all among $\Gamma \cup
\Delta$, so this shows $\Gamma \cup \Delta \Proves !B$.
\end{proof}

target_excerpt:
\begin{proof}
$\Gamma \Proves !A$ असेल, तर $!A$ ची अशी !!a{derivation}~$\delta_0$ असते
की तिच्यातील सर्व !!{undischarged} गृहीतके $\Gamma$ मध्ये असतात. $\{!A\}
\cup \Delta \Proves !B$ असेल, तर $!B$ ची अशी !!a{derivation}~$\delta_1$
असते की तिच्यातील सर्व !!{undischarged} गृहीतके $\{!A\} \cup \Delta$ मध्ये
असतात. आता पुढील रचना विचारात घ्या:
\begin{prooftree}
  \AxiomC{$\Delta, \Discharge{!A}{1}$}
  \RightLabel{$\delta_1$}
  \DeduceC{$!B$}
  \DischargeRule{\Intro{\lif}}{1}
  \UnaryInfC{$!A \lif !B$}
  \AxiomC{$\Gamma$}
  \RightLabel{$\delta_0$}
  \DeduceC{$!A$}
  \RightLabel{\Elim{\lif}}
  \BinaryInfC{$!B$}
\end{prooftree}
आता सर्व !!{undischarged} गृहीतके $\Gamma \cup \Delta$ मध्ये आहेत; म्हणून
यावरून $\Gamma \cup \Delta \Proves !B$ हे दिसते.
\end{proof}

source_excerpt:
\begin{prop}
\ollabel{prop:incons}
The following are equivalent.
    \begin{enumerate}
      \item \( \Gamma \) is inconsistent.
      \item \( \Gamma \Proves {!A} \) for every !!{sentence}~\( {!A} \).
      \item \( \Gamma \Proves {!A} \) and \( \Gamma \Proves \lnot {!A} \) for some !!{sentence}~\( {!A} \).
    \end{enumerate}
\end{prop}

target_excerpt:
\begin{prop}
\ollabel{prop:incons}
पुढील विधाने सममूल्य आहेत.
    \begin{enumerate}
      \item \( \Gamma \) विसंगत आहे.
      \item प्रत्येक !!{sentence}~\( {!A} \) साठी \( \Gamma \Proves {!A} \).
      \item एखाद्या !!{sentence}~\( {!A} \) साठी \( \Gamma \Proves {!A} \) आणि \( \Gamma \Proves \lnot {!A} \).
    \end{enumerate}
\end{prop}

source_excerpt:
\begin{proof}
Exercise.
\end{proof}

target_excerpt:
\begin{proof}
सराव.
\end{proof}

